INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Donchitos/Claude-Code-Game-Studios/team-release', 'community', 'Donchitos', 'Claude-Code-Game-Studios', 'Donchitos/Claude-Code-Game-Studios', 'team-release', 0, 0, 41, '2026-03-08T01:57:15.580Z', '2026-03-08T02:11:52.951Z', 'dd8ccc92195c4e8ecbbea7a3482ae5d8b87ba252f697a84ddff1b015a8225bde', '{"id":"Donchitos/Claude-Code-Game-Studios/team-release","name":"team-release","description":{"en":"The team-release skill automates game development studios by orchestrating release teams through a structured pipeline, utilizing subagents like release-manager and qa-lead. It benefits game developers by streamlining the development process.","zh":"Team-Release技能通过AIエージェント协同发布流程，实现游戏开发工作流的自动化","ja":"Team-Releaseスキルは、AIエージェントを使用してゲーム開発スタジオの構築を支援","ko":"Team-Release 스킬은 AI 에이전트를 활용하여 게임 개발 스튜디오의 구축을 지원","es":"Team-release es una habilidad que permite a los desarrolladores de juegos configurar un flujo de trabajo completo con 48 agentes de IA y un sistema de coordinación que simula la jerarquía de un estudio de desarrollo real","fr":"Team-release est une compétence qui permet aux développeurs de jeux de configurer un flux de travail complet avec 48 agents d''IA et un système de coordination qui simule la hiérarchie d''un studio de développement réel","de":"Team-release ist eine Fähigkeit, die es Entwicklern von Spielen ermöglicht, einen vollständigen Arbeitsablauf mit 48 KI-Agenten und einem Koordinierungssystem zu konfigurieren, das die Hierarchie eines realen Entwicklungsstudios simulierte","pt":"O Team-Release é uma habilidade que orquestra a equipe de lançamento através de um pipeline estruturado, incluindo gerenciamento de branch e versionamento","ru":"Team-Release - это навык, который оркестрирует команду выпуска через структурированный пайплайн, включая управление ветками и версиями с помощью ИИ Агентов","ar":"الفريق-الإصدار هو مهارة تؤدي إلى تنسيق فريق الإصدار من خلال خط أنابيب منظم، بما في ذلك إدارة الفروع والنسخ باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"team-release: Structured Pipeline Setup Guide | AI Agent ...","zh":"Team-Release Setup Guide: AIエージェント协同发布流程","ja":"Team-Release Best Practices: AIエージェントを使用したゲーム開発スタジオの構築","ko":"Team-Release 구축 가이드: AI 에이전트를 활용한 게임 개발 스튜디오","es":"Configuración de team-release: Guía para Devs de AI Agentes","fr":"Mise en place de team-release: Meilleures Pratiques pour ...","de":"Einrichtung von team-release: Leitfaden für Entwickler vo...","pt":"Guia de Configuração do Team-Release: Automação de Lançam...","ru":"Настройка Team-Release: Руководство по автоматизации выпу...","ar":"دليل إعداد الفريق-الإصدار: 자동化 إصدار المشاريع باستخدام أد..."},"description":{"en":"Discover how team-release orchestrates game dev studios with 48 AI agents and a complete coordination system. Learn to harness its power today!","zh":"了解Team-Release技能，如何通过AIエージェント协同发布流程，打造完整的游戏开发工作流","ja":"Team-Releaseスキルを使用して、AIエージェントを活用したゲーム開発スタジオを構築し、開発効率を向上させる","ko":"Team-Release 스킬을 통해 AI 에이전트를 활용하여 게임 개발 스튜디오를 구축하고 개발 효율을 향상시키는 방법","es":"Aprende a configurar team-release para mejorar tus flujos de trabajo de desarrollo de juegos con 48 agentes de IA y un sistema de coordinación completo","fr":"Découvrez comment configurer team-release pour améliorer vos flux de travail de développement de jeux avec 48 agents d''IA et un système de coordination complet","de":"Erfahren Sie, wie Sie team-release einrichten, um Ihre Arbeitsabläufe in der Spieleentwicklung mit 48 KI-Agenten und einem vollständigen Koordinierungssystem...","pt":"Aprenda a configurar o Team-Release para automatizar o lançamento de projetos, incluindo gerenciamento de branch, versionamento e deploy","ru":"Узнайте, как настроить Team-Release для автоматизации выпуска проектов, включая управление ветками, версиями и развертыванием с помощью ИИ Агентов","ar":"تعلم كيفية إعداد الفريق-الإصدار لتحقيق автоматизية إصدار المشاريع، بما في ذلك إدارة الفروع والنسخ والنشر باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"team-release is a skill that mirrors real studio hierarchy, utilizing 48 AI agents and 35 workflow skills to manage game development pipelines.","zh":"Team-Release是通过AIエージェント协同发布流程的技能，用于游戏开发工作流的自动化","ja":"Team-Releaseは、AIエージェントを使用したゲーム開発スタジオの構築を支援するスキル","ko":"Team-Release는 AI 에이전트를 활용하여 게임 개발 스튜디오의 구축을 지원하는 스킬","es":"Team-release es una habilidad de AI que permite la configuración de un flujo de trabajo de desarrollo de juegos","fr":"Team-release est une compétence d''IA qui permet la configuration d''un flux de travail de développement de jeux","de":"Team-release ist eine KI-Fähigkeit, die die Konfiguration eines Arbeitsablaufs in der Spieleentwicklung ermöglicht","pt":"O Team-Release é uma habilidade de automação de lançamento de projetos que utiliza um pipeline estruturado","ru":"Team-Release - это навык автоматизации выпуска проектов, который использует структурированный пайплайн с ИИ Агентами","ar":"الفريق-الإصدار هو مهارة لتحقيق自动اتية إصدار المشاريع التي تستخدم خط أنابيب منظم مع أدوات الذكاء الاصطناعي"},"features":{"en":["Orchestrates release teams through a structured pipeline","Utilizes subagents like release-manager for release branch and versioning","Employs qa-lead for testing and quality assurance","Captures user decisions with concise labels using AskUserQuestion","Writes agent''s full analysis in conversation for transparency"],"zh":["通过AskUserQuestion实现决策点","支持release-manager和qa-lead子代理","实现版本控制、变更日志和部署","提供结构化的发布流程","支持多个AI代理的协同工作"],"ja":["AskUserQuestionを使用した意思決定ポイント","release-managerとqa-leadサブエージェントのサポート","バージョン管理、変更ログ、デプロイの実装","構造化されたリリースフロー","複数のAIエージェントの共同作業のサポート"],"ko":["AskUserQuestion을 통한 의사결정 점","release-manager와 qa-lead 서브 에이전트 지원","버전 관리, 변경 로그, 배포 구현","구조화된 릴리즈 흐름","複数의 AI 에이전트의 협업 지원"],"es":["Orquestación de un flujo de trabajo estructurado con 48 agentes de IA","Sistema de coordinación que simula la jerarquía de un estudio de desarrollo real","Uso de AskUserQuestion para presentar propuestas de subagentes como opciones seleccionables","Captura de decisiones con etiquetas concisas","Aprobación del usuario antes de pasar a la siguiente fase"],"fr":["Orchestration d''un flux de travail structuré avec 48 agents d''IA","Système de coordination qui simule la hiérarchie d''un studio de développement réel","Utilisation de AskUserQuestion pour présenter les propositions des sous-agents comme options sélectionnables","Capture des décisions avec des étiquettes concises","Approbation de l''utilisateur avant de passer à la phase suivante"],"de":["Orchestrierung eines strukturierten Arbeitsablaufs mit 48 KI-Agenten","Koordinierungssystem, das die Hierarchie eines realen Entwicklungsstudios simulierte","Verwendung von AskUserQuestion, um Vorschläge von Subagenten als auswählbare Optionen darzustellen","Erfassung von Entscheidungen mit knappen Labels","Genehmigung des Benutzers vor dem Übergang zur nächsten Phase"],"pt":["Orquestração da equipe de lançamento através de um pipeline estruturado","Gerenciamento de branch e versionamento","Uso de AskUserQuestion para apresentar propostas de subagentes","Escrita da análise completa do agente em conversa","Captação de decisões com rótulos concisos"],"ru":["Оркестрирование команды выпуска через структурированный пайплайн с ИИ Агентами","Управление ветками и версиями","Использование AskUserQuestion для представления предложений субагентов","Написание полного анализа агента в разговоре","Захват решений с краткими метками"],"ar":["تنسيق فريق الإصدار من خلال خط أنابيب منظم مع أدوات الذكاء الاصطناعي","إدارة الفروع والنسخ","استخدام AskUserQuestion لتقديم مقترحات من الوكلاء الفرعيين","كتابة تحليل كامل للوكيل في المحادثة","التقاط القرارات مع علامات موجزة"]},"keywords":{"en":["how to use team-release","team-release setup guide","game development pipeline management","team-release alternative","team-release vs competing game dev tools","what is team-release","team-release install","structured pipeline for game development"],"zh":["AIエージェント","游戏开发工作流","Team-Release技能","发布流程","版本控制","变更日志","部署","AskUserQuestion","release-manager","qa-lead"],"ja":["AIエージェント","ゲーム開発スタジオ","Team-Releaseスキル","リリースフロー","バージョン管理","変更ログ","デプロイ","AskUserQuestion","release-manager","qa-lead"],"ko":["AI 에이전트","게임 개발 스튜디오","Team-Release 스킬","릴리즈 흐름","버전 관리","변경 로그","배포","AskUserQuestion","release-manager","qa-lead"],"es":["team-release","AI Agentes","desarrollo de juegos","flujo de trabajo","sistema de coordinación","AskUserQuestion","etiquetas concisas","aprobación del usuario"],"fr":["team-release","Outils d''IA","développement de jeux","flux de travail","système de coordination","AskUserQuestion","étiquettes concises","approbation de l''utilisateur"],"de":["team-release","KI-Tools","Spieleentwicklung","Arbeitsablauf","Koordinierungssystem","AskUserQuestion","knappe Labels","Benutzer genehmigung"],"pt":["Team-Release","automação de lançamento de projetos","gerenciamento de branch","versionamento","pipeline estruturado","AskUserQuestion","análise de agente","decisões concisas"],"ru":["Team-Release","автоматизация выпуска проектов","управление ветками","версиями","структурированный пайплайн","AskUserQuestion","анализ агента","решения с краткими метками","ИИ Агенты"],"ar":["الفريق-الإصدار","تحقيق 자동اتية إصدار المشاريع","إدارة الفروع","النسخ","خط أنابيب منظم","AskUserQuestion","تحليل الوكيل","القرارات الموجزة","أدوات الذكاء الاصطناعي"]}},"owner":"Donchitos","repo":"Claude-Code-Game-Studios","repoPath":"Donchitos/Claude-Code-Game-Studios","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.580Z","topics":[],"category":"community","skillMd":{"name":"team-release","description":"Orchestrate the release team: coordinates release-manager, qa-lead, devops-engineer, and producer to execute a release from candidate to deployment.","bodyPreview":"When this skill is invoked, orchestrate the release team through a structured pipeline.\n\n**Decision Points:** At each phase transition, use `AskUserQuestion` to present\nthe user with the subagent''s proposals as selectable options. Write the agent''s\nfull analysis in conversation, then capture the decision with concise labels.\nThe user must approve before moving to the next phase.\n\n## Team Composition\n- **release-manager** — Release branch, versioning, changelog, deployment\n- **qa-lead** — Test si","body":"When this skill is invoked, orchestrate the release team through a structured pipeline.\n\n**Decision Points:** At each phase transition, use `AskUserQuestion` to present\nthe user with the subagent''s proposals as selectable options. Write the agent''s\nfull analysis in conversation, then capture the decision with concise labels.\nThe user must approve before moving to the next phase.\n\n## Team Composition\n- **release-manager** — Release branch, versioning, changelog, deployment\n- **qa-lead** — Test sign-off, regression suite, release quality gate\n- **devops-engineer** — Build pipeline, artifacts, deployment automation\n- **producer** — Go/no-go decision, stakeholder communication, scheduling\n\n## How to Delegate\n\nUse the Task tool to spawn each team member as a subagent:\n- `subagent_type: release-manager` — Release branch, versioning, changelog, deployment\n- `subagent_type: qa-lead` — Test sign-off, regression suite, release quality gate\n- `subagent_type: devops-engineer` — Build pipeline, artifacts, deployment automation\n- `subagent_type: producer` — Go/no-go decision, stakeholder communication\n\nAlways provide full context in each agent''s prompt (version number, milestone status, known issues). Launch independent agents in parallel where the pipeline allows it (e.g., Phase 3 agents can run simultaneously).\n\n## Pipeline\n\n### Phase 1: Release Planning\nDelegate to **producer**:\n- Confirm all milestone acceptance criteria are met\n- Identify any scope items deferred from this release\n- Set the target release date and communicate to team\n- Output: release authorization with scope confirmation\n\n### Phase 2: Release Candidate\nDelegate to **release-manager**:\n- Cut release branch from the agreed commit\n- Bump version numbers in all relevant files\n- Generate the release checklist using `/release-checklist`\n- Freeze the branch — no feature changes, bug fixes only\n- Output: release branch name and checklist\n\n### Phase 3: Quality Gate (parallel)\nDelegate in parallel:\n- **qa-lead**: Execute full regression test suite. Test all critical paths. Verify no S1/S2 bugs. Sign off on quality.\n- **devops-engineer**: Build release artifacts for all target platforms. Verify builds are clean and reproducible. Run automated tests in CI.\n\n### Phase 4: Localization and Performance\nDelegate (can run in parallel with Phase 3 if resources available):\n- Verify all strings are translated (delegate to localization-lead if available)\n- Run performance benchmarks against targets (delegate to performance-analyst if available)\n- Output: localization and performance sign-off\n\n### Phase 5: Go/No-Go\nDelegate to **producer**:\n- Collect sign-off from: qa-lead, release-manager, devops-engineer, technical-director\n- Evaluate any open issues — are they blocking or can they ship?\n- Make the go/no-go call\n- Output: release decision with rationale\n\n### Phase 6: Deployment (if GO)\nDelegate to **release-manager** + **devops-engineer**:\n- Tag the release in version control\n- Generate changelog using `/changelog`\n- Deploy to staging for final smoke test\n- Deploy to production\n- Monitor for 48 hours post-release\n\n### Phase 7: Post-Release\n- **release-manager**: Generate release report (what shipped, what was deferred, metrics)\n- **producer**: Update milestone tracking, communicate to stakeholders\n- **qa-lead**: Monitor incoming bug reports for regressions\n- Schedule post-release retrospective if issues occurred\n\n## Output\nA summary report covering: release version, scope, quality gate results, go/no-go decision, deployment status, and monitoring plan.\n"},"lastSynced":"2026-03-08T02:11:52.951Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring structured game development pipelines and release team orchestration.","zh":"适合需要结构化游戏开发流水线和发布团队编排的项目管理代理。","ja":"構造化されたゲーム開発パイプラインとリリースチームのオーケストレーションを必要とするプロジェクト管理エージェントに最適です。","ko":"구조화된 게임 개발 파이프라인과 릴리스 팀 오케스트레이션이 필요한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de proyectos que requieren pipelines de desarrollo de juegos estructurados y orquestación de equipo de lanzamiento.","fr":"Idéal pour les agents de gestion de projet nécessitant des pipelines de développement de jeux structurés et une orchestration d''équipe de lancement.","de":"Ideal für Projektmanagement-Agenten, die strukturierte Spielentwicklungs-Pipelines und Release-Team-Orchestrierung erfordern.","pt":"Ideal para Agentes de Gerenciamento de Projetos que exigem pipelines de desenvolvimento de jogos estruturados e orquestração de equipe de lançamento.","ru":"Идеально для Агентов Управления Проектами, требующих структурированных игровых конвейеров разработки и оркестровки команды выпуска.","ar":"مثالي لعميل إدارة المشاريع الذي يتطلب خطوط أنابيب تطوير ألعاب منظمة وتحكم فريق الإصدار."},"recommendation":{"en":"Empowers agents to streamline game development through automated pipelines, utilizing subagents like release-manager for versioning and deployment, and qa-lead for testing, all while ensuring user approval at each phase transition via AskUserQuestion protocol.","zh":"赋予代理人通过自动化流水线简化游戏开发的能力，利用诸如release-manager的版本控制和部署，和qa-lead进行测试，并在每个阶段转换时通过AskUserQuestion协议确保用户批准。","ja":"リリースマネージャーのバージョニングとデプロイ、およびQAリードのテストなどのサブエージェントを使用して、自動化されたパイプラインを通じてゲーム開発を効率化する機能をエージェントに与え、さらにAskUserQuestionプロトコルを通じて各フェーズ遷移時にユーザーの承認を確保します。","ko":"릴리스 관리자의 버저닝 및 배포, 및 QA 리드의 테스트와 같은 서브 에이전트를 사용하여 자동화된 파이프라인을 통해 게임 개발을 간소화하는 기능을 에이전트에 부여하며, 추가로 AskUserQuestion 프로토콜을 통해 각 단계 전환 시에 사용자 승인을 보장합니다.","es":"Habilita a los agentes a optimizar el desarrollo de juegos a través de pipelines automatizados, utilizando subagentes como release-manager para la versión y la implementación, y qa-lead para las pruebas, asegurando la aprobación del usuario en cada transición de fase a través del protocolo AskUserQuestion.","fr":"Permet aux agents de rationaliser le développement de jeux grâce à des pipelines automatisés, en utilisant des sous-agents comme release-manager pour la version et le déploiement, et qa-lead pour les tests, en assurant l''approbation de l''utilisateur à chaque transition de phase via le protocole AskUserQuestion.","de":"Ermächtigt die Agenten, die Spielentwicklung durch automatisierte Pipelines zu optimieren, indem Subagenten wie release-manager für Versionierung und Deployment und qa-lead für Tests verwendet werden, während die Benutzerfreigabe bei jedem Phasenübergang über das AskUserQuestion-Protokoll sichergestellt wird.","pt":"Habilita agentes a simplificar o desenvolvimento de jogos por meio de pipelines automatizados, utilizando subagentes como release-manager para versionamento e implantação, e qa-lead para testes, garantindo a aprovação do usuário em cada transição de fase via protocolo AskUserQuestion.","ru":"Наделяет агентов возможностью упростить разработку игр посредством автоматизированных конвейеров, используя субагентов, таких как release-manager для версионирования и развертывания, и qa-lead для тестирования, обеспечивая одобрение пользователя на каждом этапе перехода через протокол AskUserQuestion.","ar":"يتوفر لعميل تمكينه من تبسيط تطوير الألعاب من خلال خطوط أنابيب أوتوماتيكية، باستخدام وكلاء فرعيين مثل release-manager لVERSION و النشر، و qa-lead للاختبار، مع ضمان موافقة المستخدم في كل انتقال مرحلي عبر بروتوكول AskUserQuestion."},"useCases":{"en":["Orchestrating release teams through structured pipelines","Automating game development workflows with subagents","Streamlining deployment and changelog management"],"zh":["通过结构化的流水线编排发布团队","使用子代理自动化游戏开发工作流","简化部署和变更日志管理"],"ja":["構造化されたパイプラインを通じてリリースチームのオーケストレーション","サブエージェントを使用したゲーム開発ワークフローの自動化","デプロイと変更ログ管理の効率化"],"ko":["구조화된 파이프라인을 통해 릴리스 팀의 오케스트레이션","서브 에이전트를 사용한 게임 개발 워크플로의 자동화","배포 및 변경 로그 관리의 간소화"],"es":["Orquestar equipos de lanzamiento a través de pipelines estructurados","Automatizar flujos de trabajo de desarrollo de juegos con subagentes","Optimizar la implementación y la gestión de registros de cambios"],"fr":["Orchestrer les équipes de lancement à travers des pipelines structurés","Automatiser les flux de travail de développement de jeux avec des sous-agents","Rationaliser le déploiement et la gestion des journaux des modifications"],"de":["Orchestrieren von Release-Teams durch strukturierte Pipelines","Automatisieren von Spielentwicklungs-Workflows mit Subagenten","Optimieren von Deployment und Änderungsprotokoll-Management"],"pt":["Orquestração de equipes de lançamento por meio de pipelines estruturados","Automação de fluxos de trabalho de desenvolvimento de jogos com subagentes","Simplificação da implantação e gestão de changelog"],"ru":["Оркестровка команд выпуска посредством структурированных конвейеров","Автоматизация рабочих процессов разработки игр с субагентами","Упрощение развертывания и управления журналом изменений"],"ar":["توجيه فرق الإصدار من خلال خطوط أنابيب منظمة","أتمتة تدفقات عمل تطوير الألعاب مع وكلاء فرعيين","تبسيط الإصدار وإدارة سجل التغييرات"]},"limitations":{"en":["Requires user approval at each phase transition","Specifically designed for game development studios"],"zh":["需要在每个阶段转换时获得用户批准","专门为游戏开发工作室设计"],"ja":["各フェーズ遷移時にユーザーの承認が必要","ゲーム開発スタジオ専用に設計"],"ko":["각 단계 전환 시에 사용자 승인이 필요","게임 개발 스튜디오 전용으로 설계"],"es":["Requiere aprobación del usuario en cada transición de fase","Diseñado específicamente para estudios de desarrollo de juegos"],"fr":["Nécessite l''approbation de l''utilisateur à chaque transition de phase","Conçu spécifiquement pour les studios de développement de jeux"],"de":["Benutzerfreigabe bei jedem Phasenübergang erforderlich","Speziell für Spielentwicklungsstudios konzipiert"],"pt":["Exige aprovação do usuário em cada transição de fase","Especificamente projetado para estúdios de desenvolvimento de jogos"],"ru":["Требует одобрения пользователя на каждом этапе перехода","Специально разработан для игровых разработчиков"],"ar":["يتطلب موافقة المستخدم في كل انتقال مرحلي","صممت خصيصا لأستوديوهات تطوير الألعاب"]},"version":4},"contentHash":"dd8ccc92195c4e8ecbbea7a3482ae5d8b87ba252f697a84ddff1b015a8225bde","qualityScore":41}');
