INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Donchitos/Claude-Code-Game-Studios/team-release', 'team-release', 'Donchitos', 'Claude-Code-Game-Studios', 'community', 'team-release Donchitos Claude-Code-Game-Studios community The team-release skill automates game development studios by orchestrating release teams through a structured pipeline, utilizing subagents like release-manager and qa-lead. It benefits game developers by streamlining the development process. Team-Release技能通过AIエージェント协同发布流程，实现游戏开发工作流的自动化 Team-Releaseスキルは、AIエージェントを使用してゲーム開発スタジオの構築を支援 Team-Release 스킬은 AI 에이전트를 활용하여 게임 개발 스튜디오의 구축을 지원 Team-release es una habilidad que permite a los desarrolladores de juegos configurar un flujo de trabajo completo con 48 agentes de IA y un sistema de coordinación que simula la jerarquía de un estudio de desarrollo real Team-release est une compétence qui permet aux développeurs de jeux de configurer un flux de travail complet avec 48 agents d''IA et un système de coordination qui simule la hiérarchie d''un studio de développement réel Team-release ist eine Fähigkeit, die es Entwicklern von Spielen ermöglicht, einen vollständigen Arbeitsablauf mit 48 KI-Agenten und einem Koordinierungssystem zu konfigurieren, das die Hierarchie eines realen Entwicklungsstudios simulierte O Team-Release é uma habilidade que orquestra a equipe de lançamento através de um pipeline estruturado, incluindo gerenciamento de branch e versionamento Team-Release - это навык, который оркестрирует команду выпуска через структурированный пайплайн, включая управление ветками и версиями с помощью ИИ Агентов الفريق-الإصدار هو مهارة تؤدي إلى تنسيق فريق الإصدار من خلال خط أنابيب منظم، بما في ذلك إدارة الفروع والنسخ باستخدام أدوات الذكاء الاصطناعي how to use team-release team-release setup guide game development pipeline management team-release alternative team-release vs competing game dev tools what is team-release team-release install structured pipeline for game development AIエージェント 游戏开发工作流 Team-Release技能 发布流程 版本控制 变更日志 部署 AskUserQuestion release-manager qa-lead Orchestrates release teams through a structured pipeline Utilizes subagents like release-manager for release branch and versioning Employs qa-lead for testing and quality assurance Captures user decisions with concise labels using AskUserQuestion Writes agent''s full analysis in conversation for transparency team-release is a skill that mirrors real studio hierarchy, utilizing 48 AI agents and 35 workflow skills to manage game development pipelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('doron-nazaretsky/john-bryce/plan-course-materials', 'community', 'doron-nazaretsky', 'john-bryce', 'doron-nazaretsky/john-bryce', 'plan-course-materials', 0, 0, 41, '2026-03-08T01:57:15.590Z', '2026-03-08T02:12:32.254Z', '44722e810554217952bdb1d5779d8fbf4ed01c2fab2919684c0b282f1a98d876', '{"id":"doron-nazaretsky/john-bryce/plan-course-materials","name":"plan-course-materials","description":{"en":"The plan-course-materials skill helps instructors create comprehensive course plans by gathering intent and covering key aspects such as scope, depth, and industry context. It benefits educators and course creators.","zh":"课程材料规划涉及范围、深度、内部机制和行业背景等方面的考虑，帮助您创建有效的课程","ja":"コース資料計画には、範囲、深さ、内部メカニズム、業界背景などを考慮して効果的なコースを作成する","ko":"코스 자료 계획은 범위, 깊이, 내부 메커니즘, 산업 배경 등을 고려하여 효과적인 코스를 생성하는 것을 포함합니다","es":"Planifica materiales de curso con nuestro agente de IA, considerando alcance, profundidad e internos para crear lecciones óptimas.","fr":"Planifiez des matériaux de cours avec nos outils d''IA, en tenant compte de la portée, de la profondeur et des internes pour créer des leçons optimales.","de":"Planen Sie Kursmaterialien mit unseren KI-Tools, indem Sie Umfang, Tiefe und Interna berücksichtigen, um optimale Lektionen zu erstellen.","pt":"Planeje materiais de curso personalizados com nossa ferramenta de IA, considerando fatores como escopo, profundidade e contexto","ru":"Спланируйте индивидуальные материалы курса с помощью нашего ИИ Агента, учитывая такие факторы, как объем, глубина и контекст","ar":"احضَر مواد الدورة المخصصة باستخدام أداة الذكاء الاصطناعي لدينا، مع考虑 عوامل مثل النطاق والعمق والسياق"},"seo":{"title":{"en":"plan-course-materials: Course Planning Setup Guide | AI A...","zh":"课程材料规划设置指南 - AIエージェント","ja":"コース資料計画ベストプラクティス - AIエージェント","ko":"코스 자료 계획 가이드 - AI 에이전트","es":"Guía de configuración de materiales de curso con Agentes ...","fr":"Guide de mise en place de matériel de cours avec Outils d''IA","de":"Einrichtungsleitfaden für Kursmaterialien mit KI-Tools","pt":"Guia de Configuração de Materiais de Curso com Ferramenta...","ru":"Настройка материалов курса с помощью ИИ Агентов","ar":"دليل إعداد مواد الدورة باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to effectively plan course materials with our AI agent skill, covering scope, depth, internals, context, and industry insights - get started now!","zh":"了解如何规划课程材料，包括范围、深度、内部机制和行业背景等方面的考虑","ja":"コース資料の計画方法を学び、範囲、深さ、内部メカニズム、業界背景などを考慮する","ko":"코스 자료 계획 방법을 알아보세요. 범위, 깊이, 내부 메커니즘, 산업 배경 등을 고려합니다","es":"Aprende a planificar materiales de curso con nuestro agente de IA. Optimiza tus lecciones con preguntas clave sobre alcance, profundidad e internos.","fr":"Découvrez comment planifier des matériaux de cours avec nos outils d''IA. Optimisez vos leçons avec des questions clés sur la portée, la profondeur et les int...","de":"Erfahren Sie, wie Sie Kursmaterialien mit unseren KI-Tools planen. Optimieren Sie Ihre Lektionen mit Schlüsselfragen zu Umfang, Tiefe und Interna.","pt":"Aprenda a planejar materiais de curso eficazes com nosso guia de configuração de ferramentas de IA, incluindo definição de escopo, profundidade e contexto","ru":"Узнайте, как спланировать эффективные материалы курса с помощью нашего руководства по настройке ИИ Агентов, включая определение объема, глубины и контекста","ar":"تعلم كيفية تحضير مواد الدورة بشكل فعال مع دليلنا لإعداد أدوات الذكاء الاصطناعي، بما في ذلك تحديد النطاق والعمق والسياق"},"definition":{"en":"plan-course-materials is a skill that assists in creating course plans by asking questions about scope, depth, internals, context, and industry to gather instructor intent","zh":"课程材料规划是指为创建有效的课程而进行的规划和设计过程","ja":"コース資料計画とは、効果的なコースを作成するための計画と設計プロセス","ko":"코스 자료 계획은 효과적인 코스를 생성하기 위한 계획 및 설계 프로세스입니다","es":"Planificar materiales de curso es el proceso de definir el alcance, profundidad e internos de una lección para crear un plan de estudios efectivo.","fr":"La planification de matériel de cours est le processus de définition de la portée, de la profondeur et des internes d''une leçon pour créer un plan d''études efficace.","de":"Die Planung von Kursmaterialien ist der Prozess der Definition von Umfang, Tiefe und Interna einer Lektion, um einen effektiven Lehrplan zu erstellen.","pt":"Planejamento de materiais de curso é o processo de definição do escopo, profundidade e contexto de um curso, utilizando ferramentas de IA para personalizar o conteúdo","ru":"Планирование материалов курса - это процесс определения объема, глубины и контекста курса, использующий ИИ Агенты для персонализации содержания","ar":"تخطيط مواد الدورة هو عملية تحديد النطاق والعمق والسياق للدورة، باستخدام أدوات الذكاء الاصطناعي لتحضير المحتوى بشكل مخصص"},"features":{"en":["Asks questions about scope to determine topic and lecture duration","Assesses depth to identify what to cover deeply, briefly, or skip entirely","Evaluates internals to balance ''how it works under the hood'' with practical usage","Considers context to determine historical context and related tools","Examines industry to identify related tools, CI/CD integration, and cloud patterns"],"zh":["范围规划：确定主题、讲座时长、实践与理论平衡","深度规划：决定哪些内容需要深入覆盖、哪些内容需要简要提及、哪些内容可以跳过","内部机制：确定如何平衡‘如何工作’和实际使用","行业背景：确定历史背景、相关工具、CI/CD集成、云模式、团队工作等方面的考虑"],"ja":["範囲計画：トピック、レクチャー時間、実践と理論のバランスを決定","深さ計画：どの内容を深く掘り下げるか、どの内容を簡単に触れるか、どの内容を省略するかを決定","内部メカニズム：‘どのように動作するか’と実践使用のバランスを決定","業界背景：歴史的背景、関連ツール、CI/CD統合、クラウドパターン、チームワークなどを考慮"],"ko":["범위 계획: 주제, 강의 시간, 실습과 이론의 균형을 결정","깊이 계획: 어떤 내용을 깊이 다루는지, 어떤 내용을 간단히 언급하는지, 어떤 내용을 생략하는지 결정","내부 메커니즘: ‘어떻게 작동하는지’와 실제 사용의 균형을 결정","산업 배경: 역사적 배경, 관련 도구, CI/CD 통합, 클라우드 패턴, 팀 작업 등을 고려"],"es":["Definir el alcance de la lección","Determinar la profundidad de la cobertura","Establecer el equilibrio entre teoría y práctica","Considerar el contexto histórico","Integrar herramientas y patrones de la industria"],"fr":["Définir la portée de la leçon","Déterminer la profondeur de la couverture","Établir l''équilibre entre théorie et pratique","Considérer le contexte historique","Intégrer des outils et des modèles de l''industrie"],"de":["Umfang der Lektion definieren","Tiefe der Abdeckung bestimmen","Theorie-Praxis-Gleichgewicht herstellen","Historischer Kontext berücksichtigen","Integration von Branchen-Tools und -Mustern"],"pt":["Definição de escopo e duração da aula","Determinação da profundidade e do equilíbrio entre teoria e prática","Análise do contexto e da história do assunto","Integração com ferramentas de CI/CD e padrões de nuvem","Customização do conteúdo de acordo com as necessidades do instrutor"],"ru":["Определение объема и продолжительности лекции","Определение глубины и баланса между теорией и практикой","Анализ контекста и истории предмета","Интеграция с инструментами CI/CD и облачными шаблонами","Пользовательская настройка содержания в соответствии с потребностями преподавателя"],"ar":["تحديد النطاق ومدة الدرس","تحديد العمق والتوازن بين النظرية والتطبيق","تحليل السياق والتاريخ المادة","التكامل مع أدوات CI/CD ونمطيات السحاب","تحضير المحتوى بشكل مخصص وفقًا لاحتياجات المعلم"]},"keywords":{"en":["how to plan course materials","what is plan-course-materials","plan-course-materials alternative","plan-course-materials setup guide","plan-course-materials install","course planning best practices","course material creation tools","education technology solutions"],"zh":["课程材料规划","AIエージェント","范围规划","深度规划","内部机制","行业背景","课程设计","教育技术"],"ja":["コース資料計画","AIエージェント","範囲計画","深さ計画","内部メカニズム","業界背景","コース設計","教育技術"],"ko":["코스 자료 계획","AI 에이전트","범위 계획","깊이 계획","내부 메커니즘","산업 배경","코스 설계","교육 기술"],"es":["planificar materiales de curso","agente de IA para educación","herramientas de IA para profesores","creación de planes de estudios","lecciones personalizadas","educación con tecnología"],"fr":["planifier des matériaux de cours","outils d''IA pour l''éducation","agent d''IA pour les enseignants","création de plans d''études","leçons personnalisées","éducation avec technologie"],"de":["Kursmaterialien planen","KI-Tools für Bildung","KI-Agent für Lehrer","Lehrplanerstellung","individualisierte Lektionen","Bildung mit Technologie"],"pt":["planejamento de materiais de curso","ferramentas de ia para educação","configuração de cursos personalizados","desenvolvimento de materiais de aprendizado","tecnologias de aprendizado","educação com ia"],"ru":["планирование материалов курса","инструменты ИИ для образования","настройка индивидуальных курсов","разработка материалов для обучения","технологии обучения","образование с ИИ"],"ar":["تخطيط مواد الدورة","أدوات الذكاء الاصطناعي للتعليم","إعداد الدورات المخصصة","تحضير مواد التعلم","تقنيات التعلم","التعليم بالذكاء الاصطناعي"]}},"owner":"doron-nazaretsky","repo":"john-bryce","repoPath":"doron-nazaretsky/john-bryce","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.590Z","topics":[],"category":"community","skillMd":{"name":"plan-course-materials","description":"Plan data engineering course materials for new lessons. Use when creating materials for new topics, planning lectures, or when the user asks to plan course content, lesson materials, or lecture structure.","bodyPreview":"# Plan Course Materials\n\nBefore creating a plan, gather the instructor''s intent by asking about:\n\n## Questions to Ask\n\n1. **Scope**: Topic, lecture duration, practical vs theory balance\n2. **Depth**: What to cover deeply, what to mention briefly, what to skip entirely\n3. **Internals**: How much \"how it works under the hood\" vs practical usage\n4. **Context**: Historical context needed? What existed before this tool/concept?\n5. **Industry**: Related tools, CI/CD integration, cloud patterns, team w","body":"# Plan Course Materials\n\nBefore creating a plan, gather the instructor''s intent by asking about:\n\n## Questions to Ask\n\n1. **Scope**: Topic, lecture duration, practical vs theory balance\n2. **Depth**: What to cover deeply, what to mention briefly, what to skip entirely\n3. **Internals**: How much \"how it works under the hood\" vs practical usage\n4. **Context**: Historical context needed? What existed before this tool/concept?\n5. **Industry**: Related tools, CI/CD integration, cloud patterns, team workflows to mention\n6. **Exercises**: Type of hands-on practice -- demos, guided exercises, open-ended challenges\n7. **Lab environment**: Does the lesson need sidecar services? Check existing `labs/*/` directories first.\n8. **Audience**: What students already know, what IDE/OS they use\n9. **Style**: Any specific tone, format, or emphasis preferences\n\nDon''t ask all at once -- group naturally and ask follow-ups based on answers.\n\n## Plan Output\n\nCreate a `.cursor/plans/` file containing:\n\n- **YAML frontmatter** with `name`, `overview`, granular `todos` (one per file/folder to create), `isProject: false`\n- **Folder structure** -- full directory tree of all files to create\n- **Content outline per file** -- bullet points of what each file covers, with estimated line count\n- **Time allocation table** -- how lecture time maps to sections\n- **Lab environment** -- which lab to use (or \"none\" if lesson uses only SQLite/stdlib)\n\n## Material Standards\n\n- Files go under `materials/[topic]/` with a `README.md` entry point\n- Numbered folders (`01-introduction/`) and files (`01-topic-name.md`)\n- Max ~300 lines per `.md` file; split large subjects into smaller files\n- Exercises grouped at the end\n- Include runnable demo code in a `demo-app/` folder when applicable\n\nCode format and lab conventions are defined in the cursor rules (`.cursor/rules/content-format.mdc` and `.cursor/rules/lab-environment.mdc`). Follow those when implementing.\n\n## Examples and Code\n\nExamples should be simple and easy to follow, but mimic real-life usage patterns. Students should see how things actually look in practice without getting lost in complexity.\n\n## After Planning\n\nAsk if the instructor wants to adjust anything before starting implementation.\n"},"lastSynced":"2026-03-08T02:12:32.254Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing comprehensive course planning capabilities with scope, depth, and industry context analysis.","zh":"非常适合需要全面课程规划能力的教育代理，包括范围、深度和行业背景分析。","ja":"教育エージェントが包括的なコースプランニング機能を必要とする場合に最適です。スコープ、深度、業界コンテキスト分析が含まれます。","ko":"포괄적인 과정 계획 기능이 필요한 교육 에이전트에게 적합합니다. 범위, 깊이 및 산업 컨텍스트 분석이 포함됩니다.","es":"Perfecto para Agentes Educativos que necesitan capacidades de planificación de cursos comprehensivas con alcance, profundidad y análisis de contexto industrial.","fr":"Parfait pour les Agents Éducatifs ayant besoin de capacités de planification de cours complètes avec portée, profondeur et analyse de contexte industriel.","de":"Perfekt für Bildungsagenten, die umfassende Kursplanungsfunktionen mit Umfang, Tiefe und Branchenkontextanalyse benötigen.","pt":"Perfeito para Agentes Educacionais que precisam de capacidades de planejamento de cursos abrangentes com escopo, profundidade e análise de contexto da indústria.","ru":"Идеально для образовательных агентов, которым требуются всесторонние возможности планирования курсов с объемом, глубиной и анализом контекста отрасли.","ar":"مثالي لوسائل التعليم التي تحتاج إلى قدرات تخطيط دورات شاملة مع نطاق وعمق وتحليل سياق الصناعة."},"recommendation":{"en":"Empowers agents to create structured course materials by analyzing instructor intent, covering key aspects such as topic scope, lecture duration, and practical vs theory balance, while considering industry context and historical background, utilizing protocols like CI/CD integration and cloud patterns.","zh":"通过分析讲师意图，涵盖主题范围、讲座时长、实践与理论平衡等关键方面，同时考虑行业背景和历史背景，利用CI/CD集成和云模式等协议，赋予代理创建结构化课程材料的能力。","ja":"講師の意図を分析し、トピックの範囲、講義の期間、実践と理論のバランスなどの重要な側面をカバーし、業界の背景と歴史的背景を考慮し、CI/CD統合やクラウドパターンなどのプロトコルを利用して、エージェントが構造化されたコース資料を作成する能力を付与します。","ko":"강사 의도를 분석하고 주제 범위, 강의 기간, 실습과 이론의 균형 등의 주요 측면을 커버하며, 산업 배경과 역사적 배경을 고려하고 CI/CD 통합 및 클라우드 패턴 등의 프로토콜을 활용하여 에이전트가 구조화된 과정 자료를 생성할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a crear materiales de curso estructurados analizando la intención del instructor, cubriendo aspectos clave como el alcance del tema, la duración de la conferencia y el equilibrio entre teoría y práctica, considerando el contexto industrial y el trasfondo histórico, utilizando protocolos como la integración de CI/CD y patrones en la nube.","fr":"Permet aux agents de créer des matériels de cours structurés en analysant l''intention de l''instructeur, en couvrant les aspects clés tels que la portée du sujet, la durée de la conférence et l''équilibre entre théorie et pratique, en considérant le contexte industriel et le contexte historique, en utilisant des protocoles tels que l''intégration de CI/CD et les modèles cloud.","de":"Ermöglicht es Agenten, strukturierte Kursmaterialien zu erstellen, indem sie die Absicht des Instruktors analysieren, wichtige Aspekte wie den Themenumfang, die Vortragsdauer und das Gleichgewicht zwischen Theorie und Praxis abdecken, unter Berücksichtigung des Branchenkontexts und des historischen Hintergrunds, unter Verwendung von Protokollen wie CI/CD-Integration und Cloud-Mustern.","pt":"Habilita os agentes a criar materiais de curso estruturados, analisando a intenção do instrutor, cobrindo aspectos-chave como escopo de tópico, duração da aula e equilíbrio entre teoria e prática, considerando o contexto da indústria e o histórico, utilizando protocolos como integração CI/CD e padrões de nuvem.","ru":"Наделяет агентов возможностью создавать структурированные учебные материалы, анализируя намерения преподавателя, охватывая ключевые аспекты, такие как объем темы, продолжительность лекции и баланс между теорией и практикой, учитывая контекст отрасли и исторический фон, используя протоколы, такие как интеграция CI/CD и облачные шаблоны.","ar":"تمكين الوكلاء من إنشاء مواد مقررية منظمة من خلال تحليل نية المعلم، وغمر جوانب رئيسية مثل نطاق الموضوع ومدة المحاضرة وتوازن النظرية والتطبيق، مع الأخذ في الاعتبار سياق الصناعة والخلفية التاريخية، واستخدام بروتوكولات مثل إدماج CI/CD وأنماط السحابة."},"useCases":{"en":["Generating course outlines with balanced theory and practical content","Creating lesson plans with appropriate depth and scope for specific topics","Developing educational materials with relevant industry context and tool integration"],"zh":["生成具有平衡的理论和实践内容的课程大纲","创建具有适当深度和范围的特定主题的课程计划","开发具有相关行业背景和工具集成的教育材料"],"ja":["バランスのとれた理論と実践の内容を持つコースアウトラインを生成する","特定のトピックに適切な深度と範囲を持つレッスンプランを作成する","関連する業界の背景とツールの統合を持つ教育資料を開発する"],"ko":["균형 있는 이론과 실습 내용을 가진 과정 개요 생성","특정 주제에 대한 적절한 깊이와 범위를 가진 강의 계획 생성","관련 산업 배경과 툴 통합을 가진 교육 자료 개발"],"es":["Generar esquemas de cursos con contenido teórico y práctico equilibrado","Crear planes de lección con profundidad y alcance adecuados para temas específicos","Desarrollar materiales educativos con contexto industrial relevante e integración de herramientas"],"fr":["Générer des plans de cours avec un contenu théorique et pratique équilibré","Créer des plans de leçon avec une profondeur et une portée appropriées pour des sujets spécifiques","Développer des matériels éducatifs avec un contexte industriel pertinent et une intégration d''outils"],"de":["Erstellen von Kursübersichten mit ausgewogenem Theorie- und Praxisinhalt","Erstellen von Lernplänen mit geeigneter Tiefe und Umfang für bestimmte Themen","Entwickeln von Bildungsmaterialien mit relevantem Branchenkontext und Werkzeugintegration"],"pt":["Gerar esboços de cursos com conteúdo teórico e prático equilibrado","Criar planos de lição com profundidade e escopo apropriados para tópicos específicos","Desenvolver materiais educacionais com contexto da indústria relevante e integração de ferramentas"],"ru":["Генерировать планы курсов с сбалансированным теоретическим и практическим содержанием","Создавать планы уроков с подходящей глубиной и объемом для конкретных тем","Разрабатывать образовательные материалы с актуальным контекстом отрасли и интеграцией инструментов"],"ar":["جعل مخططات الدورات مع المحتوى النظري والتطبيقي المتوازن","إنشاء خطط الدرس مع العمق والمدى المناسبين للمواضيع المحددة","تطوير المواد التعليمية مع سياق الصناعة ذي الصلة وتكامل الأدوات"]},"limitations":{"en":["Requires instructor input for intent gathering","Limited to educational content creation","Dependent on availability of industry context and related tool information"],"zh":["需要讲师输入以收集意图","仅限教育内容创建","依赖于行业背景和相关工具信息的可用性"],"ja":["意図を収集するために講師の入力が必要","教育コンテンツの作成のみ","業界の背景と関連ツールの情報の可用性に依存する"],"ko":["의도 수집을 위해 강사 입력이 필요","교육 내용 생성에만 국한됨","산업 배경 및 관련 툴 정보의 가용성에 의존"],"es":["Requiere la entrada del instructor para la recopilación de intenciones","Limitado a la creación de contenido educativo","Dependiente de la disponibilidad de información de contexto industrial y herramientas relacionadas"],"fr":["Nécessite la saisie de l''instructeur pour la collecte d''intentions","Limité à la création de contenu éducatif","Dépend de la disponibilité d''informations de contexte industriel et d''outils associés"],"de":["Benötigt die Eingabe des Instruktors für die Intent-Erfassung","Begrenzt auf die Erstellung von Bildungsinhalten","Abhängig von der Verfügbarkeit von Branchenkontext- und Werkzeuginformationen"],"pt":["Exige entrada do instrutor para coleta de intenções","Limitado à criação de conteúdo educacional","Dependente da disponibilidade de contexto da indústria e informações de ferramentas relacionadas"],"ru":["Требует ввода преподавателя для сбора намерений","Ограничен созданием образовательного контента","Зависит от наличия контекста отрасли и связанной информации об инструментах"],"ar":["يتطلب إدخال المعلم لجمع النيات","محدود بإنشاء المحتوى التعليمي","يعتمد على توافر سياق الصناعة ومعلومات الأدوات ذات الصلة"]},"version":4},"contentHash":"44722e810554217952bdb1d5779d8fbf4ed01c2fab2919684c0b282f1a98d876","qualityScore":41}');
