INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('doron-nazaretsky/john-bryce/plan-course-materials', 'plan-course-materials', 'doron-nazaretsky', 'john-bryce', 'community', 'plan-course-materials doron-nazaretsky john-bryce community The plan-course-materials skill helps instructors create comprehensive course plans by gathering intent and covering key aspects such as scope, depth, and industry context. It benefits educators and course creators. 课程材料规划涉及范围、深度、内部机制和行业背景等方面的考虑，帮助您创建有效的课程 コース資料計画には、範囲、深さ、内部メカニズム、業界背景などを考慮して効果的なコースを作成する 코스 자료 계획은 범위, 깊이, 내부 메커니즘, 산업 배경 등을 고려하여 효과적인 코스를 생성하는 것을 포함합니다 Planifica materiales de curso con nuestro agente de IA, considerando alcance, profundidad e internos para crear lecciones óptimas. Planifiez des matériaux de cours avec nos outils d''IA, en tenant compte de la portée, de la profondeur et des internes pour créer des leçons optimales. Planen Sie Kursmaterialien mit unseren KI-Tools, indem Sie Umfang, Tiefe und Interna berücksichtigen, um optimale Lektionen zu erstellen. Planeje materiais de curso personalizados com nossa ferramenta de IA, considerando fatores como escopo, profundidade e contexto Спланируйте индивидуальные материалы курса с помощью нашего ИИ Агента, учитывая такие факторы, как объем, глубина и контекст احضَر مواد الدورة المخصصة باستخدام أداة الذكاء الاصطناعي لدينا، مع考虑 عوامل مثل النطاق والعمق والسياق how to plan course materials what is plan-course-materials plan-course-materials alternative plan-course-materials setup guide plan-course-materials install course planning best practices course material creation tools education technology solutions 课程材料规划 AIエージェント 范围规划 深度规划 内部机制 行业背景 课程设计 教育技术 Asks questions about scope to determine topic and lecture duration Assesses depth to identify what to cover deeply, briefly, or skip entirely Evaluates internals to balance ''how it works under the hood'' with practical usage Considers context to determine historical context and related tools Examines industry to identify related tools, CI/CD integration, and cloud patterns plan-course-materials is a skill that assists in creating course plans by asking questions about scope, depth, internals, context, and industry to gather instructor intent');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adtak/super-red/plan-refactor', 'community', 'adtak', 'super-red', 'adtak/super-red', 'plan-refactor', 0, 0, 41, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:25.297Z', '351da3f5d9d2a80ff61753914605b07637295396900895591f97c02e9e20f1bb', '{"id":"adtak/super-red/plan-refactor","name":"plan-refactor","description":{"en":"plan-refactor analyzes codebases for refactoring opportunities, presenting a plan and creating GitHub issues for approved proposals, benefiting developers and development teams.","zh":"Plan Refactor是一种代码分析和重构工具，帮助开发者优化代码库，减少重复代码和不一致性","ja":"Plan Refactorはコード分析とリファクタリングツールで、開発者がコードベースを最適化し、重複コードや不一致性を減らすのに役立ちます","ko":"Plan Refactor는 코드 분석과 리팩토링 도구로 개발자가 코드베이스를 최적화하고 중복 코드와 불일치를 줄이는 데 도움이 됩니다","es":"Plan-refactor es una herramienta de refactorización de código que analiza tu base de código y propone mejoras","fr":"Plan-refactor est un outil de refactorisation de code qui analyse votre codebase et propose des améliorations","de":"Plan-Refactor ist ein Code-Refactoring-Tool, das Ihre Codebasis analysiert und Vorschläge für eine Verbesserung erstellt","pt":"O Plan Refactor é uma ferramenta que analisa o código para identificar oportunidades de refatoração, apresenta um plano e cria issues no GitHub","ru":"Plan Refactor - это инструмент, который анализирует код для выявления возможностей рефакторинга, представляет план и создает issues на GitHub с помощью ИИ Агентов","ar":"Plan Refactor هو أداة تحليل الكود لتحديد فرص تحسين الكود وتقديم خطة وإنشاء قضايا على GitHub باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"plan-refactor: Code Refactoring Setup Guide | AI Agent Skill","zh":"Plan Refactor_SETUP GUIDE：代码重构和优化","ja":"Plan Refactorベストプラクティス：AIエージェントによるコード分析","ko":"Plan Refactor Setup Guide: 코드 리팩토링과 최적화","es":"Guía para refactorizar código con plan-refactor","fr":"Configurer plan-refactor pour améliorer votre code","de":"Plan-Refactor-Setup für effizientes Code-Refactoring","pt":"Guia de Configuração do Plan Refactor para Otimização de ...","ru":"Настройка Plan Refactor для рефакторинга кода с помощью И...","ar":"دليل إعداد Plan Refactor لتحسين الكود باستخدام أدوات الذك..."},"description":{"en":"Discover how plan-refactor analyzes codebases, identifies refactoring opportunities, and creates GitHub issues for approved proposals - get started today!","zh":"使用Plan Refactor AI工具分析代码库，找出重构机会，并创建GitHub问题以优化代码","ja":"Plan Refactor AIエージェントを使ってコードベースを分析し、リファクタリングの機会を特定し、GitHubの問題を作成してコードを最適化する","ko":"Plan Refactor AI 도구를 사용하여 코드베이스를 분석하고 리팩토링 기회를 찾고 GitHub 이슈를 생성하여 코드 최적화","es":"Descubre cómo plan-refactor ayuda a identificar oportunidades de refactorización en tu base de código y crea propuestas para mejorarla","fr":"Découvrez comment plan-refactor analyse votre codebase et propose des améliorations pour un code plus efficace","de":"Erfahren Sie, wie plan-refactor Ihre Codebasis analysiert und Vorschläge für eine Verbesserung erstellt","pt":"Aprenda a configurar o Plan Refactor para identificar oportunidades de refatoração em seu código e melhorar a manutenção","ru":"Узнайте, как настроить Plan Refactor для выявления возможностей рефакторинга кода и улучшения его поддержки с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Plan Refactor لتحديد فرص تحسين الكود وتحسين الصيانة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"plan-refactor is a code analysis tool that identifies refactoring opportunities in codebases, focusing on large files, duplication, and inconsistency.","zh":"Plan Refactor是一种AI驱动的代码分析和重构工具","ja":"Plan RefactorはAI駆動のコード分析とリファクタリングツールです","ko":"Plan Refactor는 AI 기반의 코드 분석과 리팩토링 도구입니다","es":"Plan-refactor es una herramienta AI que analiza y mejora el código","fr":"Plan-refactor est un outil IA qui analyse et améliore le code","de":"Plan-Refactor ist ein AI-Tool, das den Code analysiert und verbessert","pt":"O Plan Refactor é uma ferramenta de otimização de código que identifica oportunidades de refatoração","ru":"Plan Refactor - это инструмент оптимизации кода, который выявляет возможности рефакторинга","ar":"Plan Refactor هو أداة تحسين الكود التي تحدد فرص تحسين الكود"},"features":{"en":["Analyzes codebases to identify refactoring opportunities","Identifies large files that mix multiple concerns for extraction","Detects duplication of styles, logic, or patterns across files","Finds inconsistency in style definitions, naming conventions, and code organization","Creates GitHub issues for each approved refactoring proposal"],"zh":["代码库分析","重构机会识别","GitHub问题创建","大文件分解","重复代码检测","不一致性检查"],"ja":["コードベース分析","リファクタリングの機会の特定","GitHubの問題作成","大きなファイルの分解","重複コードの検出","不一致性のチェック"],"ko":["코드베이스 분석","리팩토링 기회 식별","GitHub 이슈 생성","큰 파일 분해","중복 코드 감지","불일치 점검"],"es":["Análisis de archivos grandes para extracción de hooks, utilities y constantes","Detección de duplicados de estilos, lógica y patrones en archivos","Identificación de inconsistencias en definiciones de estilo y nombres","Creación de propuestas de refactorización y issues en GitHub","Análisis de código para identificar oportunidades de refactorización"],"fr":["Analyse de fichiers volumineux pour extraire des hooks, utilities et constantes","Détection de doublons de styles, logique et modèles dans les fichiers","Identification d''incohérences dans les définitions de style et les noms","Création de propositions de refactorisation et de problèmes sur GitHub","Analyse de code pour identifier les opportunités de refactorisation"],"de":["Analyse großer Dateien zur Extraktion von Hooks, Utilities und Konstanten","Erkennung von Duplikaten von Stilen, Logik und Mustern in Dateien","Identifizierung von Inkonsistenzen in Stildefinitionen und Namen","Erstellung von Vorschlägen für eine Refaktorisierung und Issues in GitHub","Code-Analyse zur Identifizierung von Möglichkeiten zur Refaktorisierung"],"pt":["Análise de arquivos grandes para extração de hooks, utilities e constants","Detecção de duplicação de estilos, lógica e padrões","Identificação de inconsistências em definições de estilo e nomenclatura","Criação de issues no GitHub para cada proposta aprovada","Análise de código para identificar oportunidades de refatoração"],"ru":["Анализ крупных файлов для extracting hooks, utilities и constants","Обнаружение дублирования стилей, логики и паттернов","Идентификация несоответствий в определениях стилей и именования","Создание issues на GitHub для каждой утвержденной пропозии","Анализ кода для выявления возможностей рефакторинга"],"ar":["تحليل الملفات الكبيرة لاستخراج hooks و utilities و constants","اكتشاف تكرار الأشكال و المنطق و الأنماط","تحديد عدم الاتساق في تعريفات الأشكال و التسمية","إنشاء قضايا على GitHub لكل مقترح معتمد","تحليل الكود لتحديد فرص تحسين الكود"]},"keywords":{"en":["how to use plan-refactor","plan-refactor alternative","plan-refactor setup guide","what is plan-refactor","plan-refactor vs code analysis tools","plan-refactor install","code refactoring best practices","github issues management","code analysis for duplication","refactoring large files"],"zh":["代码重构","代码分析","AI工具","代码优化","GitHub问题","重构机会","代码库分析","代码质量改进"],"ja":["コードリファクタリング","コード分析","AIエージェント","コード最適化","GitHubの問題","リファクタリングの機会","コードベース分析","コード品質改善"],"ko":["코드 리팩토링","코드 분석","AI 도구","코드 최적화","GitHub 이슈","리팩토링 기회","코드베이스 분석","코드 품질 개선"],"es":["herramientas de refactorización de código","análisis de código","mejora de código","refactorización de código","plan-refactor","herramientas de desarrollo","desarrollo de software","optimización de código"],"fr":["outils de refactorisation de code","analyse de code","amélioration de code","refactorisation de code","plan-refactor","outils de développement","développement de logiciels","optimisation de code"],"de":["Code-Refactoring-Tools","Code-Analyse","Code-Optimierung","Code-Refaktorisierung","plan-refactor","Entwicklertools","Software-Entwicklung","Code-Verbesserung"],"pt":["Plan Refactor","otimização de código","refatoração","análise de código","GitHub","hooks","utilities","constants","duplicação de código"],"ru":["Plan Refactor","оптимизация кода","рефакторинг","анализ кода","GitHub","hooks","utilities","constants","дублирование кода","ИИ Агенты"],"ar":["Plan Refactor","تحسين الكود","تحسين الكود","تحليل الكود","GitHub","hooks","utilities","constants","تكرار الكود","أدوات الذكاء الاصطناعي"]}},"owner":"adtak","repo":"super-red","repoPath":"adtak/super-red","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"plan-refactor","description":"Analyze the codebase for refactoring opportunities, create a plan, and file GitHub issues for each proposal.","bodyPreview":"# Plan Refactor\n\nAnalyze the codebase for refactoring opportunities, present a plan to the user, and create GitHub issues for each approved proposal.\n\n## Steps\n\n1. **Analyze the codebase** — Explore the codebase to identify refactoring opportunities. Focus on:\n   - **Large files** — Files that mix multiple concerns and could benefit from extraction (hooks, utilities, constants)\n   - **Duplication** — Repeated styles, logic, or patterns across files\n   - **Inconsistency** — Style definitions, nam","body":"# Plan Refactor\n\nAnalyze the codebase for refactoring opportunities, present a plan to the user, and create GitHub issues for each approved proposal.\n\n## Steps\n\n1. **Analyze the codebase** — Explore the codebase to identify refactoring opportunities. Focus on:\n   - **Large files** — Files that mix multiple concerns and could benefit from extraction (hooks, utilities, constants)\n   - **Duplication** — Repeated styles, logic, or patterns across files\n   - **Inconsistency** — Style definitions, naming conventions, or patterns that differ from the rest of the codebase\n   - **Magic numbers** — Hardcoded values that should be named constants\n   - **Dead code** — Unused imports, variables, or exports\n\n   Use the project''s CLAUDE.md to understand conventions and architecture.\n\n2. **Clarify unknowns** — If the analysis reveals ambiguous areas or multiple valid approaches, ask the user before proceeding. Do not make assumptions on ambiguous points.\n\n3. **Draft the plan** — Write a refactoring plan listing each proposal. Use the template in [plan-template.md](plan-template.md) for each proposal. Keep proposals independent — each should be implementable on its own.\n\n4. **Present to the user** — Show the full plan and ask for approval. The user may:\n   - Approve all proposals\n   - Remove or modify specific proposals\n   - Ask for additional analysis\n\n   Do NOT proceed to issue creation until the user explicitly approves.\n\n5. **Create GitHub issues** — For each approved proposal, create a separate GitHub issue using `gh issue create --title \"<title>\" --body \"<plan>\"`. Use a HEREDOC for the body to preserve formatting. Title is Short, imperative, in English (e.g., \"Extract game loop logic into a custom hook\").\n\n6. **Report results** — After all issues are created, show the user a summary table with issue numbers, titles, and URLs.\n\n## Guidelines\n\n- Write all issue content in English (project convention).\n- Converse with the user in Japanese (project convention).\n- Keep proposals minimal and focused — one concern per issue.\n- Do not propose changes that add complexity without clear benefit.\n- Reference actual file paths discovered during exploration, not guessed paths.\n- For each file change, specify whether it is Create, Modify, or Delete.\n- Do not include full code in the plan — describe what changes are needed and why.\n- Code snippets are acceptable when they clarify intent (e.g., type definitions, key structures).\n"},"lastSynced":"2026-03-08T02:13:25.297Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents seeking to automate refactoring proposals and GitHub issue creation for improved codebase maintainability.","zh":"适合于代码分析代理寻求自动化重构提议和 GitHub 问题创建，以提高代码库的可维护性。","ja":"コード分析エージェントがリファクタリングの提案を自動化し、GitHub の問題を作成してコードベースの保守性を高めるのに適しています。","ko":"코드 분석 에이전트가 리팩토링 제안을 자동화하고 GitHub 문제를 생성하여 코드베이스의 유지 보수성을 향상시키는 데 적합합니다.","es":"Ideal para agentes de análisis de código que buscan automatizar propuestas de refactorización y creación de problemas de GitHub para mejorar la mantenibilidad de la base de código.","fr":"Idéal pour les agents d''analyse de code qui cherchent à automatiser les propositions de refactoring et la création de problèmes GitHub pour améliorer la maintenabilité de la base de code.","de":"Ideal für Code-Analyse-Agents, die die Automatisierung von Refactoring-Vorschlägen und der Erstellung von GitHub-Problemen für eine verbesserte Codebase-Maintenabilität anstreben.","pt":"Ideal para Agentes de Análise de Código que buscam automatizar propostas de refatoração e criação de problemas no GitHub para melhorar a manutenibilidade da base de código.","ru":"Идеально для Агентов анализа кода, стремящихся автоматизировать предложения по рефакторингу и созданию проблем на GitHub для улучшения поддерживаемости кодовой базы.","ar":"مثالي لعميل تحليل الشفرة الذي يسعى إلى 자동化 مقترحات إعادة هيكلة وخلق مشاكل على GitHub لتحسين صيانة قاعدة الشفرة."},"recommendation":{"en":"Empowers agents to analyze codebases for refactoring opportunities, presenting plans and creating GitHub issues for approved proposals, leveraging code analysis and GitHub API integration for streamlined development workflows.","zh":"赋予代理分析代码库以查找重构机会的能力，提出计划并为批准的提案创建 GitHub 问题，利用代码分析和 GitHub API 集成简化开发工作流程。","ja":"コードベースを分析してリファクタリングの機会を特定し、計画を立てて承認された提案に対して GitHub の問題を作成する機能をエージェントに与え、コード分析と GitHub API の統合によって開発ワークフローを簡素化します。","ko":"에이전트가 코드베이스를 분석하여 리팩토링 기회를 찾고, 계획을 수립하고 승인된 제안에 대한 GitHub 문제를 생성할 수 있도록 하며, 코드 분석과 GitHub API 통합을 통해 개발 워크플로우를 간소화합니다.","es":"Habilita a los agentes a analizar las bases de código para encontrar oportunidades de refactorización, presentar planes y crear problemas de GitHub para propuestas aprobadas, aprovechando la integración de la API de análisis de código y GitHub para flujos de trabajo de desarrollo optimizados.","fr":"Permet aux agents d''analyser les bases de code pour trouver des opportunités de refactoring, présenter des plans et créer des problèmes GitHub pour les propositions approuvées, en exploitant l''intégration de l''API d''analyse de code et GitHub pour des flux de travail de développement rationalisés.","de":"Ermächtigt Agents, Codebasen auf Refactoring-Möglichkeiten zu analysieren, Pläne vorzustellen und GitHub-Probleme für genehmigte Vorschläge zu erstellen, indem es die Integration von Code-Analyse und GitHub-API für optimierte Entwicklungsworkflows nutzt.","pt":"Habilita os agentes a analisar bases de código para oportunidades de refatoração, apresentando planos e criando problemas no GitHub para propostas aprovadas, utilizando a integração da API do GitHub e análise de código para fluxos de trabalho de desenvolvimento otimizados.","ru":"Наделяет агентов возможностью анализировать кодовые базы для поиска возможностей рефакторинга, представляя планы и создавая проблемы на GitHub для одобренных предложений, используя интеграцию с GitHub API и анализ кода для оптимизированных рабочих процессов разработки.","ar":"يمنح العميل تحليل الشفرة القدرة على تحليل قواعد الشفرة للبحث عن فرص لإعادة الهيكلة، وتقديم خطط وخلق مشاكل على GitHub للمقترحات المعتمدة، باستخدام تكامل واجهة برمجة التطبيقات GitHub وتحليل الشفرة من أجل تدفقات عمل تطوير محسّنة."},"useCases":{"en":["Analyzing codebases for large files and duplication","Generating refactoring plans and proposals","Automating GitHub issue creation for approved refactoring proposals"],"zh":["分析代码库中的大文件和重复代码","生成重构计划和提议","自动化批准的重构提议的 GitHub 问题创建"],"ja":["大規模ファイルや重複コードを持つコードベースの分析","リファクタリング計画と提案の生成","承認されたリファクタリング提案の GitHub 問題の自動作成"],"ko":["대형 파일 및 중복 코드가 포함된 코드베이스 분석","리팩토링 계획 및 제안 생성","승인된 리팩토링 제안에 대한 GitHub 문제 자동 생성"],"es":["Análisis de bases de código para archivos grandes y duplicaciones","Generación de planes y propuestas de refactorización","Automatización de la creación de problemas de GitHub para propuestas de refactorización aprobadas"],"fr":["Analyse de bases de code pour les fichiers volumineux et les duplications","Génération de plans et de propositions de refactoring","Automatisation de la création de problèmes GitHub pour les propositions de refactoring approuvées"],"de":["Analyse von Codebasen für große Dateien und Duplizierungen","Erstellung von Refactoring-Plänen und -Vorschlägen","Automatisierung der Erstellung von GitHub-Problemen für genehmigte Refactoring-Vorschläge"],"pt":["Analisar bases de código para arquivos grandes e duplicações","Gerar planos e propostas de refatoração","Automatizar a criação de problemas no GitHub para propostas de refatoração aprovadas"],"ru":["Анализ кодовых баз для крупных файлов и дубликатов","Генерировать планы и предложения по рефакторингу","Автоматизировать создание проблем на GitHub для одобренных предложений по рефакторингу"],"ar":["تحليل قواعد الشفرة للملفات الكبيرة والتكرارات","توليد خطط ومقترحات لإعادة الهيكلة","تأتمة إنشاء المشاكل على GitHub لمقترحات إعادة الهيكلة المعتمدة"]},"limitations":{"en":["Requires GitHub API access","Limited to codebases with accessible repositories","Focus on code organization and structure refactoring"],"zh":["需要 GitHub API 访问","仅限于具有可访问存储库的代码库","专注于代码组织和结构重构"],"ja":["GitHub API アクセスが必要","アクセス可能なリポジトリを持つコードベースのみに限定","コードの組織化と構造のリファクタリングに焦点を当てた"],"ko":["GitHub API 액세스가 필요","액세스 가능한 저장소가 있는 코드베이스에만 제한","코드 조직 및 구조 리팩토링에 중점"],"es":["Requiere acceso a la API de GitHub","Limitado a codebases con repositorios accesibles","Enfocado en la refactorización de organización y estructura de código"],"fr":["Nécessite un accès à l''API GitHub","Limité aux bases de code avec des référentiels accessibles","Axé sur le refactoring de l''organisation et de la structure de code"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf Codebasen mit zugänglichen Repositories","Fokus auf die Refactoring von Code-Organisation und -Struktur"],"pt":["Exige acesso à API do GitHub","Limitado a bases de código com repositórios acessíveis","Foco na organização e estrutura de refatoração do código"],"ru":["Требует доступа к GitHub API","Ограничен кодовыми базами с доступными репозиториями","Фокус на рефакторинге организации и структуры кода"],"ar":["يتطلب الوصول إلى واجهة برمجة التطبيقات GitHub","محدود بقواعد الشفرة ذات المستودعات القابلة للوصول","التركيز على إعادة هيكلة تنظيم الشفرة وهيكلتها"]},"version":4},"contentHash":"351da3f5d9d2a80ff61753914605b07637295396900895591f97c02e9e20f1bb","qualityScore":41}');
