INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('adtak/super-red/plan-refactor', 'plan-refactor', 'adtak', 'super-red', 'community', 'plan-refactor adtak super-red community plan-refactor analyzes codebases for refactoring opportunities, presenting a plan and creating GitHub issues for approved proposals, benefiting developers and development teams. Plan Refactor是一种代码分析和重构工具，帮助开发者优化代码库，减少重复代码和不一致性 Plan Refactorはコード分析とリファクタリングツールで、開発者がコードベースを最適化し、重複コードや不一致性を減らすのに役立ちます Plan Refactor는 코드 분석과 리팩토링 도구로 개발자가 코드베이스를 최적화하고 중복 코드와 불일치를 줄이는 데 도움이 됩니다 Plan-refactor es una herramienta de refactorización de código que analiza tu base de código y propone mejoras Plan-refactor est un outil de refactorisation de code qui analyse votre codebase et propose des améliorations Plan-Refactor ist ein Code-Refactoring-Tool, das Ihre Codebasis analysiert und Vorschläge für eine Verbesserung erstellt O Plan Refactor é uma ferramenta que analisa o código para identificar oportunidades de refatoração, apresenta um plano e cria issues no GitHub Plan Refactor - это инструмент, который анализирует код для выявления возможностей рефакторинга, представляет план и создает issues на GitHub с помощью ИИ Агентов Plan Refactor هو أداة تحليل الكود لتحديد فرص تحسين الكود وتقديم خطة وإنشاء قضايا على GitHub باستخدام أدوات الذكاء الاصطناعي how to use plan-refactor plan-refactor alternative plan-refactor setup guide what is plan-refactor plan-refactor vs code analysis tools plan-refactor install code refactoring best practices github issues management code analysis for duplication refactoring large files 代码重构 代码分析 AI工具 代码优化 GitHub问题 重构机会 代码库分析 代码质量改进 Analyzes codebases to identify refactoring opportunities Identifies large files that mix multiple concerns for extraction Detects duplication of styles, logic, or patterns across files Finds inconsistency in style definitions, naming conventions, and code organization Creates GitHub issues for each approved refactoring proposal plan-refactor is a code analysis tool that identifies refactoring opportunities in codebases, focusing on large files, duplication, and inconsistency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pluginagentmarketplace/custom-plugin-product-manager/analytics-metrics-kpi', 'community', 'pluginagentmarketplace', 'custom-plugin-product-manager', 'pluginagentmarketplace/custom-plugin-product-manager', 'analytics-metrics-kpi', 0, 0, 41, '2026-03-08T01:57:15.655Z', '2026-03-08T02:13:57.506Z', '4f37ea86c1282beef01260ebbd78c23c27028a5d70940ab760da4703557488a7', '{"id":"pluginagentmarketplace/custom-plugin-product-manager/analytics-metrics-kpi","name":"analytics-metrics-kpi","description":{"en":"The analytics-metrics-kpi skill enables product managers to become data-driven by defining meaningful metrics and building dashboards. It benefits product teams by providing a framework for metrics and decision-making.","zh":"Analytics & Metrics KPI AI エージェント帮助您定义北极星指标，构建仪表盘，并做出数据驱动的决策","ja":"アナリティクス＆メトリクスKPI AIエージェントは、北極星メトリクスを定義し、ダッシュボードを構築し、データ駆動の意思決定を行うのに役立ちます","ko":"분석 및 메트릭스 KPI AI 에이전트는 북극성 지표를 정의하고 대시보드를 구축하며 데이터 驱动 의사 결정을 하는 데 도움이 됩니다","es":"El skill analytics-metrics-kpi te permite definir métricas significativas y crear paneles de control para tomar decisiones basadas en datos","fr":"Le skill analytics-metrics-kpi vous permet de définir des métriques significatives et de créer des tableaux de bord pour prendre des décisions basées sur les données","de":"Das analytics-metrics-kpi-Skill ermöglicht es Ihnen, bedeutungsvolle Metriken zu definieren und Dashboards zu erstellen, um datengetriebene Entscheidungen zu treffen","pt":"O skill analytics-metrics-kpi permite definir métricas significativas e criar painéis para tomar decisões baseadas em dados.","ru":"Навык analytics-metrics-kpi позволяет определять важные метрики и создавать панели для принятия решений на основе данных.","ar":"المهارة analytics-metrics-kpi تمكن من تعريف مقاييس معنوية وإنشاء لوحات تحكم لاتخاذ قرارات تستند إلى البيانات."},"seo":{"title":{"en":"analytics-metrics-kpi: Data-Driven Decision Making Setup ...","zh":"AIエージェント：Analytics & Metrics KPI 设置指南","ja":"AIエージェント：アナリティクス＆メトリクスKPI ベストプラクティス","ko":"AI 에이전트: 분석 및 메트릭스 KPI 구축 가이드","es":"Guía de configuración de analytics-metrics-kpi para Agent...","fr":"Guide de mise en place d''analytics-metrics-kpi pour les O...","de":"Einrichtungsleitfaden für analytics-metrics-kpi in KI-Tools","pt":"Guia de Configuração de Métricas de Análise","ru":"Настройка метрик аналитики ИИ Агентов","ar":"دليل إعداد مقاييس تحليل الوكيل الذكي"},"description":{"en":"Unlock data-driven product management with analytics-metrics-kpi. Discover how to define meaningful metrics, build dashboards, and run experiments to inform ...","zh":"了解如何使用 Analytics & Metrics KPI AI エージェント来定义有意义的指标，构建仪表盘，并做出数据驱动的决策","ja":"アナリティクス＆メトリクスKPI AIエージェントを使用して、有意義な指標を定義し、ダッシュボードを構築し、データ駆動の意思決定を行う方法を学びます","ko":"분석 및 메트릭스 KPI AI 에이전트를 사용하여 의미 있는 지표를 정의하고 대시보드를 구축하며 데이터 驱动 의사 결정을 하는 방법을 알아보세요","es":"Aprende a definir métricas significativas y crear paneles de control con analytics-metrics-kpi para tomar decisiones basadas en datos","fr":"Découvrez comment définir des métriques significatives et créer des tableaux de bord avec analytics-metrics-kpi pour prendre des décisions basées sur les don...","de":"Erfahren Sie, wie Sie mit analytics-metrics-kpi bedeutungsvolle Metriken definieren und Dashboards erstellen, um datengetriebene Entscheidungen zu treffen","pt":"Aprenda a definir métricas significativas e criar painéis com o plugin de gerenciamento de produtos","ru":"Узнайте, как определить важные метрики и создать панели с помощью плагина управления продуктом для ИИ Агентов","ar":"تعرف على كيفية تعريف مقاييس معنوية وإنشاء لوحات تحكم مع إضافة إدارة المنتج للوكيل الذكي"},"definition":{"en":"analytics-metrics-kpi is a product management plugin that provides a metrics framework for defining meaningful metrics, building dashboards, and running experiments to inform data-driven decisions.","zh":"Analytics & Metrics