INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pluginagentmarketplace/custom-plugin-product-manager/analytics-metrics-kpi', 'analytics-metrics-kpi', 'pluginagentmarketplace', 'custom-plugin-product-manager', 'community', 'analytics-metrics-kpi pluginagentmarketplace custom-plugin-product-manager community The analytics-metrics-kpi skill enables product managers to become data-driven by defining meaningful metrics and building dashboards. It benefits product teams by providing a framework for metrics and decision-making. Analytics & Metrics KPI AI エージェント帮助您定义北极星指标，构建仪表盘，并做出数据驱动的决策 アナリティクス＆メトリクスKPI AIエージェントは、北極星メトリクスを定義し、ダッシュボードを構築し、データ駆動の意思決定を行うのに役立ちます 분석 및 메트릭스 KPI AI 에이전트는 북극성 지표를 정의하고 대시보드를 구축하며 데이터 驱动 의사 결정을 하는 데 도움이 됩니다 El skill analytics-metrics-kpi te permite definir métricas significativas y crear paneles de control para tomar decisiones basadas en datos Le skill analytics-metrics-kpi vous permet de définir des métriques significatives et de créer des tableaux de bord pour prendre des décisions basées sur les données Das analytics-metrics-kpi-Skill ermöglicht es Ihnen, bedeutungsvolle Metriken zu definieren und Dashboards zu erstellen, um datengetriebene Entscheidungen zu treffen O skill analytics-metrics-kpi permite definir métricas significativas e criar painéis para tomar decisões baseadas em dados. Навык analytics-metrics-kpi позволяет определять важные метрики и создавать панели для принятия решений на основе данных. المهارة analytics-metrics-kpi تمكن من تعريف مقاييس معنوية وإنشاء لوحات تحكم لاتخاذ قرارات تستند إلى البيانات. how to use analytics-metrics-kpi what is analytics-metrics-kpi analytics-metrics-kpi alternative analytics-metrics-kpi vs product analytics tools analytics-metrics-kpi install guide analytics-metrics-kpi setup tutorial data-driven decision making with analytics-metrics-kpi product management with analytics-metrics-kpi metrics framework for product teams AI エージェント Analytics & Metrics KPI 北极星指标 仪表盘构建 数据驱动决策 Acquisition 到 Revenue 产品管理 ROADMAP 计划 Defines a North Star Metric to capture product value Provides a Metrics Framework for acquisition and revenue tracking Enables building dashboards to visualize key metrics Supports running experiments to inform data-driven decisions Identifies leading indicators of revenue for business success analytics-metrics-kpi is a product management plugin that provides a metrics framework for defining meaningful metrics, building dashboards, and running experiments to inform data-driven decisions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alekspetrov/navigator/nav-stats', 'community', 'alekspetrov', 'navigator', 'alekspetrov/navigator', 'nav-stats', 0, 0, 41, '2026-03-08T01:57:15.657Z', '2026-03-08T02:13:58.346Z', '534fdddf7028538dba06aebd55a07bf26a7587bc151eb4c4ff8737c19678f3c8', '{"id":"alekspetrov/navigator/nav-stats","name":"nav-stats","description":{"en":"nav-stats is a skill that provides real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable. It benefits developers by showing token savings, session performance, and efficiency metrics.","zh":"nav-stats技能提供实时效率报告与基线比较，优化Navigator会话，提高会话效率","ja":"nav-statsスキルはリアルタイムの効率レポートとベースライン比較を提供し、Navigatorセッションを最適化します","ko":"nav-stats 스킬은 실시간 효율성 보고와 기준 비교를 제공하여 Navigator 세션을 최적화합니다","es":"nav-stats es una habilidad que proporciona informes de eficiencia en tiempo real y comparaciones de referencia para mejorar la productividad de tus sesiones de desarrollo","fr":"nav-stats est une compétence qui fournit des rapports d''efficacité en temps réel et des comparaisons de référence pour améliorer la productivité de vos sessions de développement","de":"nav-stats ist eine Fähigkeit, die Echtzeit-Effizienzberichte und Referenzvergleiche bereitstellt, um die Produktivität Ihrer Entwicklungssitzungen zu verbessern","pt":"O nav-stats é uma habilidade que fornece relatórios de eficiência em tempo real com comparações de baseline, tornando o valor do Navigator quantificável e compartilhável.","ru":"Нав-stats - это навык, который предоставляет отчеты об эффективности в реальном времени с сравнениями базового уровня, что делает ценность Navigator количественной и общедоступной.","ar":"nav-stats هو مهارة توفر تقارير كفاءة الوقت الفعلي مع مقارنات الأساس، مما يجعل قيمة Navigator كمية وقابلة للمشاركة."},"seo":{"title":{"en":"nav-stats: Real-Time Efficiency Reporting for AI Agents |...","zh":"nav-stats Setup Guide: 实时效率报告与基线比较","ja":"nav-stats セットアップガイド: リアルタイム効率レポートとベースライン比較","ko":"nav-stats 설정 가이드: 실시간 효율성 보고 및 기준 비교","es":"Guía de configuración de nav-stats para Agentes de IA","fr":"Configurer nav-stats pour les Outils d''IA","de":"Einrichtungsleitfaden für nav-stats in KI-Tools","pt":"Guia de Configuração do Nav-Stats: Relatórios de Eficiênc...","ru":"ИИ Агенты: Настройка нав-stats для Отчетов об Эффективности","ar":"دليل ضبط нав-stats: تقارير كفاءة الوقت الفعلي"},"description":{"en":"Unlock the full potential of Claude Code with nav-stats! Learn how to invoke this skill and get real-time efficiency reporting with baseline comparisons. Get...","zh":"了解nav-stats技能，实现实时效率报告与基线比较，优化Navigator会话","ja":"nav-statsスキルを使用してリアルタイムの効率レポートとベースライン比較を実現し、Navigatorセッションを最適化します","ko":"nav-stats 스킬을 사용하여 실시간 효율성 보고와 기준 비교를 구현하고 Navigator 세션을 최적화합니다","es":"Aprende a utilizar nav-stats para mejorar la eficiencia de tus sesiones de desarrollo con estadísticas en tiempo real y comparaciones de referencia","fr":"Découvrez comment configurer nav-stats pour améliorer l''efficacité de vos sessions de développement avec des statistiques en temps réel et des comparaisons d...","de":"Erfahren Sie, wie Sie nav-stats einrichten, um die Effizienz Ihrer Entwicklungssitzungen mit Echtzeit-Statistiken und Referenzvergleichen zu verbessern","pt":"Aprenda a configurar o nav-stats para relatórios de eficiência em tempo real e compare baseline com o Claude Code","ru":"Узнайте, как настроить нав-stats для отчетов об эффективности в реальном времени и сравнить базовый уровень с Claude Code","ar":"تعلم كيفية ضبط нав-stats لتقارير الكفاءة في الوقت الفعلي وقارن الأساس مع كلود كود"},"definition":{"en":"nav-stats is a context engineering skill for Claude Code that enables real-time efficiency reporting and baseline comparisons for Navigator sessions.","zh":"nav-stats是Navigator的技能，提供实时效率报告与基线比较","ja":"nav-statsはNavigatorのスキルであり、リアルタイムの効率レポートとベースライン比較を提供します","ko":"nav-stats는 Navigator의 스킬로 실시간 효율성 보고와 기준 비교를 제공합니다","es":"nav-stats es una habilidad de inteligencia artificial que proporciona estadísticas de sesión y comparaciones de referencia","fr":"nav-stats est une compétence d''intelligence artificielle qui fournit des statistiques de session et des comparaisons de référence","de":"nav-stats ist eine KI-Fähigkeit, die Sitzungsstatistiken und Referenzvergleiche bereitstellt","pt":"O que é nav-stats? É uma habilidade de engenharia de contexto para o Claude Code que fornece relatórios de eficiência em tempo real.","ru":"Что такое нав-stats? Это навык контекстной инженерии для Claude Code, который предоставляет отчеты об эффективности в реальном времени.","ar":"ما هو nav-stats؟ إنه مهارة هندسة سياق للكلود كود التي توفر تقارير كفاءة الوقت الفعلي."},"features":{"en":["Shows real-time efficiency reporting with baseline comparisons","Provides token savings and session performance metrics","Supports invocation via commands like ''show my stats'' and ''show session stats''","Generates efficiency reports and metrics on demand","Enables users to ask questions like ''how efficient am I?'' and ''how much did I save?''","Displays impact and proves Navigator''s value"],"zh":["实时效率报告","基线比较","会话性能优化","令牌节省跟踪","Navigator报告生成"],"ja":["リアルタイム効率レポート","ベースライン比較","セッション性能最適化","トークン節約追跡","Navigatorレポート生成"],"ko":["실시간 효율성 보고","기준 비교","세션 성능 최적화","토큰 절약 추적","Navigator 보고서 생성"],"es":["Informes de eficiencia en tiempo real","Comparaciones de referencia para evaluar el rendimiento","Estadísticas de sesión para analizar la productividad","Soporte para tokens de ahorro y rendimiento de sesión","Compatibilidad con comandos de voz y texto para invocar la habilidad"],"fr":["Rapports d''efficacité en temps réel","Comparaisons de référence pour évaluer les performances","Statistiques de session pour analyser la productivité","Prise en charge des jetons d''économie et des performances de session","Compatibilité avec les commandes vocales et de texte pour invoquer la compétence"],"de":["Echtzeit-Effizienzberichte","Referenzvergleiche zur Leistungsbewertung","Sitzungsstatistiken zur Produktivitätsanalyse","Unterstützung für Token-Einsparungen und Sitzungsleistung","Kompatibilität mit Sprach- und Textbefehlen zur Aufruf der Fähigkeit"],"pt":["Relatórios de eficiência em tempo real","Comparações de baseline","Integração com o Claude Code","Suporte a sessões de 20+ trocas","Relatórios de desempenho de sessão","Análise de economia de tokens"],"ru":["Отчеты об эффективности в реальном времени","Сравнения базового уровня","Интеграция с Claude Code","Поддержка сессий из 20+ обменов","Отчеты о производительности сессии","Анализ экономии токенов"],"ar":["تقارير كفاءة الوقت الفعلي","مقارنات الأساس","التكامل مع كلود كود","دعم جلسات 20+ تبادلات","تقارير أداء الجلسة","تحليل توفير الرموز"]},"keywords":{"en":["how to use nav-stats","what is nav-stats","nav-stats alternative","nav-stats vs Claude Code","nav-stats install","nav-stats setup guide","nav-stats for AI agents","real-time efficiency reporting","context engineering for Claude Code"],"zh":["nav-stats","AI工具","实时效率报告","基线比较","Navigator技能","会话性能优化","令牌节省","AIエージェント"],"ja":["nav-stats","AIエージェント","リアルタイム効率レポート","ベースライン比較","Navigatorスキル","セッション性能最適化","トークン節約","AIツール"],"ko":["nav-stats","AIツール","실시간 효율성 보고","기준 비교","Navigator스킬","세션 성능 최적화","토큰 절약","AI에이전트"],"es":["nav-stats","Agentes de IA","Herramientas de desarrollo","Estadísticas de sesión","Informes de eficiencia","Comparaciones de referencia","Tokens de ahorro","Rendimiento de sesión"],"fr":["nav-stats","Outils d''IA","Outils de développement","Statistiques de session","Rapports d''efficacité","Comparaisons de référence","Jetons d''économie","Performances de session"],"de":["nav-stats","KI-Tools","Entwicklungstools","Sitzungsstatistiken","Echtzeit-Effizienzberichte","Referenzvergleiche","Token-Einsparungen","Sitzungsleistung"],"pt":["nav-stats","relatórios de eficiência","Claude Code","engenharia de contexto","sessões de 20+ trocas","análise de economia de tokens","relatórios de desempenho de sessão","otimização de desempenho","ferramentas de desenvolvimento"],"ru":["нав-stats","отчеты об эффективности","Claude Code","контекстная инженерия","сессии из 20+ обменов","анализ экономии токенов","отчеты о производительности сессии","оптимизация производительности","инструменты разработки"],"ar":["nav-stats","تقارير كفاءة","كلود كود","هندسة سياق","جلسات 20+ تبادلات","تحليل توفير الرموز","تقارير أداء الجلسة","تحسين الأداء","أدوات التطوير"]}},"owner":"alekspetrov","repo":"navigator","repoPath":"alekspetrov/navigator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.657Z","topics":[],"category":"community","skillMd":{"name":"nav-stats","description":"Display session efficiency report showing token savings, cache performance, and optimization recommendations. Use when user asks show my stats, how efficient am I?, show session metrics, or wants to see Navigators impact.","version":"1.0.0","bodyPreview":"# Navigator Session Statistics Skill\n\nShow real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable.\n\n## When to Invoke\n\nInvoke this skill when the user:\n- Says \"show my stats\", \"show session stats\", \"show metrics\"\n- Asks \"how efficient am I?\", \"how much did I save?\"\n- Says \"show my Navigator report\", \"efficiency report\"\n- Wants to see token savings or session performance\n- Says \"show impact\", \"prove Navigator works\"\n\n**DO NOT invoke** if:\n- U","body":"# Navigator Session Statistics Skill\n\nShow real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable.\n\n## When to Invoke\n\nInvoke this skill when the user:\n- Says \"show my stats\", \"show session stats\", \"show metrics\"\n- Asks \"how efficient am I?\", \"how much did I save?\"\n- Says \"show my Navigator report\", \"efficiency report\"\n- Wants to see token savings or session performance\n- Says \"show impact\", \"prove Navigator works\"\n\n**DO NOT invoke** if:\n- User just started session (< 5 messages)\n- Navigator not initialized in project\n- User asking about specific metrics only (answer directly)\n\n## Execution Steps\n\n### Step 1: Check Navigator Initialized\n\nVerify Navigator is set up:\n\n```bash\nif [ ! -f \".agent/DEVELOPMENT-README.md\" ]; then\n  echo \"❌ Navigator not initialized in this project\"\n  echo \"Run ''Initialize Navigator'' first\"\n  exit 1\nfi\n```\n\n### Step 2: Run Enhanced Session Stats\n\nExecute the enhanced session statistics script:\n\n```bash\n# Check if enhanced script exists\nif [ ! -f \"scripts/session-stats.sh\" ]; then\n  echo \"❌ Session stats script not found\"\n  echo \"This feature requires Navigator v3.5.0+\"\n  exit 1\nfi\n\n# Run stats script\nbash scripts/session-stats.sh\n```\n\nThis script outputs shell-parseable variables:\n- `BASELINE_TOKENS` - Total size of all .agent/ docs\n- `LOADED_TOKENS` - Actually loaded in session (estimated)\n- `TOKENS_SAVED` - Difference\n- `SAVINGS_PERCENT` - Percentage saved\n- `EFFICIENCY_SCORE` - 0-100 score\n- `CACHE_EFFICIENCY` - From OpenTelemetry\n- `CONTEXT_USAGE_PERCENT` - Estimated context fill\n- `TIME_SAVED_MINUTES` - Estimated time saved\n\n### Step 3: Calculate Efficiency Score\n\nUse predefined function to calculate score:\n\n```bash\n# Extract metrics from session-stats.sh\nsource <(bash scripts/session-stats.sh)\n\n# Calculate efficiency score using predefined function\nEFFICIENCY_SCORE=$(python3 skills/nav-stats/functions/efficiency_scorer.py \\\n  --tokens-saved-percent ${SAVINGS_PERCENT} \\\n  --cache-efficiency ${CACHE_EFFICIENCY} \\\n  --context-usage ${CONTEXT_USAGE_PERCENT})\n```\n\n### Step 4: Format and Display Report\n\nUse predefined function to format visual report:\n\n```bash\n# Generate formatted report\npython3 skills/nav-stats/functions/report_formatter.py \\\n  --baseline ${BASELINE_TOKENS} \\\n  --loaded ${LOADED_TOKENS} \\\n  --saved ${TOKENS_SAVED} \\\n  --savings-percent ${SAVINGS_PERCENT} \\\n  --cache-efficiency ${CACHE_EFFICIENCY} \\\n  --context-usage ${CONTEXT_USAGE_PERCENT} \\\n  --efficiency-score ${EFFICIENCY_SCORE} \\\n  --time-saved ${TIME_SAVED_MINUTES}\n```\n\n**Output Format**:\n```\n╔══════════════════════════════════════════════════════╗\n║          NAVIGATOR EFFICIENCY REPORT                 ║\n╚══════════════════════════════════════════════════════╝\n\n📊 TOKEN USAGE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nDocumentation loaded:        12,000 tokens\nBaseline (all docs):        150,000 tokens\nTokens saved:               138,000 tokens (92% ↓)\n\n💾 CACHE PERFORMANCE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCache efficiency:              100.0% (perfect)\n\n📈 SESSION METRICS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nContext usage:                      35% (excellent)\nEfficiency score:                94/100 (excellent)\n\n⏱️  TIME SAVED\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nEstimated time saved:          ~42 minutes\n\n💡 WHAT THIS MEANS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nNavigator loaded 92% fewer tokens than loading all docs.\nYour context window is 65% available for actual work.\n\n🎯 RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n✅ Excellent efficiency - keep using lazy-loading strategy\n✅ Context usage healthy - plenty of room for work\n\nShare your efficiency: Take a screenshot! #ContextEfficiency\n```\n\n### Step 5: Add Context-Specific Recommendations\n\nBased on efficiency score, provide actionable advice:\n\n**If efficiency_score < 70**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Token savings below target (70%+)\n→ Check: Are you loading more docs than needed?\n→ Tip: Use navigator to find docs, don''t load all upfront\n\nRead more: .agent/philosophy/CONTEXT-EFFICIENCY.md\n```\n\n**If context_usage > 80%**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Context usage high (80%+)\n→ Consider: Create context marker and compact\n→ Tip: Compact after completing sub-tasks\n\nRead more: .agent/philosophy/ANTI-PATTERNS.md\n```\n\n**If cache_efficiency < 80%**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Cache efficiency low (<80%)\n→ Check: CLAUDE.md properly configured?\n→ Tip: Ensure prompt caching enabled\n\nRead more: .agent/philosophy/PATTERNS.md (Caching pattern)\n```\n\n## Predefined Functions\n\n### `efficiency_scorer.py`\n\nCalculate Navigator efficiency score (0-100) based on:\n- Token savings (40 points)\n- Cache efficiency (30 points)\n- Context usage (30 points)\n\n**Usage**:\n```bash\npython3 skills/nav-stats/functions/efficiency_scorer.py \\\n  --tokens-saved-percent 92 \\\n  --cache-efficiency 100 \\\n  --context-usage 35\n```\n\n**Output**: `94` (integer score)\n\n### `report_formatter.py`\n\nFormat efficiency metrics into visual, shareable report.\n\n**Usage**:\n```bash\npython3 skills/nav-stats/functions/report_formatter.py \\\n  --baseline 150000 \\\n  --loaded 12000 \\\n  --saved 138000 \\\n  --savings-percent 92 \\\n  --cache-efficiency 100 \\\n  --context-usage 35 \\\n  --efficiency-score 94 \\\n  --time-saved 42\n```\n\n**Output**: Formatted ASCII report (see Step 4)\n\n## Philosophy Integration\n\n**Context Engineering Principle**: Measurement validates optimization\n\nFrom `.agent/philosophy/PATTERNS.md`:\n> \"Measure to validate. Navigator tracks real metrics, not estimates.\"\n\nThis skill proves:\n- **Token savings** are real (baseline comparison)\n- **Cache efficiency** works (OpenTelemetry data)\n- **Context usage** is healthy (window not overloaded)\n- **Time saved** is quantifiable (6s per 1k tokens)\n\n## User Experience\n\n**User says**: \"Show my stats\"\n\n**Skill displays**:\n1. Visual efficiency report\n2. Clear metrics (tokens, cache, context)\n3. Interpretation (\"What this means\")\n4. Actionable recommendations\n\n**User can**:\n- Screenshot and share (#ContextEfficiency)\n- Understand Navigator''s impact\n- Optimize workflow based on recommendations\n- Validate context engineering principles\n\n## Example Output Scenarios\n\n### Scenario 1: Excellent Efficiency (Score 94)\n\nUser following lazy-loading pattern, cache working perfectly:\n- 92% token savings ✅\n- 100% cache efficiency ✅\n- 35% context usage ✅\n- Score: 94/100\n\n**Recommendation**: Keep it up! Share your efficiency.\n\n### Scenario 2: Fair Efficiency (Score 72)\n\nUser loading too many docs upfront:\n- 65% token savings ⚠️\n- 95% cache efficiency ✅\n- 55% context usage ✅\n- Score: 72/100\n\n**Recommendation**: Review lazy-loading strategy. Load docs on-demand.\n\n### Scenario 3: Poor Efficiency (Score 48)\n\nUser not using Navigator patterns:\n- 45% token savings ❌\n- 70% cache efficiency ⚠️\n- 85% context usage ❌\n- Score: 48/100\n\n**Recommendation**: Read philosophy docs. Consider /nav:compact. Review CLAUDE.md.\n\n## Success Metrics\n\n**After using this skill, users should**:\n- Understand their efficiency score\n- See quantified token savings\n- Know what to improve (if anything)\n- Feel motivated to share results\n\n**Long-term impact**:\n- Users screenshot reports and share\n- \"Navigator saved me 138k tokens\" becomes common\n- Efficiency becomes visible, not abstract\n- Continuous improvement through measurement\n\n---\n\n**This skill makes Navigator''s value tangible and shareable.**\n"},"lastSynced":"2026-03-08T02:13:58.346Z","agentAnalysis":{"suitability":{"en":"Perfect for Efficiency Analysis Agents needing real-time session statistics and token savings metrics.","zh":"非常适合需要实时会话统计和令牌节省指标的效率分析代理","ja":"リアルタイムのセッション統計とトークン節約メトリクスが必要な効率分析エージェントに最適","ko":"실시간 세션 통계 및 토큰 절약 메트릭이 필요한 효율성 분석 에이전트에 적합","es":"Perfecto para agentes de Análisis de Eficiencia que necesitan estadísticas de sesión en tiempo real y métricas de ahorro de tokens.","fr":"Parfait pour les agents d''analyse d''efficacité nécessitant des statistiques de session en temps réel et des métriques d''économie de jetons.","de":"Perfekt für Effizienzanalyse-Agents, die Echtzeit-Sitzungsstatistiken und Token-Sparmetrics benötigen.","pt":"Perfeito para Agentes de Análise de Eficiência que necessitam de estatísticas de sessão em tempo real e métricas de economia de tokens.","ru":"Идеально подходит для агентов анализа эффективности, требующих статистики сеанса в реальном времени и метрик экономии токенов.","ar":"مثالي لعمليات تحليل كفاءة الوكلاء التي تحتاج إلى إحصائيات الجلسة في الوقت الفعلي وأرقام توفير الرموز."},"recommendation":{"en":"Empowers agents to provide quantifiable efficiency reporting with baseline comparisons, utilizing real-time metrics such as token savings and session performance, making Navigator''s value shareable through comprehensive reports.","zh":"赋予代理提供可量化的效率报告能力，利用基线比较和实时指标，如令牌节省和会话性能，使 Navigator 的价值可以通过综合报告共享","ja":"エージェントが定量的な効率報告を提供できるようにし、基準比較やリアルタイムのメトリクス（トークン節約、セッションパフォーマンスなど）を利用して、Navigator の価値を包括的な報告書で共有できるようにする","ko":"에이전트가 정량적인 효율성 보고서를 제공할 수 있도록 하며, 기준 비교 및 실시간 메트릭스(토큰 절약, 세션 성능 등)을 활용하여 네비게이터의 가치를 포괄적인 보고서로 공유할 수 있도록 한다","es":"Habilita a los agentes a proporcionar informes de eficiencia cuantificables con comparaciones de referencia, utilizando métricas en tiempo real como el ahorro de tokens y el rendimiento de la sesión, lo que permite compartir el valor de Navigator a través de informes exhaustivos.","fr":"Permet aux agents de fournir des rapports d''efficacité quantifiables avec des comparaisons de référence, en utilisant des métricas en temps réel telles que les économies de jetons et les performances de session, ce qui permet de partager la valeur de Navigator grâce à des rapports complets.","de":"Ermöglicht es Agents, quantifizierbare Effizienzberichte mit Vergleichswerten zu liefern, indem sie Echtzeit-Metriken wie Token-Einsparungen und Sitzungsleistung verwenden, wodurch Navigators Wert durch umfassende Berichte teilbar wird.","pt":"Habilita os agentes a fornecer relatórios de eficiência quantificáveis com comparações de baseline, utilizando métricas em tempo real, como economia de tokens e desempenho da sessão, tornando a participação de valor do Navigator compartilhável por meio de relatórios abrangentes.","ru":"Наделяет агентов возможностью предоставлять количественные отчеты об эффективности с сравнениями базовой линии, используя метрики в реальном времени, такие как экономия токенов и производительность сеанса, что делает долю стоимости Navigator общедоступной посредством всесторонних отчетов.","ar":"تمكّن الوكلاء من تقديم تقارير قابلة للقياس عن الكفاءة مع مقارنات الخط الأساسي، باستخدام مقاييس في الوقت الفعلي مثل توفير الرموز وأداء الجلسة، مما يجعل حصة قيمة Navigator قابلة للمشاركة من خلال تقارير شاملة."},"useCases":{"en":["Generating real-time efficiency reports for Navigator sessions","Comparing baseline metrics to evaluate session performance","Calculating token savings for optimized resource allocation"],"zh":["为 Navigator 会话生成实时效率报告","比较基线指标以评估会话性能","计算令牌节省以优化资源分配"],"ja":["Navigator セッションのリアルタイム効率報告を生成する","基準メトリクスを比較してセッションパフォーマンスを評価する","最適なリソース割り当てのためにトークン節約を計算する"],"ko":["네비게이터 세션에 대한 실시간 효율성 보고서 생성","세션 성능 평가를 위한 기준 메트릭스 비교","최적의 리소스 할당을 위한 토큰 절약 계산"],"es":["Generar informes de eficiencia en tiempo real para sesiones de Navigator","Comparar métricas de referencia para evaluar el rendimiento de la sesión","Calcular el ahorro de tokens para una asignación de recursos optimizada"],"fr":["Générer des rapports d''efficacité en temps réel pour les sessions de Navigator","Comparer les métriques de référence pour évaluer les performances de session","Calculer les économies de jetons pour une allocation de ressources optimisée"],"de":["Erzeugen von Echtzeit-Effizienzberichten für Navigator-Sitzungen","Vergleichen von Referenzmetriken zur Bewertung der Sitzungsleistung","Berechnen von Token-Einsparungen für eine optimierte Ressourcenzuweisung"],"pt":["Gerar relatórios de eficiência em tempo real para sessões do Navigator","Comparar métricas de baseline para avaliar o desempenho da sessão","Calcular a economia de tokens para alocação de recursos otimizada"],"ru":["Генерировать отчеты об эффективности в реальном времени для сеансов Navigator","Сравнивать метрики базовой линии для оценки производительности сеанса","Рассчитывать экономию токенов для оптимизированного распределения ресурсов"],"ar":["توليد تقارير عن الكفاءة في الوقت الفعلي لجلسات Navigator","مقارنة مقاييس الخط الأساسي لتقييم أداء الجلسة","حساب توفير الرموز لتحديد الموارد المثلى"]},"limitations":{"en":["Requires invocation through specific user queries","Limited to Navigator session statistics and efficiency metrics"],"zh":["需要通过特定的用户查询调用","仅限 Navigator 会话统计和效率指标"],"ja":["特定のユーザー クエリを介して呼び出される必要がある","Navigator セッション統計と効率メトリクスに限定される"],"ko":["특정 사용자 쿼리를 통해 호출해야 함","네비게이터 세션 통계 및 효율성 메트릭스에 한정됨"],"es":["Requiere invocación a través de consultas de usuario específicas","Limitado a estadísticas de sesión y métricas de eficiencia de Navigator"],"fr":["Nécessite une invocation via des requêtes utilisateur spécifiques","Limité aux statistiques de session et aux métriques d''efficacité de Navigator"],"de":["Erfordert Aufruf über bestimmte Benutzerabfragen","Begrenzt auf Sitzungsstatistiken und Effizienzmetriken von Navigator"],"pt":["Requer invocação por meio de consultas de usuário específicas","Limitado a estatísticas de sessão e métricas de eficiência do Navigator"],"ru":["Требует вызова через конкретные запросы пользователя","Ограничен статистикой сеанса и метриками эффективности Navigator"],"ar":["يتطلب استدعاءً من خلال استفسارات مستخدم محددة","محدود بإحصائيات الجلسة وأرقام كفاءة Navigator"]},"version":4},"contentHash":"534fdddf7028538dba06aebd55a07bf26a7587bc151eb4c4ff8737c19678f3c8","qualityScore":41}');
