INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alekspetrov/navigator/nav-stats', 'nav-stats', 'alekspetrov', 'navigator', 'community', 'nav-stats alekspetrov navigator community nav-stats is a skill that provides real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable. It benefits developers by showing token savings, session performance, and efficiency metrics. nav-stats技能提供实时效率报告与基线比较，优化Navigator会话，提高会话效率 nav-statsスキルはリアルタイムの効率レポートとベースライン比較を提供し、Navigatorセッションを最適化します nav-stats 스킬은 실시간 효율성 보고와 기준 비교를 제공하여 Navigator 세션을 최적화합니다 nav-stats es una habilidad que proporciona informes de eficiencia en tiempo real y comparaciones de referencia para mejorar la productividad de tus sesiones de desarrollo nav-stats est une compétence qui fournit des rapports d''efficacité en temps réel et des comparaisons de référence pour améliorer la productivité de vos sessions de développement nav-stats ist eine Fähigkeit, die Echtzeit-Effizienzberichte und Referenzvergleiche bereitstellt, um die Produktivität Ihrer Entwicklungssitzungen zu verbessern O nav-stats é uma habilidade que fornece relatórios de eficiência em tempo real com comparações de baseline, tornando o valor do Navigator quantificável e compartilhável. Нав-stats - это навык, который предоставляет отчеты об эффективности в реальном времени с сравнениями базового уровня, что делает ценность Navigator количественной и общедоступной. nav-stats هو مهارة توفر تقارير كفاءة الوقت الفعلي مع مقارنات الأساس، مما يجعل قيمة Navigator كمية وقابلة للمشاركة. how to use nav-stats what is nav-stats nav-stats alternative nav-stats vs Claude Code nav-stats install nav-stats setup guide nav-stats for AI agents real-time efficiency reporting context engineering for Claude Code nav-stats AI工具 实时效率报告 基线比较 Navigator技能 会话性能优化 令牌节省 AIエージェント Shows real-time efficiency reporting with baseline comparisons Provides token savings and session performance metrics Supports invocation via commands like ''show my stats'' and ''show session stats'' Generates efficiency reports and metrics on demand Enables users to ask questions like ''how efficient am I?'' and ''how much did I save?'' Displays impact and proves Navigator''s value nav-stats is a context engineering skill for Claude Code that enables real-time efficiency reporting and baseline comparisons for Navigator sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cuozg/oh-my-unity/unity-review-quality', 'community', 'cuozg', 'oh-my-unity', 'cuozg/oh-my-unity', 'unity-review-quality', 0, 0, 41, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:06.717Z', '5af3c4d7a39fd043c1ebc52ec9ae59fe00b403a61a3a32d989699256a49e921d', '{"id":"cuozg/oh-my-unity/unity-review-quality","name":"unity-review-quality","description":{"en":"The unity-review-quality skill scans a Unity project read-only, grading its architecture, performance, best practices, and tech debt on an A–F scale. It benefits developers onboarding to unfamiliar Unity codebases, pre-release quality gates, and quarterly tech debt audits.","zh":"Unity代码审查质量AI工具扫描Unity项目，评估架构、性能、最佳实践和技术债务，生成综合HTML报告","ja":"Unityコードレビュー品質AIエージェントは、Unityプロジェクトをスキャンし、構造、パフォーマンス、ベストプラクティス、技術債を評価し、包括的なHTMLレポートを生成します","ko":"Unity 코드 리뷰 품질 AI 에이전트는 Unity 프로젝트를 스캔하고, 구조, 성능, 최선의實践, 기술 부채를 평가하여 포괄적인 HTML 보고서를 생성합니다","es":"unity-review-quality analiza la arquitectura y el rendimiento de tus proyectos Unity, generando un informe HTML detallado","fr":"unity-review-quality analyse l''architecture et les performances de vos projets Unity, générant un rapport HTML détaillé","de":"unity-review-quality analysiert die Architektur und Leistung Ihrer Unity-Projekte, erzeugt einen detaillierten HTML-Bericht","pt":"O unity-review-quality é uma ferramenta que analisa projetos Unity e fornece relatórios detalhados sobre arquitetura, desempenho e boas práticas","ru":"unity-review-quality - это инструмент, который анализирует проекты Unity и предоставляет подробные отчеты об архитектуре, производительности и лучших практиках","ar":"unity-review-quality هو أداة تحليل لمشاريع Unity وتقدم تقارير متعمقة حول الهيكلة والأداء وأفضل الممارسات"},"seo":{"title":{"en":"unity-review-quality: Comprehensive Unity Project Analysi...","zh":"Unity 代码审查质量 Setup Guide - AI工具","ja":"Unityコードレビュー品質 Setup Guide - AIエージェント","ko":"Unity 코드 리뷰 품질 Setup Guide - AI 에이전트","es":"Guía de configuración para unity-review-quality: Análisis...","fr":"Guide d''installation pour unity-review-quality : Analyse ...","de":"Einrichtungsleitfaden für unity-review-quality: Architekt...","pt":"Guia de Configuração do unity-review-quality para Análise...","ru":"ИИ Агенты: unity-review-quality Настройка Руководства для...","ar":"دليل إعداد unity-review-quality لمراجعة مشاريع Unity"},"description":{"en":"Unlock the full potential of your Unity project with unity-review-quality. Get a detailed HTML report on architecture, performance, and tech debt. Try it now...","zh":"使用Unity代码审查质量AI工具，扫描Unity项目，评估架构、性能、最佳实践和技术债务，生成综合HTML报告","ja":"Unityコードレビュー品質AIエージェントを使用して、Unityプロジェクトをスキャンし、構造、パフォーマンス、ベストプラクティス、技術債を評価し、包括的なHTMLレポートを生成します","ko":"Unity 코드 리뷰 품질 AI 에이전트를 사용하여 Unity 프로젝트를 스캔하고, 구조, 성능, 최선의實践, 기술 부채를 평가하여 포괄적인 HTML 보고서를 생성합니다","es":"Mejora la calidad de tus proyectos Unity con unity-review-quality, que analiza la arquitectura, el rendimiento y las mejores prácticas","fr":"Améliorez la qualité de vos projets Unity avec unity-review-quality, qui analyse l''architecture, les performances et les meilleures pratiques","de":"Verbessern Sie die Qualität Ihrer Unity-Projekte mit unity-review-quality, das Architektur, Leistung und Best Practices analysiert","pt":"Aprenda a configurar o unity-review-quality para analisar projetos Unity e melhorar a qualidade do código","ru":"Узнайте, как настроить unity-review-quality для анализа проектов Unity и улучшения качества кода с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد unity-review-quality لمراجعة مشاريع Unity وتحسين جودة الكود"},"definition":{"en":"unity-review-quality is a skill that analyzes Unity projects, providing a comprehensive report on architecture, performance, best practices, and tech debt, helping developers identify areas for improvement.","zh":"Unity代码审查质量是AI工具，扫描Unity项目，评估架构、性能、最佳实践和技术债务","ja":"Unityコードレビュー品質は、AIエージェントであり、Unityプロジェクトをスキャンし、構造、パフォーマンス、ベストプラクティス、技術債を評価します","ko":"Unity 코드 리뷰 품질은 AI 에이전트로서 Unity 프로젝트를 스캔하고, 구조, 성능, 최선의實践, 기술 부채를 평가합니다","es":"unity-review-quality es una herramienta de análisis de código que evalúa la calidad de los proyectos Unity","fr":"unity-review-quality est un outil d''analyse de code qui évalue la qualité des projets Unity","de":"unity-review-quality ist ein Code-Analyse-Tool, das die Qualität von Unity-Projekten bewertet","pt":"O que é unity-review-quality? É uma ferramenta de análise de projetos Unity que avalia a arquitetura, desempenho e boas práticas","ru":"Что такое unity-review-quality? Это инструмент анализа проектов Unity, который оценивает архитектуру, производительность и лучшие практики","ar":"ما هو unity-review-quality؟ هو أداة تحليل لمشاريع Unity تقييم الهيكلة والأداء وأفضل الممارسات"},"features":{"en":["Scans Unity projects read-only, analyzing .cs, .prefab, .unity, .asmdef, and .asset files","Grades architecture, performance, best practices, and tech debt on an A–F scale with evidence","Generates a comprehensive HTML report for detailed analysis","Checks Dependency Injection (DI) patterns for optimal architecture","Records file counts for .cs, .prefab, .unity, .asmdef, and .asset files"],"zh":["扫描Unity项目，评估架构、性能、最佳实践和技术债务","生成综合HTML报告","支持DI检查","支持ASMDEF文件分析","支持Unity项目结构分析","支持技术债务评估"],"ja":["Unityプロジェクトをスキャンし、構造、パフォーマンス、ベストプラクティス、技術債を評価します","包括的なHTMLレポートを生成します","DIチェックをサポートします","ASMDEFファイル分析をサポートします","Unityプロジェクト構造分析をサポートします","技術債評価をサポートします"],"ko":["Unity 프로젝트를 스캔하고, 구조, 성능, 최선의實践, 기술 부채를 평가합니다","포괄적인 HTML 보고서를 생성합니다","DI 체크를 지원합니다","ASMDEF 파일 분석을 지원합니다","Unity 프로젝트 구조 분석을 지원합니다","기술 부채 평가를 지원합니다"],"es":["Análisis de arquitectura y rendimiento","Generación de informes HTML detallados","Evaluación de las mejores prácticas y la deuda técnica","Compatibilidad con archivos .cs, .prefab, .unity, .asmdef y .asset","Integración con el proceso de desarrollo de Unity"],"fr":["Analyse d''architecture et de performances","Génération de rapports HTML détaillés","Évaluation des meilleures pratiques et de la dette technique","Compatibilité avec les fichiers .cs, .prefab, .unity, .asmdef et .asset","Intégration avec le processus de développement Unity"],"de":["Architektur- und Leistungsanalyse","Erzeugung detaillierter HTML-Berichte","Bewertung von Best Practices und technischer Schulden","Kompatibilität mit Dateien .cs, .prefab, .unity, .asmdef und .asset","Integration mit dem Unity-Entwicklungsprozess"],"pt":["Análise de arquitetura de projetos Unity","Avaliação de desempenho e boas práticas","Geração de relatórios detalhados em HTML","Suporte a análise de projetos em diferentes fases do ciclo de vida","Integração com ferramentas de desenvolvimento de jogos"],"ru":["Анализ архитектуры проектов Unity","Оценка производительности и лучших практик","Генерация подробных отчетов в HTML","Поддержка анализа проектов на разных стадиях жизненного цикла","Интеграция с инструментами разработки игр"],"ar":["تحليل هيكلة مشاريع Unity","تقييم الأداء وأفضل الممارسات","توليد تقارير متعمقة بالصيغة HTML","دعم تحليل المشاريع في مراحل مختلفة من دورة الحياة","التكامل مع أدوات تطوير الألعاب"]},"keywords":{"en":["unity-review-quality setup guide","how to use unity-review-quality for Unity project analysis","unity-review-quality vs other code analysis tools","unity-review-quality install for AI agents","what is unity-review-quality and its benefits","unity-review-quality alternative for tech debt audit","unity-review-quality best practices for Unity development","unity-review-quality tutorial for comprehensive project analysis"],"zh":["Unity代码审查质量","AI工具","代码审查","Unity项目","架构评估","性能优化","最佳实践","技术债务","HTML报告"],"ja":["Unityコードレビュー品質","AIエージェント","コードレビュー","Unityプロジェクト","構造評価","パフォーマンス最適化","ベストプラクティス","技術債","HTMLレポート"],"ko":["Unity 코드 리뷰 품질","AI 에이전트","코드 리뷰","Unity 프로젝트","구조 평가","성능 최적화","최선의實践","기술 부채","HTML 보고서"],"es":["unity-review-quality","análisis de código Unity","mejores prácticas de Unity","deuda técnica en Unity","informes de calidad de Unity","herramientas de desarrollo de Unity","optimización de rendimiento de Unity"],"fr":["unity-review-quality","analyse de code Unity","meilleures pratiques Unity","dette technique dans Unity","rapports de qualité Unity","outils de développement Unity","optimisation des performances Unity"],"de":["unity-review-quality","Code-Analyse für Unity","Best Practices für Unity","technische Schulden in Unity","Qualitätsberichte für Unity","Entwicklertools für Unity","Leistungsoptimierung für Unity"],"pt":["unity-review-quality","análise de projetos Unity","boas práticas de desenvolvimento de jogos","otimização de desempenho Unity","ferramentas de desenvolvimento de jogos","análise de arquitetura de projetos","relatórios de análise de projetos"],"ru":["unity-review-quality","анализ проектов Unity","лучшие практики разработки игр","оптимизация производительности Unity","инструменты разработки игр","анализ архитектуры проектов","отчеты анализа проектов"],"ar":["unity-review-quality","تحليل مشاريع Unity","أفضل الممارسات لتطوير الألعاب","تحسين الأداء في Unity","أدوات تطوير الألعاب","تحليل هيكلة المشاريع","تقارير تحليل المشاريع"]}},"owner":"cuozg","repo":"oh-my-unity","repoPath":"cuozg/oh-my-unity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"unity-review-quality","description":"Full Unity project audit — A-F graded HTML report covering architecture, performance, best practices, tech debt. Triggers — project audit, quality audit, project review, code quality report, tech debt audit.","bodyPreview":"# unity-review-quality\n\nScan a Unity project read-only, grade architecture, performance, best practices, and tech debt on an A–F scale with evidence, and generate a comprehensive HTML report.\n\n## When to Use\n\n- Onboarding to an unfamiliar Unity codebase\n- Pre-release quality gate for a shipped title\n- Quarterly tech debt audit for a live game\n\n## Workflow\n\n1. **Scope project** — list all `.cs`, `.prefab`, `.unity`, `.asmdef`, `.asset` files; record counts\n2. **Analyze architecture** — check DI p","body":"# unity-review-quality\n\nScan a Unity project read-only, grade architecture, performance, best practices, and tech debt on an A–F scale with evidence, and generate a comprehensive HTML report.\n\n## When to Use\n\n- Onboarding to an unfamiliar Unity codebase\n- Pre-release quality gate for a shipped title\n- Quarterly tech debt audit for a live game\n\n## Workflow\n\n1. **Scope project** — list all `.cs`, `.prefab`, `.unity`, `.asmdef`, `.asset` files; record counts\n2. **Analyze architecture** — check DI patterns, assembly structure, coupling, event systems, singleton count\n3. **Analyze performance** — scan for hot-path allocations, `FindObjectOfType`, per-frame `GetComponent`, excessive coroutines\n4. **Evaluate best practices** — null handling, serialization safety, test coverage presence, naming conventions\n5. **Measure tech debt** — TODO/FIXME count, dead code, magic numbers, file length outliers\n6. **Grade each category** — apply A–F rubric from `references/quality-grading-rubric.md`\n7. **Generate HTML report** — use structure from `unity-standards/references/quality/html-report-format.md`; embed evidence snippets\n\n## Rules\n\n- Read files only — never modify source code or assets\n- Assign one grade per category: Architecture, Performance, Best Practices, Tech Debt\n- Every grade must cite at least one evidence file path + line number\n- F grade requires 3+ CRITICAL violations in that category\n- A grade requires zero violations and positive evidence\n- Include a \"Top 5 Priority Fixes\" section ranked by severity × frequency\n- Do not average grades into an overall score — list each separately\n- Flag `FindObjectOfType` calls as performance violations (not architectural)\n- Flag missing `.asmdef` files in a project > 50 scripts as Architecture WARNING\n- Flag test coverage below 10% (by file count) as Best Practices WARNING\n- Save report to `Documents/QualityAudit_{date}.html` unless path overridden\n\n## Output Format\n\nHTML report file at `Documents/QualityAudit_{date}.html` with A-F grades per category, evidence table, and prioritized fix list.\n\n## Reference Files\n\n- `references/quality-grading-rubric.md` — per-category A-F descriptions (loads `unity-standards/references/quality/grading-criteria.md` for scale + formula)\n\nLoad references on demand via `read_skill_file(\"unity-review-quality\", \"references/{file}\")` and `read_skill_file(\"unity-standards\", \"references/quality/grading-criteria.md\")`.\n\n## Standards\n\nLoad `unity-standards` for audit criteria. Key references:\n\n- `quality/grading-criteria.md` — A-F scale definitions, evidence requirements\n- `quality/architecture-audit.md` — coupling, layering, assembly structure\n- `quality/performance-audit.md` — profiler markers, memory, frame budget\n- `quality/best-practices-audit.md` — Unity API usage, deprecated calls\n- `quality/tech-debt-audit.md` — TODO density, code duplication, complexity\n\nLoad via `read_skill_file(\"unity-standards\", \"references/quality/<file>\")`.\n"},"lastSynced":"2026-03-08T02:14:06.717Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents specializing in Unity project analysis and optimization.","zh":"非常适合专门从事Unity项目分析和优化的代码审查代理。","ja":"Unityプロジェクト分析および最適化を専門とするコードレビュー代理に最適です。","ko":"Unity 프로젝트 분석 및 최적화를 전문으로 하는 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código especializados en análisis y optimización de proyectos de Unity.","fr":"Parfait pour les Agents de Revue de Code spécialisés dans l''analyse et l''optimisation de projets Unity.","de":"Perfekt für Code-Review-Agenten, die auf die Analyse und Optimierung von Unity-Projekten spezialisiert sind.","pt":"Perfeito para Agentes de Revisão de Código especializados em análise e otimização de projetos Unity.","ru":"Идеально подходит для агентов код-ревью, специализирующихся на анализе и оптимизации проектов Unity.","ar":"مثالي لمنسقي استعراض الشفرة الذين يختصون في تحليل مشاريع Unity وضبط أدائها."},"recommendation":{"en":"Empowers agents to scan Unity projects read-only, grading architecture, performance, best practices, and tech debt on an A–F scale, generating comprehensive HTML reports with evidence, utilizing file formats like `.cs`, `.prefab`, `.unity`, `.asmdef`, and `.asset`.","zh":"赋予代理扫描Unity项目的只读权限，评估架构、性能、最佳实践和技术债务，采用A–F评分标准，生成包含证据的综合HTML报告，利用文件格式如`.cs`、`.prefab`、`.unity`、`.asmdef`和`.asset`。","ja":"エージェントにUnityプロジェクトを読み取り専用でスキャンする権限を与え、アーキテクチャ、パフォーマンス、ベストプラクティス、およびテクニカルデットをA–F評価基準で評価し、証拠を含む包括的なHTMLレポートを生成する、`.cs`、`.prefab`、`.unity`、`.asmdef`、`.asset`などのファイル形式を使用する。","ko":"에이전트가 Unity 프로젝트를 읽기 전용으로 스캔할 수 있도록 하여 아키텍처, 성능, 모범 사례 및 기술 부채를 A–F 평가 기준으로 평가하고, 증거를 포함한 포괄적인 HTML 보고서를 생성하며, `.cs`, `.prefab`, `.unity`, `.asmdef`, `.asset` 등의 파일 형식을 사용합니다.","es":"Habilita a los agentes a escanear proyectos de Unity de solo lectura, calificando la arquitectura, el rendimiento, las mejores prácticas y la deuda técnica en una escala de A a F, generando informes HTML completos con evidencia, utilizando formatos de archivo como `.cs`, `.prefab`, `.unity`, `.asmdef` y `.asset`.","fr":"Permet aux agents d''analyser les projets Unity en lecture seule, notant l''architecture, les performances, les bonnes pratiques et la dette technique sur une échelle de A à F, générant des rapports HTML complets avec preuves, en utilisant des formats de fichiers tels que `.cs`, `.prefab`, `.unity`, `.asmdef` et `.asset`.","de":"Ermächtigt die Agenten, Unity-Projekte nur zum Lesen zu scannen, bewertet die Architektur, Leistung, Best Practices und technische Schulden auf einer Skala von A bis F, generiert umfassende HTML-Berichte mit Beweisen, unter Verwendung von Dateiformaten wie `.cs`, `.prefab`, `.unity`, `.asmdef` und `.asset`.","pt":"Habilita os agentes a digitalizar projetos Unity somente leitura, graduando a arquitetura, o desempenho, as melhores práticas e a dívida técnica em uma escala de A a F, gerando relatórios HTML abrangentes com evidências, utilizando formatos de arquivo como `.cs`, `.prefab`, `.unity`, `.asmdef` e `.asset`.","ru":"Позволяет агентам сканировать проекты Unity только для чтения, оценивая архитектуру, производительность, лучшие практики и технический долг по шкале от A до F,生成ируя комплексные отчеты HTML с доказательствами, используя форматы файлов как `.cs`, `.prefab`, `.unity`, `.asmdef` и `.asset`.","ar":"تمكّن الوكلاء من مسح مشاريع Unity للقراءة فقط، وتقدير الهيكلية والأداء وأفضل الممارسات والديون الفنية على مقياس من A إلى F، وتوليد تقارير HTML شاملة مع الأدلة، باستخدام تنسيقات الملفات مثل `.cs` و `.prefab` و `.unity` و `.asmdef` و `.asset`."},"useCases":{"en":["Onboarding to unfamiliar Unity codebases","Implementing pre-release quality gates for shipped titles","Conducting quarterly tech debt audits for live games"],"zh":["适应不熟悉的Unity代码库","为已发布的标题实施预发布质量门槛","进行季度技术债务审计以维护现有游戏"],"ja":["未経験のUnityコードベースへのオンボーディング","出荷済みタイトルへの事前リリース品質ゲートの実施","ライブゲームの季節的なテクニカルデット審査"],"ko":["익숙하지 않은 Unity 코드베이스에 대한 온보딩","출시된 타이틀에 대한 사전 출시 품질 게이트 구현","라이브 게임에 대한 분기별 기술 부채 감사"],"es":["Integración en bases de código de Unity desconocidas","Implementación de puertas de calidad prelanzamiento para títulos enviados","Realización de auditorías trimestrales de deuda técnica para juegos en vivo"],"fr":["Intégration à des bases de code Unity inconnues","Mise en œuvre de portes de qualité pré-version pour les titres expédiés","Réalisation d''audits trimestriels de dette technique pour les jeux en cours"],"de":["Integration in unbekannte Unity-Codebasen","Implementierung von Qualitätsprüfungen vor der Veröffentlichung für versandte Titel","Durchführung von quartalsweisen Technische-Schulden-Audits für Live-Spiele"],"pt":["Integração a código de base Unity desconhecido","Implementação de portões de qualidade pré-lançamento para títulos expedidos","Realização de auditorias trimestrais de dívida técnica para jogos ao vivo"],"ru":["Ввод в кодовую базу Unity","Реализация предварительных ворот качества для отправленных названий","Проведение квартальных аудитов технического долга для живых игр"],"ar":["التكامل مع قاعدة كود Unity غير المألوفة","تنفيذ أبواب جودة ما قبل الإصدار لألقاب المرسلة","إجراء مراجعات ربع سنوية للديون الفنية للألعاب الحية"]},"limitations":{"en":["Requires read-only access to Unity project files","Limited to Unity projects only","Grading scale may require customization for specific project needs"],"zh":["需要对Unity项目文件具有只读访问权限","仅限于Unity项目","评分标准可能需要根据具体项目需求进行自定义"],"ja":["Unityプロジェクトファイルへの読み取り専用アクセスが必要","Unityプロジェクトのみに限定","評価基準は特定のプロジェクトニーズに応じてカスタマイズが必要になる可能性"],"ko":["Unity 프로젝트 파일에 대한 읽기 전용 액세스가 필요","Unity 프로젝트에만 제한","평가 기준은 특정 프로젝트 요구 사항에 따라 사용자 지정이 필요할 수 있음"],"es":["Requiere acceso de solo lectura a los archivos del proyecto de Unity","Limitado a proyectos de Unity solo","La escala de calificación puede requerir personalización para necesidades de proyecto específicas"],"fr":["Nécessite un accès en lecture seule aux fichiers du projet Unity","Limité aux projets Unity uniquement","L''échelle de notation peut nécessiter une personnalisation pour les besoins spécifiques du projet"],"de":["Benötigt Lesezugriff auf die Dateien des Unity-Projekts","Begrenzt auf Unity-Projekte nur","Die Bewertungsskala kann eine Anpassung für spezifische Projektanforderungen erfordern"],"pt":["Exige acesso somente leitura a arquivos de projeto Unity","Limitado a projetos Unity apenas","A escala de graduação pode exigir personalização para necessidades de projeto específicas"],"ru":["Требует доступа только для чтения к файлам проекта Unity","Ограничен проектами Unity только","Шкала оценки может требовать настройки для конкретных потребностей проекта"],"ar":["يتطلب الوصول القراءة فقط إلى ملفات مشروع Unity","محدود بمشاريع Unity فقط","مقياس التصنيف قد يحتاج إلى تخصيص لاحتياجات مشروع محددة"]},"version":4},"contentHash":"5af3c4d7a39fd043c1ebc52ec9ae59fe00b403a61a3a32d989699256a49e921d","qualityScore":41}');
