INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cuozg/oh-my-unity/unity-review-quality', 'unity-review-quality', 'cuozg', 'oh-my-unity', 'community', 'unity-review-quality cuozg oh-my-unity community The unity-review-quality skill scans a Unity project read-only, grading its architecture, performance, best practices, and tech debt on an A–F scale. It benefits developers onboarding to unfamiliar Unity codebases, pre-release quality gates, and quarterly tech debt audits. Unity代码审查质量AI工具扫描Unity项目，评估架构、性能、最佳实践和技术债务，生成综合HTML报告 Unityコードレビュー品質AIエージェントは、Unityプロジェクトをスキャンし、構造、パフォーマンス、ベストプラクティス、技術債を評価し、包括的なHTMLレポートを生成します Unity 코드 리뷰 품질 AI 에이전트는 Unity 프로젝트를 스캔하고, 구조, 성능, 최선의實践, 기술 부채를 평가하여 포괄적인 HTML 보고서를 생성합니다 unity-review-quality analiza la arquitectura y el rendimiento de tus proyectos Unity, generando un informe HTML detallado unity-review-quality analyse l''architecture et les performances de vos projets Unity, générant un rapport HTML détaillé unity-review-quality analysiert die Architektur und Leistung Ihrer Unity-Projekte, erzeugt einen detaillierten HTML-Bericht O unity-review-quality é uma ferramenta que analisa projetos Unity e fornece relatórios detalhados sobre arquitetura, desempenho e boas práticas unity-review-quality - это инструмент, который анализирует проекты Unity и предоставляет подробные отчеты об архитектуре, производительности и лучших практиках unity-review-quality هو أداة تحليل لمشاريع Unity وتقدم تقارير متعمقة حول الهيكلة والأداء وأفضل الممارسات unity-review-quality setup guide how to use unity-review-quality for Unity project analysis unity-review-quality vs other code analysis tools unity-review-quality install for AI agents what is unity-review-quality and its benefits unity-review-quality alternative for tech debt audit unity-review-quality best practices for Unity development unity-review-quality tutorial for comprehensive project analysis Unity代码审查质量 AI工具 代码审查 Unity项目 架构评估 性能优化 最佳实践 技术债务 HTML报告 Scans Unity projects read-only, analyzing .cs, .prefab, .unity, .asmdef, and .asset files Grades architecture, performance, best practices, and tech debt on an A–F scale with evidence Generates a comprehensive HTML report for detailed analysis Checks Dependency Injection (DI) patterns for optimal architecture Records file counts for .cs, .prefab, .unity, .asmdef, and .asset files unity-review-quality is a skill that analyzes Unity projects, providing a comprehensive report on architecture, performance, best practices, and tech debt, helping developers identify areas for improvement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('richardgill/nix/upgrade-flake', 'community', 'richardgill', 'nix', 'richardgill/nix', 'upgrade-flake', 29, 1, 41, '2026-02-25T22:59:24Z', '2026-03-06T06:39:19.593Z', 'b3b49f264c12bf5409efe1121b56e136a0935a0665fffaa22b309e3abed4a867', '{"id":"richardgill/nix/upgrade-flake","name":"upgrade-flake","description":{"en":"The upgrade-flake skill updates `flake.lock` to pull in the latest commits from all flake inputs, benefiting NixOS developers. It safely updates packages without changing release channels.","zh":"Upgrade Flake更新flake.lock文件，获取最新的包版本，不改变NixOS版本","ja":"Upgrade Flakeはflake.lockファイルを更新し、最新のパッケージバージョンを取得します","ko":"Upgrade Flake는 flake.lock 파일을 업데이트하고 최신 패키지 버전을 가져옵니다","es":"Upgrade-flake actualiza los commits más recientes de todas las entradas de flake, incluyendo nixpkgs y home-manager, sin cambiar los canales de lanzamiento de NixOS","fr":"Upgrade-flake met à jour les commits les plus récents de toutes les entrées de flake, y compris nixpkgs et home-manager, sans changer les canaux de sortie de NixOS","de":"Upgrade-Flake aktualisiert die neuesten Commits aller Flake-Eingaben, einschließlich nixpkgs und home-manager, ohne die NixOS-Release-Kanäle zu ändern","pt":"O Upgrade Flake atualiza o arquivo flake.lock para obter as últimas versões dos pacotes NixOS","ru":"Upgrade Flake обновляет файл flake.lock до последних версий пакетов NixOS","ar":"يحديث Upgrade Flake ملف flake.lock للحصول على أحدث إصدارات الحزم NixOS"},"seo":{"title":{"en":"upgrade-flake: NixOS Update Setup Guide | AI Agent Skill","zh":"Upgrade Flake Setup Guide - AIエージェント工具","ja":"Upgrade Flakeベストプラクティス - AIエージェント","ko":"Upgrade Flake 설정 가이드 - 인공지능 에이전트","es":"Guía de configuración de upgrade-flake para NixOS","fr":"Mise à jour de flake avec upgrade-flake : Meilleures prat...","de":"Upgrade-Flake-Setup-Anleitung für NixOS-Entwickler","pt":"Guia de Configuração do Upgrade Flake para NixOS","ru":"Настройка Upgrade Flake для обновления версий пакетов NixOS","ar":"دليل إعداد Upgrade Flake لأحدث إصدارات الحزم NixOS"},"description":{"en":"Discover how to update NixOS packages with upgrade-flake. Learn to run `nix flake update` and get the latest commits without changing release channels.","zh":"了解Upgrade Flake的功能和优势，包括更新flake.lock文件和获取最新包版本","ja":"Upgrade Flakeの機能と利点を学びましょう。最新のコミットを取得し、パッケージを更新します","ko":"Upgrade Flake의 기능과 장점을 알아보세요. flake.lock 파일을 업데이트하고 최신 패키지 버전을 가져옵니다","es":"Aprende a actualizar tus dependencias de NixOS con upgrade-flake y mantén tus proyectos actualizados con las últimas versiones de nixpkgs y home-manager","fr":"Découvrez comment mettre à jour vos dépendances NixOS avec upgrade-flake et profitez des dernières versions de nixpkgs et home-manager pour vos projets","de":"Erfahren Sie, wie Sie Ihre NixOS-Abhängigkeiten mit upgrade-flake aktualisieren und Ihre Projekte mit den neuesten Versionen von nixpkgs und home-manager auf...","pt":"Aprenda a atualizar o arquivo flake.lock para obter as últimas versões dos pacotes NixOS sem alterar os canais de lançamento","ru":"Обновите файл flake.lock до последних версий пакетов NixOS без смены каналов выпуска","ar":"تعلم كيفية تحديث ملف flake.lock للحصول على أحدث إصدارات الحزم NixOS دون تغيير قنوات الإصدار"},"definition":{"en":"upgrade-flake is a skill that updates all inputs to their latest commits, including nixpkgs and home-manager, without changing NixOS release channels.","zh":"Upgrade Flake是一种AI工具，用于更新flake.lock文件以获取最新的包版本","ja":"Upgrade Flakeは、最新のコミットを取得するためにflake.lockファイルを更新するAIエージェントです","ko":"Upgrade Flake는 최신 패키지 버전을 가져오기 위해 flake.lock 파일을 업데이트하는 인공지능 에이전트입니다","es":"Upgrade-flake es una herramienta de AI que actualiza las dependencias de NixOS a las últimas versiones","fr":"Upgrade-flake est un outil d''IA qui met à jour les dépendances NixOS vers les dernières versions","de":"Upgrade-Flake ist ein AI-Tool, das die NixOS-Abhängigkeiten auf die neuesten Versionen aktualisiert","pt":"O Upgrade Flake é uma ferramenta que atualiza o arquivo flake.lock para obter as últimas versões dos pacotes NixOS","ru":"Upgrade Flake - это инструмент, который обновляет файл flake.lock до последних версий пакетов NixOS","ar":"Upgrade Flake هو أداة تحديث ملف flake.lock للحصول على أحدث إصدارات الحزم NixOS"},"features":{"en":["Updates all inputs to their latest commits using `nix flake update`","Does not change release channels, staying on the same NixOS version","Safely updates `flake.lock` file","Allows rollback to previous versions","Runs `just update` command to update the lock file"],"zh":["更新flake.lock文件","获取最新的包版本","不改变NixOS版本","安全操作，支持回滚","使用nix flake update命令"],"ja":["flake.lockファイルの更新","最新のパッケージバージョンの取得","NixOSバージョンの変更なし","安全な操作、ロールバック対応","nix flake updateコマンドの使用"],"ko":["flake.lock 파일 업데이트","최신 패키지 버전 가져오기","NixOS 버전 변경 없음","안전한 작업, 롤백 지원","nix flake update 명령어 사용"],"es":["Actualiza los commits más recientes de todas las entradas de flake","Mantiene los canales de lanzamiento de NixOS sin cambios","Ejecuta ''nix flake update'' para actualizar el archivo de bloqueo","Permite revertir los cambios en caso de problemas","Soporta la actualización de nixpkgs y home-manager"],"fr":["Met à jour les commits les plus récents de toutes les entrées de flake","Conserve les canaux de sortie de NixOS sans changement","Exécute ''nix flake update'' pour mettre à jour le fichier de verrouillage","Permet d''annuler les modifications en cas de problèmes","Prend en charge la mise à jour de nixpkgs et home-manager"],"de":["Aktualisiert die neuesten Commits aller Flake-Eingaben","Hält die NixOS-Release-Kanäle unverändert","Führt ''nix flake update'' aus, um die Lock-Datei zu aktualisieren","Ermöglicht das Zurücksetzen der Änderungen im Falle von Problemen","Unterstützt die Aktualisierung von nixpkgs und home-manager"],"pt":["Atualiza o arquivo flake.lock para obter as últimas versões dos pacotes NixOS","Não altera os canais de lançamento do NixOS","Opera de forma segura, permitindo rollback","Executa o comando `nix flake update` para atualizar o arquivo flake.lock","Compatível com nixpkgs e home-manager"],"ru":["Обновляет файл flake.lock до последних версий пакетов NixOS","Не меняет каналы выпуска NixOS","Безопасная операция, позволяет откатиться назад","Выполняет команду `nix flake update` для обновления файла flake.lock","Компатибельна с nixpkgs и home-manager"],"ar":["يحديث ملف flake.lock للحصول على أحدث إصدارات الحزم NixOS","لا يغير قنوات الإصدار NixOS","تعمل بسلامة، مما يسمح بالرجوع إلى الوراء","ينفذ أمر `nix flake update` لتحديث ملف flake.lock","متوافقة مع nixpkgs و home-manager"]},"keywords":{"en":["how to use upgrade-flake","upgrade-flake setup guide","nix flake update command","upgrade-flake vs nixos-rebuild","what is upgrade-flake","upgrade-flake install","nixos package management","flake.lock update","nixpkgs update"],"zh":["Upgrade Flake","AIエージェント工具","flake.lock文件更新","NixOS包管理","nix flake update","AI工具","软件包更新","版本管理"],"ja":["Upgrade Flake","AIエージェント","flake.lockファイル更新","NixOSパッケージ管理","nix flake update","AIツール","ソフトウェアパッケージ更新","バージョン管理"],"ko":["Upgrade Flake","인공지능 에이전트","flake.lock 파일 업데이트","NixOS 패키지 관리","nix flake update","AI 도구","소프트웨어 패키지 업데이트","버전 관리"],"es":["upgrade-flake","NixOS","nixpkgs","home-manager","actualización de dependencias","herramientas de AI","desarrollo de software","gestión de dependencias"],"fr":["upgrade-flake","NixOS","nixpkgs","home-manager","mise à jour des dépendances","outils d''IA","développement de logiciels","gestion des dépendances"],"de":["upgrade-flake","NixOS","nixpkgs","home-manager","Aktualisierung von Abhängigkeiten","AI-Tools","Software-Entwicklung","Abhängigkeits-Management"],"pt":["Upgrade Flake","NixOS","atualizar flake.lock","nix flake update","nixpkgs","home-manager","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["Upgrade Flake","NixOS","обновить flake.lock","nix flake update","nixpkgs","home-manager","инструменты разработки","разработка программного обеспечения"],"ar":["Upgrade Flake","NixOS","تحديث flake.lock","nix flake update","nixpkgs","home-manager","أدوات التطوير","تطوير البرمجيات"]}},"owner":"richardgill","repo":"nix","repoPath":"richardgill/nix","stars":29,"forks":1,"updatedAt":"2026-02-25T22:59:24Z","topics":[],"category":"community","skillMd":{"name":"upgrade-flake","description":"|","bodyPreview":"# Upgrade Flake Inputs\n\nUpdate `flake.lock` to pull in the latest commits from all flake inputs. This gets you newer package versions without changing NixOS release channels.\n\n## What this does\n\n- Updates all inputs to their latest commits (nixpkgs, home-manager, etc.)\n- Does NOT change release channels (stays on same NixOS version)\n- Safe operation - can always rollback\n\n## Process\n\n1. **Update the lock file**\n   ```bash\n   just update\n   ```\n   This runs `nix flake update` and updates `flake.l","body":"# Upgrade Flake Inputs\n\nUpdate `flake.lock` to pull in the latest commits from all flake inputs. This gets you newer package versions without changing NixOS release channels.\n\n## What this does\n\n- Updates all inputs to their latest commits (nixpkgs, home-manager, etc.)\n- Does NOT change release channels (stays on same NixOS version)\n- Safe operation - can always rollback\n\n## Process\n\n1. **Update the lock file**\n   ```bash\n   just update\n   ```\n   This runs `nix flake update` and updates `flake.lock`.\n\n2. **Build and verify** (safe dry-run)\n   ```bash\n   just check\n   ```\n   Builds all configurations without applying. If this fails, fix errors before proceeding.\n\n3. **Apply the update** (when ready)\n   ```bash\n   just switch\n   ```\n\n4. **Verify services are running**\n   ```bash\n   systemctl status docker tailscaled\n   ```\n\n## Rollback if needed\nWhen you''re done echo out the instructions to:\n```bash\n# Revert to previous system generation\nsudo nixos-rebuild switch --rollback\n\n# Revert flake.lock to previous state\ngit checkout flake.lock\n```\n\n## Tips\n\n- show the user what ch `git diff flake.lock` to see what changed before applying\n- Old boot entries remain available for rollback until garbage collected\n\n$ARGUMENTS\n"},"lastSynced":"2026-03-06T06:39:19.593Z","agentAnalysis":{"suitability":{"en":"Ideal for NixOS Agents requiring automated package updates and dependency management.","zh":"适用于需要自动包更新和依赖管理的 NixOS Agents。","ja":"NixOS エージェントが自動パッケージ更新と依存関係管理を必要とする場合に適しています。","ko":"자동 패키지 업데이트 및 의존성 관리가 필요한 NixOS 에이전트에 적합합니다.","es":"Ideal para agentes de NixOS que requieren actualizaciones de paquetes automatizadas y gestión de dependencias.","fr":"Idéal pour les agents NixOS nécessitant des mises à jour de paquets automatisées et une gestion des dépendances.","de":"Ideal für NixOS-Agents, die automatisierte Paket-Updates und Abhängigkeitsverwaltung erfordern.","pt":"Ideal para Agents NixOS que exigem atualizações de pacotes automatizadas e gerenciamento de dependências.","ru":"Идеально подходит для агентов NixOS, требующих автоматизированного обновления пакетов и управления зависимостями.","ar":"مثالي لعميل NixOS الذي يتطلب تحديثات حزمة آلية وإدارة التبعيات."},"recommendation":{"en":"Empowers agents to update `flake.lock` files, pulling in the latest commits from all flake inputs like nixpkgs and home-manager, ensuring safe and up-to-date package versions without changing NixOS release channels, all through the `nix flake update` command.","zh":"赋予代理更新 `flake.lock` 文件的能力，拉取所有 flake 输入（如 nixpkgs 和 home-manager）中的最新提交，确保在不更改 NixOS 发布渠道的情况下获得安全且最新的包版本，所有这些都通过 `nix flake update` 命令完成。","ja":"エージェントに `flake.lock` ファイルを更新する機能を与え、nixpkgs や home-manager などのすべての flake 入力から最新のコミットを取得し、NixOS リリース チャンネルを変更せずに安全で最新のパッケージ バージョンを提供する、すべて `nix flake update` コマンドを介して。","ko":"에이전트가 `flake.lock` 파일을 업데이트하는 기능을 부여하여 nixpkgs 및 home-manager와 같은 모든 플레이크 입력에서 최신 커밋을 가져와 NixOS 릴리스 채널을 변경하지 않고 안전하고 최신 버전의 패키지를 제공하며, 모든 것은 `nix flake update` 명령을 통해 수행됩니다.","es":"Habilita a los agentes a actualizar archivos `flake.lock`, incorporando los últimos commits de todas las entradas de flake como nixpkgs y home-manager, garantizando versiones de paquetes seguras y actualizadas sin cambiar los canales de lanzamiento de NixOS, todo a través del comando `nix flake update`.","fr":"Permet aux agents de mettre à jour les fichiers `flake.lock`, en intégrant les derniers commits de toutes les entrées de flake comme nixpkgs et home-manager, garantissant des versions de paquets sécurisées et à jour sans changer les canaux de publication de NixOS, le tout via la commande `nix flake update`.","de":"Ermächtigt Agenten, `flake.lock`-Dateien zu aktualisieren, indem sie die neuesten Commits aus allen Flake-Eingaben wie nixpkgs und home-manager einbeziehen, um sichere und aktuelle Paketversionen ohne Änderung der NixOS-Veröffentlichungskanäle sicherzustellen, und all dies über den Befehl `nix flake update`.","pt":"Habilita os agentes a atualizar arquivos `flake.lock`, incorporando os últimos commits de todas as entradas de flake, como nixpkgs e home-manager, garantindo versões de pacotes seguras e atualizadas sem alterar os canais de lançamento do NixOS, tudo por meio do comando `nix flake update`.","ru":"Позволяет агентам обновлять файлы `flake.lock`, подтягивая последние коммиты со всех входов flake, таких как nixpkgs и home-manager, обеспечивая безопасные и актуальные версии пакетов без изменения каналов выпуска NixOS, все через команду `nix flake update`.","ar":"تمكين الوكيل من تحديث الملفات `flake.lock` ، وجلب آخر التعليقات من جميع مدخلات flake مثل nixpkgs و home-manager ، وضمان إصدارات حزم آمنة ومحدثة بدون تغيير قنوات إصدار NixOS ، وكل شيء من خلال أمر `nix flake update`."},"useCases":{"en":["Updating flake inputs to the latest commits","Safely updating packages without changing release channels","Rolling back to previous versions if needed"],"zh":["更新 flake 输入到最新提交","在不更改发布渠道的情况下安全更新包","如果需要，则回滚到以前的版本"],"ja":["flake 入力を最新のコミットに更新する","リリース チャンネルを変更せずに安全にパッケージを更新する","必要に応じて以前のバージョンにロールバックする"],"ko":["플레이크 입력을 최신 커밋으로 업데이트하는 것","릴리스 채널을 변경하지 않고 안전하게 패키지를 업데이트하는 것","필요한 경우 이전 버전으로 롤백하는 것"],"es":["Actualizar las entradas de flake a los últimos commits","Actualizar paquetes de forma segura sin cambiar los canales de lanzamiento","Revertir a versiones anteriores si es necesario"],"fr":["Mettre à jour les entrées de flake aux derniers commits","Mettre à jour les paquets de manière sécurisée sans changer les canaux de publication","Revenir à des versions antérieures si nécessaire"],"de":["Flake-Eingaben auf die neuesten Commits aktualisieren","Pakete sicher aktualisieren, ohne die Veröffentlichungskanäle zu ändern","Auf vorherige Versionen zurücksetzen, wenn erforderlich"],"pt":["Atualizar entradas de flake para os últimos commits","Atualizar pacotes de forma segura sem alterar canais de lançamento","Reverter para versões anteriores se necessário"],"ru":["Обновление входов flake до последних коммитов","Безопасное обновление пакетов без изменения каналов выпуска","Откат к предыдущим версиям при необходимости"],"ar":["تحديث مدخلات flake إلى آخر التعليقات","تحديث الحزم بشكل آمن دون تغيير قنوات الإصدار","الرجوع إلى الإصدارات السابقة عند الحاجة"]},"limitations":{"en":["Requires NixOS environment","Limited to updating flake inputs, not changing release channels"],"zh":["需要 NixOS 环境","仅限更新 flake 输入，不更改发布渠道"],"ja":["NixOS 環境が必要","flake 入力の更新のみ、リリース チャンネルの変更は不可"],"ko":["NixOS 환경이 필요함","플레이크 입력 업데이트만 가능하며 릴리스 채널 변경은 불가능"],"es":["Requiere entorno de NixOS","Limitado a la actualización de entradas de flake, no a la modificación de canales de lanzamiento"],"fr":["Nécessite un environnement NixOS","Limité à la mise à jour des entrées de flake, et non à la modification des canaux de publication"],"de":["Benötigt NixOS-Umgebung","Begrenzt auf die Aktualisierung von Flake-Eingaben, nicht auf die Änderung der Veröffentlichungskanäle"],"pt":["Exige ambiente NixOS","Limitado à atualização de entradas de flake, não alterando canais de lançamento"],"ru":["Требует окружения NixOS","Ограничен обновлением входов flake, не изменяя каналы выпуска"],"ar":["يتطلب بيئة NixOS","محدود بتحديث مدخلات flake ، لا تغيير قنوات الإصدار"]},"version":4},"contentHash":"b3b49f264c12bf5409efe1121b56e136a0935a0665fffaa22b309e3abed4a867","qualityScore":41}');
