INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('richardgill/nix/upgrade-flake', 'upgrade-flake', 'richardgill', 'nix', 'community', 'upgrade-flake richardgill nix community The upgrade-flake skill updates `flake.lock` to pull in the latest commits from all flake inputs, benefiting NixOS developers. It safely updates packages without changing release channels. Upgrade Flake更新flake.lock文件，获取最新的包版本，不改变NixOS版本 Upgrade Flakeはflake.lockファイルを更新し、最新のパッケージバージョンを取得します Upgrade Flake는 flake.lock 파일을 업데이트하고 최신 패키지 버전을 가져옵니다 Upgrade-flake actualiza los commits más recientes de todas las entradas de flake, incluyendo nixpkgs y home-manager, sin cambiar los canales de lanzamiento de NixOS Upgrade-flake met à jour les commits les plus récents de toutes les entrées de flake, y compris nixpkgs et home-manager, sans changer les canaux de sortie de NixOS Upgrade-Flake aktualisiert die neuesten Commits aller Flake-Eingaben, einschließlich nixpkgs und home-manager, ohne die NixOS-Release-Kanäle zu ändern O Upgrade Flake atualiza o arquivo flake.lock para obter as últimas versões dos pacotes NixOS Upgrade Flake обновляет файл flake.lock до последних версий пакетов NixOS يحديث Upgrade Flake ملف flake.lock للحصول على أحدث إصدارات الحزم NixOS how to use upgrade-flake upgrade-flake setup guide nix flake update command upgrade-flake vs nixos-rebuild what is upgrade-flake upgrade-flake install nixos package management flake.lock update nixpkgs update Upgrade Flake AIエージェント工具 flake.lock文件更新 NixOS包管理 nix flake update AI工具 软件包更新 版本管理 Updates all inputs to their latest commits using `nix flake update` Does not change release channels, staying on the same NixOS version Safely updates `flake.lock` file Allows rollback to previous versions Runs `just update` command to update the lock file upgrade-flake is a skill that updates all inputs to their latest commits, including nixpkgs and home-manager, without changing NixOS release channels.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dkyazzentwatwa/SuperNavigator/nav-stats', 'community', 'dkyazzentwatwa', 'SuperNavigator', 'dkyazzentwatwa/SuperNavigator', 'nav-stats', 0, 0, 41, '2026-03-07T12:46:33.792Z', '2026-03-07T13:04:31.602Z', '534fdddf7028538dba06aebd55a07bf26a7587bc151eb4c4ff8737c19678f3c8', '{"id":"dkyazzentwatwa/SuperNavigator/nav-stats","name":"nav-stats","description":{"en":"The nav-stats skill provides real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable for developers. It benefits users who want to track their session performance and token savings.","zh":"nav-stats技能提供实时效率报告和基线比较，帮助开发者量化和分享Navigator的价值","ja":"nav-statsスキルはリアルタイム効率レポートとベースライン比較を提供し、開発者がNavigatorの価値を数量化して共有できるようにします","ko":"nav-stats 스킬은 실시간 효율 보고 및 기준 비교를 제공하여 개발자가 Navigator의 가치를 정량화하고 공유할 수 있습니다","es":"nav-stats es un skill que proporciona informes de eficiencia en tiempo real con comparaciones de referencia para Claude Code","fr":"nav-stats est un skill qui fournit des rapports d''efficacité en temps réel avec des comparaisons de référence pour Claude Code","de":"nav-stats ist ein Skill, der Echtzeit-Effizienzberichte mit Vergleichswerten für Claude Code bereitstellt","pt":"O nav-stats fornece relatórios de eficiência em tempo real com comparações de baseline, permitindo que os desenvolvedores meçam o valor do Navigator de forma quantificável e compartilhável.","ru":"Навык nav-stats предоставляет отчеты об эффективности в реальном времени с сравнением базовой производительности, позволяя разработчикам оценить ценность Navigator в количественном и общем виде для ИИ Агентов","ar":"يوفر нав-ستاتس تقارير كفاءة الوقت الحقيقي مع مقارنة الأساس، مما يسمح للمطورين بقياس قيمة Navigator بطريقة كمية ويمكن مشاركتها للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"nav-stats: Real-Time Efficiency Reporting for AI Agents |...","zh":"nav-stats Setup Guide: 实时效率报告和基线比较","ja":"nav-stats セットアップガイド: リアルタイム効率レポートとベースライン比較","ko":"nav-stats 설정 가이드: 실시간 효율 보고 및 기준 비교","es":"Guía de configuración de nav-stats para Agentes de IA","fr":"Guide de mise en place de nav-stats pour les Outils d''IA","de":"Einrichtungsleitfaden für nav-stats in KI-Agents","pt":"Guia de Configuração do Nav-Stats: Relatórios de Eficiênc...","ru":"Настройка навыка Nav-Stats: Отчеты об эффективности в реа...","ar":"دليل إعداد нав-ستاتس: تقارير كفاءة الوقت الحقيقي للوكلاء ..."},"description":{"en":"Unlock the power of nav-stats and discover how to quantify Navigator''s value with real-time session statistics and baseline comparisons. Learn how to invoke ...","zh":"了解nav-stats技能，实现实时效率报告和基线比较，提升Navigator的价值","ja":"nav-statsスキルを使用してリアルタイム効率レポートとベースライン比較を行い、Navigatorの価値を高める","ko":"nav-stats 스킬을 사용하여 실시간 효율 보고 및 기준 비교를 통해 Navigator의 가치를 높여보세요","es":"Aprende a utilizar nav-stats para medir la eficiencia de tus sesiones en Claude Code y descubre cómo funciona este skill de estadísticas","fr":"Découvrez comment utiliser nav-stats pour mesurer l''efficacité de vos sessions dans Claude Code et découvrez les fonctionnalités de ce skill de statistiques","de":"Erfahren Sie, wie Sie nav-stats verwenden, um die Effizienz Ihrer Sitzungen in Claude Code zu messen und entdecken Sie die Funktionen dieses Statistik-Skills","pt":"Aprenda a configurar o nav-stats para obter relatórios de eficiência em tempo real e comparativos de baseline para medir o valor do Navigator","ru":"Узнайте, как настроить навык nav-stats для получения отчетов об эффективности в реальном времени и сравнения базовой производительности для оценки ценности N...","ar":"تعرف على كيفية إعداد нав-ستاتس للحصول على تقارير كفاءة الوقت الحقيقي ومقارنة الأساس لقياس قيمة Navigator للوكلاء الذكاء الاصطناعي"},"definition":{"en":"nav-stats is a Navigator Session Statistics Skill that shows real-time efficiency reporting with baseline comparisons, enabling users to quantify Navigator''s value.","zh":"nav-stats是一种Navigator会话统计技能，提供实时效率报告和基线比较","ja":"nav-statsはNavigatorセッション統計スキルであり、リアルタイム効率レポートとベースライン比較を提供する","ko":"nav-stats는 Navigator 세션 통계 스킬로 실시간 효율 보고 및 기준 비교를 제공합니다","es":"nav-stats es un skill de estadísticas que muestra informes de eficiencia en tiempo real para sesiones de Claude Code","fr":"nav-stats est un skill de statistiques qui affiche des rapports d''efficacité en temps réel pour les sessions de Claude Code","de":"nav-stats ist ein Statistik-Skill, der Echtzeit-Effizienzberichte für Claude-Code-Sitzungen anzeigt","pt":"O nav-stats é um skill que fornece relatórios de eficiência em tempo real com comparações de baseline para o Navigator","ru":"Навык nav-stats - это навык, который предоставляет отчеты об эффективности в реальном времени с сравнением базовой производительности для Navigator для ИИ Агентов","ar":"ناف-ستاتس هو مهارة توفر تقارير كفاءة الوقت الحقيقي مع مقارنة الأساس لنافيجيتور للوكلاء الذكاء الاصطناعي"},"features":{"en":["Generates real-time efficiency reports with baseline comparisons","Supports invocation through voice commands like ''show my stats'' or ''show session stats''","Provides token savings and session performance metrics","Enables users to ask questions like ''how efficient am I?'' or ''how much did I save?''","Offers a Navigator report and efficiency report for users to track their progress"],"zh":["实时效率报告","基线比较","token节省分析","会话性能分析","Navigator报告生成","效率影响分析"],"ja":["リアルタイム効率レポート","ベースライン比較","トークン節約分析","セッション性能分析","Navigatorレポート生成","効率影響分析"],"ko":["실시간 효율 보고","기준 비교","토큰 절약 분석","세션 성능 분석","Navigator 보고서 생성","효율 영향 분석"],"es":["Informes de eficiencia en tiempo real","Comparaciones de referencia para medir el ahorro de tokens","Análisis de rendimiento de sesiones","Generación de informes de impacto","Integración con Claude Code"],"fr":["Rapports d''efficacité en temps réel","Comparaisons de référence pour mesurer les économies de jetons","Analyse des performances de session","Génération de rapports d''impact","Intégration avec Claude Code"],"de":["Echtzeit-Effizienzberichte","Vergleichswerte für die Messung von Token-Einsparungen","Sitzungsleistungsanalyse","Erstellung von Auswirkungsberichten","Integration mit Claude Code"],"pt":["Relatórios de eficiência em tempo real","Comparações de baseline para medir o valor do Navigator","Token savings e session performance","Relatórios de impacto e eficiência","Integração com o Navigator para desenvolvedores"],"ru":["Отчеты об эффективности в реальном времени","Сравнение базовой производительности для оценки ценности Navigator","Экономия токенов и производительность сеанса","Отчеты об эффективности и воздействии","Интеграция с Navigator для разработчиков ИИ Агентов"],"ar":["تقارير كفاءة الوقت الحقيقي","مقارنة الأساس لقياس قيمة Navigator","توفير رموز العملة و أداء الجلسة","تقارير التأثير و الكفاءة","التكامل مع Navigator للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use nav-stats","nav-stats setup guide","what is nav-stats","nav-stats alternative","nav-stats vs Navigator","nav-stats install","real-time efficiency reporting","Navigator Session Statistics Skill","token savings metrics"],"zh":["AI工具","nav-stats","Navigator","实时效率报告","基线比较","token节省","会话性能","Navigator报告","效率影响"],"ja":["AIエージェント","nav-stats","Navigator","リアルタイム効率レポート","ベースライン比較","トークン節約","セッション性能","Navigatorレポート","効率影響"],"ko":["AI 에이전트","nav-stats","Navigator","실시간 효율 보고","기준 비교","토큰 절약","세션 성능","Navigator 보고서","효율 영향"],"es":["nav-stats","Agentes de IA","Herramientas de IA","Estadísticas de sesiones","Informes de eficiencia","Claude Code","Análisis de rendimiento","Integración de habilidades","Desarrollo de habilidades de IA"],"fr":["nav-stats","Outils d''IA","Agents d''IA","Statistiques de sessions","Rapports d''efficacité","Claude Code","Analyse de performances","Intégration de compétences","Développement de compétences d''IA"],"de":["nav-stats","KI-Agents","KI-Tools","Sitzungsstatistiken","Effizienzberichte","Claude Code","Leistungsanalyse","Fähigkeitsintegration","Entwicklung von KI-Fähigkeiten"],"pt":["nav-stats","relatórios de eficiência","comparações de baseline","Navigator","desenvolvedores","relatórios de impacto","token savings","session performance","otimização de processos"],"ru":["nav-stats","отчеты об эффективности","сравнение базовой производительности","Navigator","разработчики","отчеты об эффективности","экономия токенов","производительность сеанса","оптимизация процессов","ИИ Агенты"],"ar":["ناف-ستاتس","تقارير كفاءة","مقارنة الأساس","نافيجيتور","مطورون","تقارير التأثير","توفير رموز العملة","أداء الجلسة","تحسين العمليات","الوكلاء الذكاء الاصطناعي"]}},"owner":"dkyazzentwatwa","repo":"SuperNavigator","repoPath":"dkyazzentwatwa/SuperNavigator","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.792Z","topics":[],"category":"community","skillMd":{"name":"nav-stats","description":"Display session efficiency report showing token savings, cache performance, and optimization recommendations. Use when user asks show my stats, how efficient am I?, show session metrics, or wants to see Navigators impact.","version":"1.0.0","bodyPreview":"# Navigator Session Statistics Skill\n\nShow real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable.\n\n## When to Invoke\n\nInvoke this skill when the user:\n- Says \"show my stats\", \"show session stats\", \"show metrics\"\n- Asks \"how efficient am I?\", \"how much did I save?\"\n- Says \"show my Navigator report\", \"efficiency report\"\n- Wants to see token savings or session performance\n- Says \"show impact\", \"prove Navigator works\"\n\n**DO NOT invoke** if:\n- U","body":"# Navigator Session Statistics Skill\n\nShow real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable.\n\n## When to Invoke\n\nInvoke this skill when the user:\n- Says \"show my stats\", \"show session stats\", \"show metrics\"\n- Asks \"how efficient am I?\", \"how much did I save?\"\n- Says \"show my Navigator report\", \"efficiency report\"\n- Wants to see token savings or session performance\n- Says \"show impact\", \"prove Navigator works\"\n\n**DO NOT invoke** if:\n- User just started session (< 5 messages)\n- Navigator not initialized in project\n- User asking about specific metrics only (answer directly)\n\n## Execution Steps\n\n### Step 1: Check Navigator Initialized\n\nVerify Navigator is set up:\n\n```bash\nif [ ! -f \".agent/DEVELOPMENT-README.md\" ]; then\n  echo \"❌ Navigator not initialized in this project\"\n  echo \"Run ''Initialize Navigator'' first\"\n  exit 1\nfi\n```\n\n### Step 2: Run Enhanced Session Stats\n\nExecute the enhanced session statistics script:\n\n```bash\n# Check if enhanced script exists\nif [ ! -f \"scripts/session-stats.sh\" ]; then\n  echo \"❌ Session stats script not found\"\n  echo \"This feature requires Navigator v3.5.0+\"\n  exit 1\nfi\n\n# Run stats script\nbash scripts/session-stats.sh\n```\n\nThis script outputs shell-parseable variables:\n- `BASELINE_TOKENS` - Total size of all .agent/ docs\n- `LOADED_TOKENS` - Actually loaded in session (estimated)\n- `TOKENS_SAVED` - Difference\n- `SAVINGS_PERCENT` - Percentage saved\n- `EFFICIENCY_SCORE` - 0-100 score\n- `CACHE_EFFICIENCY` - From OpenTelemetry\n- `CONTEXT_USAGE_PERCENT` - Estimated context fill\n- `TIME_SAVED_MINUTES` - Estimated time saved\n\n### Step 3: Calculate Efficiency Score\n\nUse predefined function to calculate score:\n\n```bash\n# Extract metrics from session-stats.sh\nsource <(bash scripts/session-stats.sh)\n\n# Calculate efficiency score using predefined function\nEFFICIENCY_SCORE=$(python3 skills/nav-stats/functions/efficiency_scorer.py \\\n  --tokens-saved-percent ${SAVINGS_PERCENT} \\\n  --cache-efficiency ${CACHE_EFFICIENCY} \\\n  --context-usage ${CONTEXT_USAGE_PERCENT})\n```\n\n### Step 4: Format and Display Report\n\nUse predefined function to format visual report:\n\n```bash\n# Generate formatted report\npython3 skills/nav-stats/functions/report_formatter.py \\\n  --baseline ${BASELINE_TOKENS} \\\n  --loaded ${LOADED_TOKENS} \\\n  --saved ${TOKENS_SAVED} \\\n  --savings-percent ${SAVINGS_PERCENT} \\\n  --cache-efficiency ${CACHE_EFFICIENCY} \\\n  --context-usage ${CONTEXT_USAGE_PERCENT} \\\n  --efficiency-score ${EFFICIENCY_SCORE} \\\n  --time-saved ${TIME_SAVED_MINUTES}\n```\n\n**Output Format**:\n```\n╔══════════════════════════════════════════════════════╗\n║          NAVIGATOR EFFICIENCY REPORT                 ║\n╚══════════════════════════════════════════════════════╝\n\n📊 TOKEN USAGE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nDocumentation loaded:        12,000 tokens\nBaseline (all docs):        150,000 tokens\nTokens saved:               138,000 tokens (92% ↓)\n\n💾 CACHE PERFORMANCE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCache efficiency:              100.0% (perfect)\n\n📈 SESSION METRICS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nContext usage:                      35% (excellent)\nEfficiency score:                94/100 (excellent)\n\n⏱️  TIME SAVED\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nEstimated time saved:          ~42 minutes\n\n💡 WHAT THIS MEANS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nNavigator loaded 92% fewer tokens than loading all docs.\nYour context window is 65% available for actual work.\n\n🎯 RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n✅ Excellent efficiency - keep using lazy-loading strategy\n✅ Context usage healthy - plenty of room for work\n\nShare your efficiency: Take a screenshot! #ContextEfficiency\n```\n\n### Step 5: Add Context-Specific Recommendations\n\nBased on efficiency score, provide actionable advice:\n\n**If efficiency_score < 70**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Token savings below target (70%+)\n→ Check: Are you loading more docs than needed?\n→ Tip: Use navigator to find docs, don''t load all upfront\n\nRead more: .agent/philosophy/CONTEXT-EFFICIENCY.md\n```\n\n**If context_usage > 80%**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Context usage high (80%+)\n→ Consider: Create context marker and compact\n→ Tip: Compact after completing sub-tasks\n\nRead more: .agent/philosophy/ANTI-PATTERNS.md\n```\n\n**If cache_efficiency < 80%**:\n```\n⚠️  RECOMMENDATIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚠️  Cache efficiency low (<80%)\n→ Check: CLAUDE.md properly configured?\n→ Tip: Ensure prompt caching enabled\n\nRead more: .agent/philosophy/PATTERNS.md (Caching pattern)\n```\n\n## Predefined Functions\n\n### `efficiency_scorer.py`\n\nCalculate Navigator efficiency score (0-100) based on:\n- Token savings (40 points)\n- Cache efficiency (30 points)\n- Context usage (30 points)\n\n**Usage**:\n```bash\npython3 skills/nav-stats/functions/efficiency_scorer.py \\\n  --tokens-saved-percent 92 \\\n  --cache-efficiency 100 \\\n  --context-usage 35\n```\n\n**Output**: `94` (integer score)\n\n### `report_formatter.py`\n\nFormat efficiency metrics into visual, shareable report.\n\n**Usage**:\n```bash\npython3 skills/nav-stats/functions/report_formatter.py \\\n  --baseline 150000 \\\n  --loaded 12000 \\\n  --saved 138000 \\\n  --savings-percent 92 \\\n  --cache-efficiency 100 \\\n  --context-usage 35 \\\n  --efficiency-score 94 \\\n  --time-saved 42\n```\n\n**Output**: Formatted ASCII report (see Step 4)\n\n## Philosophy Integration\n\n**Context Engineering Principle**: Measurement validates optimization\n\nFrom `.agent/philosophy/PATTERNS.md`:\n> \"Measure to validate. Navigator tracks real metrics, not estimates.\"\n\nThis skill proves:\n- **Token savings** are real (baseline comparison)\n- **Cache efficiency** works (OpenTelemetry data)\n- **Context usage** is healthy (window not overloaded)\n- **Time saved** is quantifiable (6s per 1k tokens)\n\n## User Experience\n\n**User says**: \"Show my stats\"\n\n**Skill displays**:\n1. Visual efficiency report\n2. Clear metrics (tokens, cache, context)\n3. Interpretation (\"What this means\")\n4. Actionable recommendations\n\n**User can**:\n- Screenshot and share (#ContextEfficiency)\n- Understand Navigator''s impact\n- Optimize workflow based on recommendations\n- Validate context engineering principles\n\n## Example Output Scenarios\n\n### Scenario 1: Excellent Efficiency (Score 94)\n\nUser following lazy-loading pattern, cache working perfectly:\n- 92% token savings ✅\n- 100% cache efficiency ✅\n- 35% context usage ✅\n- Score: 94/100\n\n**Recommendation**: Keep it up! Share your efficiency.\n\n### Scenario 2: Fair Efficiency (Score 72)\n\nUser loading too many docs upfront:\n- 65% token savings ⚠️\n- 95% cache efficiency ✅\n- 55% context usage ✅\n- Score: 72/100\n\n**Recommendation**: Review lazy-loading strategy. Load docs on-demand.\n\n### Scenario 3: Poor Efficiency (Score 48)\n\nUser not using Navigator patterns:\n- 45% token savings ❌\n- 70% cache efficiency ⚠️\n- 85% context usage ❌\n- Score: 48/100\n\n**Recommendation**: Read philosophy docs. Consider /nav:compact. Review CLAUDE.md.\n\n## Success Metrics\n\n**After using this skill, users should**:\n- Understand their efficiency score\n- See quantified token savings\n- Know what to improve (if anything)\n- Feel motivated to share results\n\n**Long-term impact**:\n- Users screenshot reports and share\n- \"Navigator saved me 138k tokens\" becomes common\n- Efficiency becomes visible, not abstract\n- Continuous improvement through measurement\n\n---\n\n**This skill makes Navigator''s value tangible and shareable.**\n"},"lastSynced":"2026-03-07T13:04:31.602Z","agentAnalysis":{"suitability":{"en":"Perfect for Efficiency Analysis Agents needing real-time session performance tracking and token savings metrics.","zh":"适用于需要实时会话性能跟踪和令牌节省指标的效率分析代理。","ja":"リアルタイムのセッションパフォーマンス追跡とトークンセーブのメトリクスが必要な効率分析エージェントに最適です。","ko":"실시간 세션 성능 추적 및 토큰 절약 메트릭이 필요한 효율성 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de Análisis de Eficiencia que necesitan un seguimiento del rendimiento de la sesión en tiempo real y métricas de ahorro de tokens.","fr":"Parfait pour les agents d''Analyse d''Efficience nécessitant un suivi des performances de session en temps réel et des métriques d''économie de tokens.","de":"Perfekt für Effizienzanalyse-Agents, die eine Echtzeit-Überwachung der Sitzungsleistung und Token-Einsparungs-Metriken benötigen.","pt":"Perfeito para Agentes de Análise de Eficiência que necessitam de rastreamento de desempenho de sessão em tempo real e métricas de economia de tokens.","ru":"Идеально подходит для агентов анализа эффективности, которым необходима отслеживание производительности сеанса в реальном времени и метрики экономии токенов.","ar":"مثالي لعمليات تحليل الكفاءة التي تحتاج إلى تتبع أداء الجلسة في الوقت الفعلي وأرقام توفير الرموز."},"recommendation":{"en":"Empowers agents to provide real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable through metrics and token savings data, utilizing natural language inputs like ''show my stats'' and ''efficiency report''.","zh":"赋予代理提供实时效率报告的能力，通过基线比较，使 Navigator 的价值可量化并可通过指标和令牌节省数据共享，利用自然语言输入如 ''显示我的统计数据'' 和 ''效率报告''。","ja":"エージェントがリアルタイムの効率報告を提供できるようにし、ベースライン比較を行うことで、Navigator の価値を数量化し、メトリクスとトークンセーブのデータを使用して共有できるようにします。自然言語入力 seperti ''私の統計を表示'' および ''効率報告'' を使用します。","ko":"에이전트가 실시간 효율성 보고를 제공할 수 있도록 하여 기준 비교를 통해 네비게이터의 가치를 양적으로 측정하고 메트릭 및 토큰 절약 데이터를 사용하여 공유할 수 있도록 합니다. 자연어 입력을 사용합니다. 예를 들어 ''내 통계를 표시'' 및 ''효율성 보고''.","es":"Habilita a los agentes a proporcionar informes de eficiencia en tiempo real con comparaciones de referencia, lo que hace que el valor de Navigator sea cuantificable y compartible a través de métricas y datos de ahorro de tokens, utilizando entradas de lenguaje natural como ''show my stats'' y ''efficiency report''.","fr":"Permet aux agents de fournir des rapports d''efficacité en temps réel avec des comparaisons de référence, ce qui rend la valeur de Navigator quantifiable et partageable via des métriques et des données d''économie de tokens, en utilisant des entrées de langage naturel comme ''show my stats'' et ''efficiency report''.","de":"Ermächtigt Agents, Echtzeit-Effizienzberichte mit Basisvergleichen bereitzustellen, wodurch der Wert von Navigator quantifizierbar und über Metriken und Token-Einsparungsdaten teilbar wird, unter Verwendung natürlicher Spracheingaben wie ''show my stats'' und ''efficiency report''.","pt":"Habilita os agentes a fornecer relatórios de eficiência em tempo real com comparações de baseline, tornando o valor do Navigator quantificável e compartilhável por meio de métricas e dados de economia de tokens, utilizando entradas de linguagem natural como ''mostrar minhas estatísticas'' e ''relatório de eficiência''.","ru":"Наделяет агентов возможностью предоставлять отчеты об эффективности в реальном времени с сравнениями базовой линии, что делает ценность Navigator количественной и общедоступной посредством метрик и данных об экономии токенов, используя естественные языковые входные данные, такие как ''покажите мои статистику'' и ''отчет об эффективности''.","ar":"يتمكّن الوكلاء من تقديم تقارير الكفاءة في الوقت الفعلي بالمقارنات الأساسية، مما يجعل قيمة Navigator كمية وقابلة للمشاركة من خلال الأرقام والبيانات الخاصة بتوفير الرموز، باستخدام مدخلات اللغة الطبيعية مثل ''أظهر إحصائياتي'' و ''تقرير الكفاءة''."},"useCases":{"en":["Tracking session performance in real-time","Generating efficiency reports with baseline comparisons","Calculating token savings for Navigator sessions"],"zh":["实时跟踪会话性能","生成基线比较的效率报告","计算 Navigator 会话的令牌节省"],"ja":["リアルタイムのセッションパフォーマンスの追跡","ベースライン比較の効率報告の生成","Navigator セッションのトークンセーブの計算"],"ko":["실시간 세션 성능 추적","기준 비교 효율성 보고서 생성","네비게이터 세션의 토큰 절약 계산"],"es":["Seguimiento del rendimiento de la sesión en tiempo real","Generación de informes de eficiencia con comparaciones de referencia","Cálculo del ahorro de tokens para las sesiones de Navigator"],"fr":["Suivi des performances de session en temps réel","Génération de rapports d''efficacité avec des comparaisons de référence","Calcul de l''économie de tokens pour les sessions de Navigator"],"de":["Überwachung der Sitzungsleistung in Echtzeit","Erstellung von Effizienzberichten mit Basisvergleichen","Berechnung der Token-Einsparung für Navigator-Sitzungen"],"pt":["Rastreamento de desempenho de sessão em tempo real","Geração de relatórios de eficiência com comparações de baseline","Cálculo de economia de tokens para sessões do Navigator"],"ru":["Отслеживание производительности сеанса в реальном времени","Генерация отчетов об эффективности с сравнениями базовой линии","Расчет экономии токенов для сеансов Navigator"],"ar":["تتبع أداء الجلسة في الوقت الفعلي","توليد تقارير الكفاءة بالمقارنات الأساسية","حساب توفير الرموز للجلسات Navigator"]},"limitations":{"en":["Requires Navigator session data access","Limited to Navigator-specific metrics and token savings"],"zh":["需要 Navigator 会话数据访问","仅限 Navigator 特定的指标和令牌节省"],"ja":["Navigator セッションデータへのアクセスが必要","Navigator 固有のメトリクスとトークンセーブに限定"],"ko":["네비게이터 세션 데이터 액세스가 필요","네비게이터 전용 메트릭 및 토큰 절약으로 제한"],"es":["Requiere acceso a los datos de la sesión de Navigator","Limitado a métricas y ahorro de tokens específicos de Navigator"],"fr":["Nécessite un accès aux données de session de Navigator","Limité aux métriques et à l''économie de tokens spécifiques de Navigator"],"de":["Benötigt Zugriff auf die Sitzungsdaten von Navigator","Begrenzt auf Navigator-spezifische Metriken und Token-Einsparungen"],"pt":["Requer acesso aos dados da sessão do Navigator","Limitado a métricas e economia de tokens específicas do Navigator"],"ru":["Требует доступа к данным сеанса Navigator","Ограничен метриками и экономией токенов, специфичными для Navigator"],"ar":["يتطلب الوصول إلى بيانات جلسة Navigator","محدود بالمعايير وأرقام توفير الرموز الخاصة بNavigator"]},"version":4},"contentHash":"534fdddf7028538dba06aebd55a07bf26a7587bc151eb4c4ff8737c19678f3c8","qualityScore":41}');
