INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dkyazzentwatwa/SuperNavigator/nav-stats', 'nav-stats', 'dkyazzentwatwa', 'SuperNavigator', 'community', 'nav-stats dkyazzentwatwa SuperNavigator community The nav-stats skill provides real-time efficiency reporting with baseline comparisons, making Navigator''s value quantifiable and shareable for developers. It benefits users who want to track their session performance and token savings. nav-stats技能提供实时效率报告和基线比较，帮助开发者量化和分享Navigator的价值 nav-statsスキルはリアルタイム効率レポートとベースライン比較を提供し、開発者がNavigatorの価値を数量化して共有できるようにします nav-stats 스킬은 실시간 효율 보고 및 기준 비교를 제공하여 개발자가 Navigator의 가치를 정량화하고 공유할 수 있습니다 nav-stats es un skill que proporciona informes de eficiencia en tiempo real con comparaciones de referencia para Claude Code nav-stats est un skill qui fournit des rapports d''efficacité en temps réel avec des comparaisons de référence pour Claude Code nav-stats ist ein Skill, der Echtzeit-Effizienzberichte mit Vergleichswerten für Claude Code bereitstellt O nav-stats fornece relatórios de eficiência em tempo real com comparações de baseline, permitindo que os desenvolvedores meçam o valor do Navigator de forma quantificável e compartilhável. Навык nav-stats предоставляет отчеты об эффективности в реальном времени с сравнением базовой производительности, позволяя разработчикам оценить ценность Navigator в количественном и общем виде для ИИ Агентов يوفر нав-ستاتس تقارير كفاءة الوقت الحقيقي مع مقارنة الأساس، مما يسمح للمطورين بقياس قيمة Navigator بطريقة كمية ويمكن مشاركتها للوكلاء الذكاء الاصطناعي how to use nav-stats nav-stats setup guide what is nav-stats nav-stats alternative nav-stats vs Navigator nav-stats install real-time efficiency reporting Navigator Session Statistics Skill token savings metrics AI工具 nav-stats Navigator 实时效率报告 基线比较 token节省 会话性能 Navigator报告 效率影响 Generates real-time efficiency reports with baseline comparisons Supports invocation through voice commands like ''show my stats'' or ''show session stats'' Provides token savings and session performance metrics Enables users to ask questions like ''how efficient am I?'' or ''how much did I save?'' Offers a Navigator report and efficiency report for users to track their progress nav-stats is a Navigator Session Statistics Skill that shows real-time efficiency reporting with baseline comparisons, enabling users to quantify Navigator''s value.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('inline-chat/inline/finalize', 'community', 'inline-chat', 'inline', 'inline-chat/inline', 'finalize', 0, 0, 41, '2026-02-27T01:51:08.518Z', '2026-02-27T02:45:22.954Z', '89cbbf36633846910fb5c7e9b0318a73f833643d25ac022c9ba804d694098373', '{"id":"inline-chat/inline/finalize","name":"finalize","description":{"zh":"finalize技能是快速、轻量、可扩展的工作聊天应用，实现无与伦比的协作能力","ja":"finalizeスキルは高速、軽量、スケーラブルなワークチャットアプリで、前例のないコラボレーション能力を実現","ko":"finalize 기능은 빠르고 가벼운 확장 가능한 작업 채팅 애플리케이션으로서 이전에는 볼 수 없었던 협업 능력을 제공","es":"Inline es una app de chat de trabajo rápida, ligera, escalable y potente que permite una colaboración sin precedentes","fr":"Inline est une application de chat de travail rapide, légère, évolutuve et puissante qui permet une collaboration inégalée","de":"Inline ist eine schnelle, leichte, skalierbare und leistungsstarke Work-Chat-App, die eine beispiellose Kollaboration ermöglicht","pt":"O Finalize é uma ferramenta de chat de trabalho rápida, leve e escalável que permite colaboração sem precedentes","ru":"Finalize - это быстрый, лёгкий и масштабируемый чат для работы, который обеспечивает беспрецедентное сотрудничество","ar":"Finalize هو أداة الدردشة الخاصة بالعمل السريعة والخفيفة والقابلة للتوسيع التي تمكن التعاون غير المسبوق","en":"Inline is a fast, lightweight, scalable, and powerful work chat app which enables unprecedented collaboration bandwidth."},"seo":{"title":{"zh":"AI智能工具finalize技能介绍","ja":"AIエージェントのfinalizeスキル","ko":"AI 에이전트 finalize 기능","es":"Finalizar con Herramientas de Inteligencia Artificial","fr":"Finaliser avec les Outils d''Intelligence Artificielle","de":"Finalisieren mit KI-Tools","pt":"Finalize: Ferramenta de Chat de Trabalho para Desenvolved...","ru":"Finalize: ИИ Агент для Командной Чата","ar":"Finalize: أداة الدردشة الخاصة بالعمل للطورين","en":"finalize"},"description":{"zh":"finalize技能是快速、轻量、可扩展的工作聊天应用，实现无与伦比的协作能力","ja":"finalizeスキルは高速、軽量、スケーラブルなワークチャットアプリで、前例のないコラボレーション能力を実現","ko":"finalize 기능은 빠르고 가벼운 확장 가능한 작업 채팅 애플리케이션으로서 이전에는 볼 수 없었던 협업 능력을 제공","es":"Inline es una app de chat de trabajo rápida, ligera, escalable y potente que permite una colaboración sin precedentes","fr":"Inline est une application de chat de travail rapide, légère, évolutuve et puissante qui permet une collaboration inégalée","de":"Inline ist eine schnelle, leichte, skalierbare und leistungsstarke Work-Chat-App, die eine beispiellose Kollaboration ermöglicht","pt":"O Finalize é uma ferramenta de chat de trabalho rápida, leve e escalável que permite colaboração sem precedentes","ru":"Finalize - это быстрый, лёгкий и масштабируемый чат для работы, который обеспечивает беспрецедентное сотрудничество","ar":"Finalize هو أداة الدردشة الخاصة بالعمل السريعة والخفيفة والقابلة للتوسيع التي تمكن التعاون غير المسبوق","en":"Inline is a fast, lightweight, scalable, and powerful work chat app which enables unprecedented collaboration bandwidth."},"definition":{"en":"Inline is a fast, lightweight, scalable, and powerful work chat app which enables unprecedented collaboration bandwidth."},"features":{"zh":["快速轻量","可扩展","强大的协作能力","实时通信","跨平台支持"],"ja":["高速軽量","スケーラブル","強力なコラボレーション能力","リアルタイム通信","クロスプラットフォーム対応"],"ko":["빠르고 가벼움","확장 가능","강력한 협업 능력","실시간 통신","크로스 플랫폼 지원"],"es":["Colaboración en tiempo real","Integración con herramientas de desarrollo","Seguridad y escalabilidad","Interfaz de usuario intuitiva","Soporte para equipos distribuidos"],"fr":["Collaboration en temps réel","Intégration avec des outils de développement","Sécurité et évolutivité","Interface utilisateur intuitive","Support pour les équipes distribuées"],"de":["Echtzeit-Kollaboration","Integration mit Entwicklungstools","Sicherheit und Skalierbarkeit","Benutzerfreundliche Oberfläche","Unterstützung für verteilte Teams"],"pt":["Chat de trabalho rápido e escalável","Colaboração em tempo real","Integração com ferramentas de desenvolvimento","Segurança e privacidade de dados","Interface de usuário intuitiva"],"ru":["Быстрый и масштабируемый чат для работы","Сотрудничество в режиме реального времени","Интеграция с инструментами разработки","Безопасность и приватность данных","Интуитивно понятный интерфейс пользователя"],"ar":["دردشة العمل السريعة والقابلة للتوسيع","التعاون في الوقت الفعلي","التكامل مع أدوات التطوير","أمن وخصوصية البيانات","واجهة المستخدم البسيطة"]},"keywords":{"zh":["AI智能工具finalize","工作聊天应用","协作能力提升","如何使用finalize","finalize安装","finalize教程"],"ja":["AIエージェントのfinalize","ワークチャットアプリ","コラボレーション能力の向上","finalizeの使い方","finalizeのセットアップ","finalizeのチュートリアル"],"ko":["AI 에이전트 finalize","작업 채팅 애플리케이션","협업 능력 향상","finalize 사용법","finalize 설치 가이드","finalize 튜토리얼"],"es":["cómo usar Inline","qué es la colaboración en tiempo real","Inline vs Slack","guía de instalación de Inline","configuración de Inline","herramientas de inteligencia artificial para desarrolladores"],"fr":["comment utiliser Inline","qu''est-ce que la collaboration en temps réel","Inline vs Slack","guide d''installation d''Inline","configuration d''Inline","outils d''intelligence artificielle pour les développeurs"],"de":["wie man Inline verwendet","was ist Echtzeit-Kollaboration","Inline vs Slack","Installationsanleitung für Inline","Einrichtung von Inline","KI-Tools für Entwickler"],"pt":["como usar finalize","o que é finalize","finalize alternative","finalize vs slack","finalize instalação","finalize guia de configuração","ferramentas de chat de trabalho","colaboração em equipe","desenvolvimento de software"],"ru":["как использовать finalize","что такое finalize","finalize альтернатива","finalize vs slack","finalize установка","finalize руководство по настройке","инструменты командной чаты","сотрудничество в команде","разработка программного обеспечения"],"ar":["كيفية استخدام finalize","ما هو finalize","finalize بديل","finalize مقابل slack","finalize تثبيت","finalize دليل الإعداد","أدوات الدردشة الخاصة بالعمل","التعاون الفريق","تطوير البرمجيات"]}},"owner":"inline-chat","repo":"inline","repoPath":"inline-chat/inline","stars":0,"forks":0,"updatedAt":"2026-02-27T01:51:08.518Z","topics":[],"category":"community","skillMd":{"name":"finalize","description":"Finalize work to prepare a commit. Clean up unnecessary debug logs, remove unused methods added, do a final review to ensure tight elegant implementation, etc.","bodyPreview":"# High-level work\n\nUser is mostly happy with the outcome and has probably done some manual QA checklist and is ready to finish up the task at hand to be committed and released to production.\n\n# Instructions\n\n- Review the work done so far. See section on review criteria below.\n- Clean up. See section on clean up workflow.\n- Run related tests/lint/typecheck. If change is UI code, make sure we didn''t break any other UI that uses the view we modified. \n- Prepare a list of changes, and a commit messa","body":"# High-level work\n\nUser is mostly happy with the outcome and has probably done some manual QA checklist and is ready to finish up the task at hand to be committed and released to production.\n\n# Instructions\n\n- Review the work done so far. See section on review criteria below.\n- Clean up. See section on clean up workflow.\n- Run related tests/lint/typecheck. If change is UI code, make sure we didn''t break any other UI that uses the view we modified. \n- Prepare a list of changes, and a commit message.\n- If the scope is large, summarize work using the skill before committing. If the scope is minimal and review is safe, commit.\n- If `$summarize-work` was run immediately before this, move faster: avoid re-reading files and proceed to commit after minimal checks.\n\n# Review criteria\n\n- Make sure the work done matches the spec \n- Make sure we don''t introduce unfinished work\n- Make sure we didn''t accidentally remove another part of the code in the file, or if we removed a function/class/file make sure it''s not referenced or used anywhere else. Tell the user if we removed anything.\n- Make sure we didn''t accidentally expose secrets, credentials, or hard code anything that is different in production without if protecting it to env.\n- If there are changes in the working directory that are not from this session, ignore those and don''t mention or include them in the commit.\n\n# Clean up workflow\n\n- Clean up unused code we added earlier in the sessions that is no longer needed.\n- Remove debug logs that are not helpful to remain in code or we added to debug an issue.\n- Follow best practices for preparing a commit.\n\n# Preflight checklist\n- `git status` clean of unrelated changes (ignore but do not touch).\n- Scan for debug logs and remove if not required.\n- Verify no secrets or hardcoded prod values were introduced.\n\n# Test scope\n- Run minimal, focused tests only; ask before heavy commands.\n\n# Commit prep\n- Propose a commit message in repo style.\n- End with “Production readiness” note and any risks.\n"},"lastSynced":"2026-02-27T02:45:22.954Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents needing to streamline commit and release workflows.","zh":"非常适合需要简化提交和发布工作流程的开发Agent。","ja":"コミットとリリースのワークフローを効率化する必要がある開発エージェントに最適です。","ko":"커밋 및 릴리스 워크플로우를 간소화해야 하는 개발 에이전트에 이상적입니다.","es":"Ideal para Development Agents que necesitan optimizar los flujos de trabajo de commit y release.","fr":"Idéal pour les Development Agents ayant besoin de rationaliser les flux de travail de commit et de release.","de":"Ideal für Development Agents, die Commit- und Release-Workflows optimieren müssen.","pt":"Ideal para Agentes de Desenvolvimento que precisam otimizar fluxos de trabalho de commit e release.","ru":"Идеально подходит для Development Agents, которым необходимо оптимизировать рабочие процессы коммитов и выпусков.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى تبسيط عمليات commit و release."},"recommendation":{"en":"Empowers agents to execute thorough review criteria checks, run related tests and lint/typecheck, and prepare detailed commit messages using UI code validation and automated testing protocols.","zh":"使Agent能够执行全面的审查标准检查、运行相关测试和lint/typecheck，并使用UI代码验证和自动化测试协议准备详细的提交消息。","ja":"エージェントが徹底的なレビュー基準チェックの実行、関連テストおよびlint/typecheckの実行、UIコード検証と自動テストプロトコルを使用した詳細なコミットメッセージの準備を可能にします。","ko":"에이전트가 철저한 검토 기준 확인을 실행하고, 관련 테스트 및 lint/typecheck를 실행하며, UI 코드 검증 및 자동화된 테스트 프로토콜을 사용하여 상세한 커밋 메시지를 준비할 수 있도록 합니다.","es":"Permite a los agentes ejecutar comprobaciones exhaustivas de criterios de revisión, ejecutar pruebas relacionadas y lint/typecheck, y preparar mensajes de commit detallados utilizando la validación de código de UI y protocolos de testing automatizado.","fr":"Permet aux agents d''exécuter des vérifications exhaustives des critères de revue, d''exécuter les tests associés et le lint/typecheck, et de préparer des messages de commit détaillés en utilisant la validation de code UI et les protocoles de testing automatisé.","de":"Ermöglicht es Agents, umfassende Prüfkriterien zu überprüfen, verwandte Tests sowie Lint-/TypeCheck-Läufe durchzuführen und detaillierte Commit-Messages unter Verwendung von UI-Code-Validierung und automatisierten Testing-Protokollen zu erstellen.","pt":"Capacita os agentes a executar verificações de critérios de revisão completas, executar testes relacionados e lint/typecheck, e preparar mensagens de commit detalhadas usando validação de código de UI e protocolos de teste automatizados.","ru":"Позволяет агентам выполнять тщательные проверки критериев обзора, запускать связанные тесты и проверки lint/typecheck, а также подготавливать подробные сообщения коммитов с использованием проверки кода UI и протоколов автоматизированного тестирования.","ar":"يمكن الوكلاء من تنفيذ عمليات فحص معايير المراجعة الشاملة، وتشغيل الاختبارات ذات الصلة وفحص lint/typecheck، وإعداد رسائل commit مفصلة باستخدام التحقق من صحة كود واجهة المستخدم وبروتوكولات الاختبار الآلي."},"useCases":{"en":["Automating manual QA checklist reviews","Generating commit messages with detailed change lists","Validating UI code changes against existing views"],"zh":["自动化手动QA检查清单审查","生成带有详细变更列表的提交消息","根据现有视图验证UI代码变更"],"ja":["手動QAチェックリストレビューの自動化","詳細な変更リストを含むコミットメッセージの生成","既存のビューに対するUIコード変更の検証"],"ko":["수동 QA 체크리스트 검토 자동화","상세 변경 목록이 포함된 커밋 메시지 생성","기존 뷰에 대한 UI 코드 변경 사항 검증"],"es":["Automatización de revisiones manuales de listas de verificación QA","Generación de mensajes de commit con listas de cambios detalladas","Validación de cambios de código de UI con respecto a las vistas existentes"],"fr":["Automatisation des revues manuelles des checklists QA","Génération de messages de commit avec des listes de modifications détaillées","Validation des modifications de code UI par rapport aux vues existantes"],"de":["Automatisierung manueller QA-Checklist-Überprüfungen","Generierung von Commit-Messages mit detaillierten Änderungslisten","Validierung von UI-Code-Änderungen anhand bestehender Views"],"pt":["Automatizando revisões manuais de checklist de QA","Gerando mensagens de commit com listas de alterações detalhadas","Validando alterações de código de UI em relação às visualizações existentes"],"ru":["Автоматизация ручных проверок контрольного списка QA","Генерация сообщений коммитов с подробными списками изменений","Проверка изменений кода UI по сравнению с существующими представлениями"],"ar":["أتمتة مراجعات قوائم مراجعة ضمان الجودة اليدوية","إنشاء رسائل commit مع قوائم التغييرات المفصلة","التحقق من صحة تغييرات كود واجهة المستخدم مقابل المشاهدات الحالية"]},"limitations":{"en":["Requires access to project codebase","Limited to UI code and related tests"],"zh":["需要访问项目代码库","仅限于UI代码和相关测试"],"ja":["プロジェクトコードベースへのアクセスが必要","UIコードと関連テストに限定される"],"ko":["프로젝트 코드베이스에 대한 액세스 필요","UI 코드 및 관련 테스트로 제한됨"],"es":["Requiere acceso al codebase del proyecto","Limitado a código de UI y pruebas relacionadas"],"fr":["Nécessite un accès au codebase du projet","Limité au code UI et aux tests associés"],"de":["Erfordert Zugriff auf die Projekt-Codebase","Beschränkt auf UI-Code und verwandte Tests"],"pt":["Requer acesso ao codebase do projeto","Limitado a código de UI e testes relacionados"],"ru":["Требуется доступ к кодовой базе проекта","Ограничено кодом UI и связанными тестами"],"ar":["يتطلب الوصول إلى قاعدة كود المشروع","يقتصر على كود واجهة المستخدم والاختبارات ذات الصلة"]},"version":3},"contentHash":"89cbbf36633846910fb5c7e9b0318a73f833643d25ac022c9ba804d694098373","qualityScore":41}');
