INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cannuri/lobsidian/lobsidian', 'lobsidian', 'cannuri', 'lobsidian', 'community', 'lobsidian cannuri lobsidian community lobsidian 为 AI 代理提供结构化问责和简单的 markdown 协议 lobsidian は AI エージェントに構造化された説明責任とシンプルな markdown プロトコルを提供 lobsidian은 AI 에이전트에 구조화된 책임과 단순한 markdown 프로토콜을 제공 Lobisidian es un protocolo de markdown para motivos, decisiones y tareas de agentes de IA, que proporciona responsabilidad estructurada para herramientas de AI. Lobisidian est un protocole markdown pour les motifs, les décisions et les tâches des agents d''IA, qui offre une responsabilité structurée pour les outils d''IA. Lobisidian ist ein Markdown-Protokoll für Motive, Entscheidungen und Aufgaben von KI-Agents, das strukturierte Verantwortung für AI-Tools bietet. O Lobsidian é uma ferramenta de conta AI que fornece responsabilidade estruturada para agentes de IA com protocolo de marcação em markdown. Lobsidian - это инструмент ИИ Агентов, обеспечивающий структурированную отчетность с помощью протокола markdown. لوبسيديان هو أداة ذكاء اصطناعي تقدم مساءلة منظمة للوكلاء الذكاء الاصطناعي ببروتوكول markdown Structured accountability for AI agents. Plain markdown protocol for motives, decisions, and tasks. 如何使用 lobsidian 什么是 AI 代理 lobsidian 替代品 lobsidian 安装 AI 代理工具 lobsidian 文档 Structured accountability for AI agents. Plain markdown protocol for motives, decisions, and tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SamarthaKV29/antigravity-god-mode/fal-platform', 'community', 'SamarthaKV29', 'antigravity-god-mode', 'SamarthaKV29/antigravity-god-mode', 'fal-platform', 0, 0, 41, '2026-03-07T01:49:01.466Z', '2026-03-07T01:56:10.112Z', 'f595ac3e56ed2c2281e3db5d9dff2255c1f1b1e7458f098da1e9716e096a5a78', '{"id":"SamarthaKV29/antigravity-god-mode/fal-platform","name":"fal-platform","description":{"en":"The fal-platform skill turns any AI coding agent into a full engineering team by providing platform APIs for model management, pricing, and usage tracking, benefiting developers and engineers.","zh":"Fal Platform是一个-drop-in技能包，用于将任何AI编码代理转换为全功能工程团队，提供平台API用于模型管理、定价和使用跟踪","ja":"Fal Platformは、任意のAIエージェントをフルエンジニアリングチームに変えるためのdrop-inスキルパックです。プラットフォームAPIを使用してモデル管理、価格設定、使用状況追跡を行います","ko":"Fal Platform은任意의 AI 코딩 에이전트를 완전한 엔지니어링 팀으로 전환하는 drop-in 스킬 팩입니다. 플랫폼 API를 사용하여 모델 관리, 가격 설정 및 사용량 추적을 수행합니다","es":"Fal-platform es un paquete de habilidades que proporciona APIs de plataforma para la gestión de modelos, precios y seguimiento de uso","fr":"Fal-platform est un pack de compétences qui fournit des API de plateforme pour la gestion de modèles, de tarifs et de suivi d''utilisation","de":"Fal-platform ist ein Skill-Paket, das Plattform-APIs für Modellmanagement, Preisgestaltung und Nutzungsverfolgung bereitstellt","pt":"O Fal Platform é um pacote de habilidades que transforma qualquer agente de codificação de IA em uma equipe de engenharia completa, fornecendo APIs de plataforma para gerenciamento de modelos, preços e rastreamento de uso","ru":"Fal Platform - это набор навыков, который превращает любого агента кодирования ИИ в полную инженерную команду, предоставляя платформенные API для управления моделями, ценами и отслеживания использования","ar":"منصة Fal هي حزمة مهارات تحول أي وكيل ترميز ذكاء اصطناعي إلى فريق هندسي كامل، تقدم واجهات برمجة تطبيقات منصة لإدارة النماذج والأسعار وتتبع الاستخدام"},"seo":{"title":{"en":"fal-platform: Platform APIs Setup Guide | AI Agent Skill","zh":"Fal Platform集成指南 - AI编码代理全功能工程团队","ja":"Fal Platformセットアップガイド - AIエージェントをフルエンジニアリングチームに","ko":"Fal Platform 설정 가이드 - AI 코딩 에이전트를 완전한 엔지니어링 팀으로","es":"Guía de configuración de fal-platform para Agentes de IA","fr":"Guide de mise en place de fal-platform pour les Agents IA","de":"Einrichtungsanleitung für fal-platform für KI-Agents","pt":"Guia de Configuração do Fal Platform para Agentes de IA","ru":"Руководство по настройке Fal Platform для ИИ Агентов","ar":"دليل إعداد منصة Fal للوكلاء الذكيين"},"description":{"en":"Unlock the full potential of your AI coding agent with fal-platform, learn how to work with platform APIs for model management, pricing, and usage tracking t...","zh":"了解Fal Platform的功能和优点，打造全功能AI编码代理工程团队","ja":"Fal Platformの機能と利点を学び、AIエージェントをフルエンジニアリングチームに","ko":"Fal Platform의 기능과 장점을 배우고 AI 코딩 에이전트를 완전한 엔지니어링 팀으로 전환","es":"Aprende a utilizar fal-platform para convertir cualquier agente de codificación de IA en un equipo de ingeniería completo","fr":"Découvrez comment utiliser fal-platform pour transformer n''importe quel agent de codage IA en une équipe d''ingénierie complète","de":"Erfahren Sie, wie Sie fal-platform verwenden, um jeden IA-Coding-Agent in ein vollständiges Ingenieurteam umzuwandeln","pt":"Aprenda a integrar o Fal Platform em seus agentes de IA para gerenciar modelos, preços e rastrear uso com APIs de plataforma","ru":"Узнайте, как интегрировать Fal Platform в ваши ИИ Агенты для управления моделями, ценами и отслеживания использования с помощью платформенных API","ar":"تعلم كيفية دمج منصة Fal في وكلائك الذكيين لإدارة النماذج والأسعار وتتبع الاستخدام باستخدام واجهات برمجة التطبيقات للمنصة"},"definition":{"en":"fal-platform is a drop-in skill pack that enables AI coding agents to manage models, track usage, and handle pricing via platform APIs.","zh":"Fal Platform是一种drop-in技能包，用于扩展AI编码代理的功能","j