INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SamarthaKV29/antigravity-god-mode/fal-platform', 'fal-platform', 'SamarthaKV29', 'antigravity-god-mode', 'community', 'fal-platform SamarthaKV29 antigravity-god-mode community The fal-platform skill turns any AI coding agent into a full engineering team by providing platform APIs for model management, pricing, and usage tracking, benefiting developers and engineers. Fal Platform是一个-drop-in技能包，用于将任何AI编码代理转换为全功能工程团队，提供平台API用于模型管理、定价和使用跟踪 Fal Platformは、任意のAIエージェントをフルエンジニアリングチームに変えるためのdrop-inスキルパックです。プラットフォームAPIを使用してモデル管理、価格設定、使用状況追跡を行います Fal Platform은任意의 AI 코딩 에이전트를 완전한 엔지니어링 팀으로 전환하는 drop-in 스킬 팩입니다. 플랫폼 API를 사용하여 모델 관리, 가격 설정 및 사용량 추적을 수행합니다 Fal-platform es un paquete de habilidades que proporciona APIs de plataforma para la gestión de modelos, precios y seguimiento de uso Fal-platform est un pack de compétences qui fournit des API de plateforme pour la gestion de modèles, de tarifs et de suivi d''utilisation Fal-platform ist ein Skill-Paket, das Plattform-APIs für Modellmanagement, Preisgestaltung und Nutzungsverfolgung bereitstellt O Fal Platform é um pacote de habilidades que transforma qualquer agente de codificação de IA em uma equipe de engenharia completa, fornecendo APIs de plataforma para gerenciamento de modelos, preços e rastreamento de uso Fal Platform - это набор навыков, который превращает любого агента кодирования ИИ в полную инженерную команду, предоставляя платформенные API для управления моделями, ценами и отслеживания использования منصة Fal هي حزمة مهارات تحول أي وكيل ترميز ذكاء اصطناعي إلى فريق هندسي كامل، تقدم واجهات برمجة تطبيقات منصة لإدارة النماذج والأسعار وتتبع الاستخدام how to use fal-platform fal-platform alternative fal-platform setup guide what is fal-platform fal-platform vs competitors fal-platform install fal-platform for AI agents platform APIs for model management pricing and usage tracking with fal-platform Fal Platform AI编码代理 全功能工程团队 平台API 模型管理 定价 使用跟踪 drop-in技能包 GitHub源仓库 Provides platform APIs for model management Supports pricing and usage tracking Offers guidance and patterns for platform APIs Includes documentation in the source repository on GitHub Enables working with model management, pricing, and usage tracking APIs fal-platform is a drop-in skill pack that enables AI coding agents to manage models, track usage, and handle pricing via platform APIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/sentry-javascript/upgrade-otel', 'community', 'getsentry', 'sentry-javascript', 'getsentry/sentry-javascript', 'upgrade-otel', 8596, 1754, 40, '2026-02-28T01:25:16Z', '2026-03-06T06:25:07.745Z', 'e0d1bfbd5f40ba422b929d5364307fb66a9785aad5e953f5642f561c3e904f1e', '{"id":"getsentry/sentry-javascript/upgrade-otel","name":"upgrade-otel","description":{"en":"The upgrade-otel skill helps developers upgrade OpenTelemetry instrumentations for JavaScript applications, ensuring a smooth transition without breaking changes.","zh":"升级OpenTelemetry Instrumentations，包括@opentelemetry/instrumentation和@opentelemetry/instrumentation-*包的最新版本","ja":"OpenTelemetry Instrumentationsのアップグレード、@opentelemetry/instrumentationと@opentelemetry/instrumentation-*パッケージの最新バージョンを含む","ko":"OpenTelemetry Instrumentations 업그레이드, @opentelemetry/instrumentation과 @opentelemetry/instrumentation-* 패키지의 최신 버전 포함","es":"Actualiza tus instrumentaciones de OpenTelemetry de manera segura. Sigue nuestra guía para asegurarte de que tus actualizaciones sean libres de cambios de ruptura","fr":"Mettez à niveau vos instrumentations OpenTelemetry en toute sécurité. Suivez notre guide pour vous assurer que vos mises à niveau sont exemptes de changements de rupture","de":"Aktualisieren Sie Ihre OpenTelemetry-Instrumentierungen sicher. Befolgen Sie unsere Anleitung, um sicherzustellen, dass Ihre Aktualisierungen frei von brechenden Änderungen sind","pt":"O upgrade-otel é uma ferramenta oficial para atualizar o OpenTelemetry. Leia os logs de alterações antes de prosseguir.","ru":"Upgrade-otel - это официальный инструмент для обновления OpenTelemetry. Читайте журналы изменений перед продолжением.","ar":"ترقية OpenTelemetry هي أداة رسمية لترقية OpenTelemetry. اقرأ سجلات التغييرات قبل المتابعة."},"seo":{"title":{"en":"upgrade-otel: OpenTelemetry Instrumentat