INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/sentry-javascript/upgrade-otel', 'upgrade-otel', 'getsentry', 'sentry-javascript', 'community', 'upgrade-otel getsentry sentry-javascript community angular crash-reporting ember error-monitoring hacktoberfest javascript javascript-client nextjs node raven react sdk sentry sentry-client tag-production team-sdk-javascript team-web-frontend typescript vue The upgrade-otel skill helps developers upgrade OpenTelemetry instrumentations for JavaScript applications, ensuring a smooth transition without breaking changes. 升级OpenTelemetry Instrumentations，包括@opentelemetry/instrumentation和@opentelemetry/instrumentation-*包的最新版本 OpenTelemetry Instrumentationsのアップグレード、@opentelemetry/instrumentationと@opentelemetry/instrumentation-*パッケージの最新バージョンを含む OpenTelemetry Instrumentations 업그레이드, @opentelemetry/instrumentation과 @opentelemetry/instrumentation-* 패키지의 최신 버전 포함 Actualiza tus instrumentaciones de OpenTelemetry de manera segura. Sigue nuestra guía para asegurarte de que tus actualizaciones sean libres de cambios de ruptura Mettez à niveau vos instrumentations OpenTelemetry en toute sécurité. Suivez notre guide pour vous assurer que vos mises à niveau sont exemptes de changements de rupture Aktualisieren Sie Ihre OpenTelemetry-Instrumentierungen sicher. Befolgen Sie unsere Anleitung, um sicherzustellen, dass Ihre Aktualisierungen frei von brechenden Änderungen sind O upgrade-otel é uma ferramenta oficial para atualizar o OpenTelemetry. Leia os logs de alterações antes de prosseguir. Upgrade-otel - это официальный инструмент для обновления OpenTelemetry. Читайте журналы изменений перед продолжением. ترقية OpenTelemetry هي أداة رسمية لترقية OpenTelemetry. اقرأ سجلات التغييرات قبل المتابعة. how to upgrade OpenTelemetry instrumentations upgrade-otel alternative OpenTelemetry instrumentation upgrade guide upgrade-otel setup tutorial what is upgrade-otel upgrade-otel vs OpenTelemetry upgrade-otel install upgrade-otel for JavaScript applications OpenTelemetry upgrade best practices OpenTelemetry Instrumentations升级 升级@opentelemetry/instrumentation JavaScript升级 Node.js升级 React升级 Angular升级 Vue.js升级 Upgrades @opentelemetry/instrumentation to the latest version Supports upgrading all @opentelemetry/instrumentation-* packages Checks changelogs for each package, including @opentelemetry/opentelemetry-js and @opentelemetry/opentelemetry-js-contrib Ensures all upgrades are free of breaking changes Follows a specific upgrade order for packages, including packages/** Provides access to changelogs for verification, such as https://github.com/open-telemetry/opentelemetry-js/blob/main/experimental/CHANGELOG.md upgrade-otel is a skill that facilitates the upgrade of OpenTelemetry instrumentations for JavaScript, following a specific order and checking changelogs for each package.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('golemcloud/golem/modifying-service-configs', 'community', 'golemcloud', 'golem', 'golemcloud/golem', 'modifying-service-configs', 967, 170, 40, '2026-02-27T18:10:13Z', '2026-03-06T06:26:27.315Z', 'c2efa2afd403a6a0eaccd794fec9f69749c87e903840291b52450efd8ffedbfe', '{"id":"golemcloud/golem/modifying-service-configs","name":"modifying-service-configs","description":{"en":"The modifying-service-configs skill enables developers to configure Golem services using Figment and TOML, ensuring durable computing and fault-tolerance for AI agents.","zh":"修改服务配置是Golem Cloud AI代理运行时的关键部分，使用Figment和TOML实现可靠的配置管理","ja":"サービス設定の変更はGolem Cloud AIエージェントランタイムの重要な部分であり、FigmentとTOMLを使用して信頼性の高い設定管理を実現します","ko":"서비스 설정 수정은 Golem Cloud AI 에이전트 런타임의 중요한 부분으로 Figment와 TOML을 사용하여 안정적인 설정 관리를 구현합니다","es":"Modifica configuraciones de servicios en Golem Cloud utilizando Figment y TOML","fr":"Configurez les services d''agents IA sur Golem Cloud avec Figment et TOML","de":"Passen Sie Dienstkonfigurationen in Golem Cloud mit Figment und TOML an","pt":"Modificando configurações de serviço no Golem Cloud para aplicativos distribuídos com Figment e TOML.","ru":"Настройка конфигураций сервисов в Golem Cloud для распределенных приложений и ИИ Агентов с помощью Figment и TOML.","ar":"تعديل إعدادات الخدمة في Golem Cloud لتطبيقات موزعة ووكلاء الذكاء الاصطناعي باستخدام Figment و TOML."},"seo":{"title":{"en":"modifying-service-configs: Configuration Setup Guide for ...","zh":"修改服务配置 Setup Guide - AIエージェント开发","ja":"サービス設定の変更方法 - AIエージェントのベストプラクティス","ko":"서비스 설정 수정 가이드 - AI 에이전트 개발","es":"Guía de configuración de servicios de AI Agents","fr":"Configurer les services d''agents IA avec succès","de":"Anleitung zur Konfiguration von AI-Agent-Diensten","pt":"Modificando Configurações de Serviço com Golem Cloud","ru":"Настройка конфигураций сервисов с помощь