INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('golemcloud/golem/modifying-service-configs', 'modifying-service-configs', 'golemcloud', 'golem', 'community', 'modifying-service-configs golemcloud golem community agentic agentic-ai agentic-runtime agents ai ai-agent-runtime component-model distributed-systems durable-computing durable-execution fault-tolerance high-reliability serverless wasi wasm wasm-component The modifying-service-configs skill enables developers to configure Golem services using Figment and TOML, ensuring durable computing and fault-tolerance for AI agents. 修改服务配置是Golem Cloud AI代理运行时的关键部分，使用Figment和TOML实现可靠的配置管理 サービス設定の変更はGolem Cloud AIエージェントランタイムの重要な部分であり、FigmentとTOMLを使用して信頼性の高い設定管理を実現します 서비스 설정 수정은 Golem Cloud AI 에이전트 런타임의 중요한 부분으로 Figment와 TOML을 사용하여 안정적인 설정 관리를 구현합니다 Modifica configuraciones de servicios en Golem Cloud utilizando Figment y TOML Configurez les services d''agents IA sur Golem Cloud avec Figment et TOML Passen Sie Dienstkonfigurationen in Golem Cloud mit Figment und TOML an Modificando configurações de serviço no Golem Cloud para aplicativos distribuídos com Figment e TOML. Настройка конфигураций сервисов в Golem Cloud для распределенных приложений и ИИ Агентов с помощью Figment и TOML. تعديل إعدادات الخدمة في Golem Cloud لتطبيقات موزعة ووكلاء الذكاء الاصطناعي باستخدام Figment و TOML. how to use modifying-service-configs modifying-service-configs setup guide Golem Cloud configuration management Figment and TOML configuration durable computing and fault-tolerance modifying-service-configs vs traditional configuration methods AIエージェント开发 服务配置修改 Figment TOML AI代理运行时 分布式系统 serverless Golem Cloud Implements configuration structs with Default, Serialize, and Deserialize interfaces Utilizes Figment via a custom ConfigLoader for configuration management Serializes configuration defaults to TOML and env-var reference files Validates configuration in CI for high-reliability and fault-tolerance Supports durable computing and execution in distributed systems modifying-service-configs is a skill for configuring Golem services using a custom ConfigLoader and Figment, providing default values and serialization to TOML and env-var reference files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('causify-ai/helpers/coding.fix_from_imports', 'community', 'causify-ai', 'helpers', 'causify-ai/helpers', 'coding.fix_from_imports', 141, 128, 40, '2026-02-28T18:01:51Z', '2026-03-06T06:29:39.787Z', '60f90536632903a38bc46ec499b9220a48543a630e281624a358a263f9bdddae', '{"id":"causify-ai/helpers/coding.fix_from_imports","name":"coding.fix_from_imports","description":{"en":"The coding.fix_from_imports skill optimizes Python imports by replacing statements like from X import Y with import X and updating uses of Y to X.Y, benefiting Python developers.","zh":"coding.fix_from_imports 是一种 Python 代码优化工具，能够自动替换导入语句，提高代码的可读性和维护性","ja":"coding.fix_from_imports は Python コードを最適化するツールで、インポート文を自動的に置き換えてコードの可読性と保守性を向上させる","ko":"coding.fix_from_imports는 Python 코드를 최적화하는 도구로, 임포트 문을 자동으로 교체하여 코드의 가독성과 유지 보수성을 향상시킵니다","es":"Coding.fix_from_imports es una herramienta de desarrollo que reemplaza importaciones como ''from X import Y'' con ''import X'' y ''X.Y'', mejorando la legibilidad del código","fr":"Coding.fix_from_imports est un outil de développement qui remplace des importations comme ''from X import Y'' par ''import X'' et ''X.Y'', améliorant la lisibilité du code","de":"Coding.fix_from_imports ist ein Entwicklungstool, das Importe wie ''from X import Y'' durch ''import X'' und ''X.Y'' ersetzt, um die Lesbarkeit des Codes zu verbessern","pt":"coding.fix_from_imports é uma ferramenta que ajuda a reorganizar importações em projetos Python. Ele substitui declarações de importação por versões mais concisas.","ru":"coding.fix_from_imports - это инструмент, помогающий реорганизовать импорты в проектах Python. Он заменяет операторы импорта на более краткие версии.","ar":"coding.fix_from_imports هو أداة تساعد في إعادة تنظيم الاستيراد في مشاريع Python. يقوم باستبدال عبارات الاستيراد بنسخ أكثر إيجازًا."},"seo":{"title":{"en":"coding.fix_from_imports: Python Import Optimization Setup...","zh":"Python导入优化： coding.fix_from_imports 设置指南","ja":"Pythonインポートの最適化： coding.fix_from_imports 導入ガイド","ko":"Python 임포트 최적화: coding.fix_from_imports 설정 가이드","es":"Guía de configuración para coding.fix_from_imports: Mejor...","fr":"Guide de configuration pour coding.fix_from_imports : Amé...","de":"Konfigurationsleitfaden für coding.fix_from_imports: Opti...","pt":"Guia de Configuração coding.fix_from_imports para Python","ru":"Настройка coding.fix_from_imports для ИИ Агентов Python","ar":"دليل إعداد coding.fix_from_imports لبرمجة Python"},"description":{"en":"Discover how coding.fix_from_imports simplifies Python imports. Learn to replace from X import Y with import X and optimize your code today!","zh":"了解 coding.fix_from_imports 的功能和优点，优化 Python 代码中的导入语句，提高开发效率","ja":"coding.fix_from_imports の機能と利点を学び、Python コードのインポート文を最適化して開発効率を向上させる","ko":"coding.fix_from_imports의 기능과 이점을 학습하고, Python 코드의 임포트 문을 최적화하여 개발 효율을 향상시키는 방법","es":"Descubre cómo coding.fix_from_imports mejora la estructura de importaciones en Python, simplificando el código y mejorando la legibilidad","fr":"Découvrez comment coding.fix_from_imports améliore la structure des importations Python, simplifiant le code et améliorant la lisibilité","de":"Erfahren Sie, wie coding.fix_from_imports die Importstruktur in Python verbessert, den Code vereinfacht und die Lesbarkeit erhöht","pt":"Aprenda a configurar coding.fix_from_imports para melhorar a organização de importações em projetos Python com ferramentas de desenvolvimento de IA","ru":"Узнайте, как настроить coding.fix_from_imports для улучшения организации импортов в проектах Python с помощью ИИ Агентов","ar":"تعلم كيفية إعداد coding.fix_from_imports لتحسين تنظيم الاستيراد في مشاريع Python باستخدام أدوات تطوير الذكاء الاصطناعي"},"definition":{"en":"coding.fix_from_imports is a Python import optimization technique that standardizes import statements for improved code readability and maintainability.","zh":"coding.fix_from_imports 是一种 Python 代码优化工具，用于自动替换导入语句","ja":"coding.fix_from_imports は Python コードを最適化するツールで、インポート文を自動的に置き換える","ko":"coding.fix_from_imports는 Python 코드를 최적화하는 도구로, 임포트 문을 자동으로 교체합니다","es":"Coding.fix_from_imports es una herramienta que reformatea importaciones Python para mejorar la legibilidad","fr":"Coding.fix_from_imports est un outil qui reformate les importations Python pour améliorer la lisibilité","de":"Coding.fix_from_imports ist ein Tool, das Python-Importe umformatiert, um die Lesbarkeit zu verbessern","pt":"coding.fix_from_imports é uma ferramenta de desenvolvimento que reorganiza importações Python","ru":"coding.fix_from_imports - это инструмент развития, реорганизующий импорты Python","ar":"coding.fix_from_imports هو أداة تطوير ترتب الاستيراد في Python"},"features":{"en":["Replaces Python statements like from X import Y with import X and updates uses of Y to X.Y","Converts aliased imports from X import Y as Z to import X and replaces uses of Z with X.Y","Handles nested module imports from X.Y import Z by converting to import X.Y and replacing uses of Z with X.Y.Z","Preserves specific imports like from __future__ import annotations and from typing import Any, Dict, List, Optional","Standardizes import statements for improved code readability and maintainability"],"zh":["自动替换导入语句","支持 aliased 导入","支持 nested 模块导入","保留特定导入语句（如 from __future__ import annotations）"],"ja":["インポート文の自動置き換え","エイリアスインポートのサポート","ネストされたモジュールインポートのサポート","特定のインポート文の保持（from __future__ import annotations など）"],"ko":["임포트 문 자동 교체","별칭 임포트 지원","중첩된 모듈 임포트 지원","특정 임포트 문 유지（from __future__ import annotations 등）"],"es":["Reemplaza importaciones como ''from X import Y'' con ''import X'' y ''X.Y''","Soporta importaciones anidadas como ''from X.Y import Z''","Mantiene importaciones específicas como ''from __future__ import annotations''","Mejora la legibilidad del código","Simplifica la estructura de importaciones"],"fr":["Remplace des importations comme ''from X import Y'' par ''import X'' et ''X.Y''","Prend en charge des importations imbriquées comme ''from X.Y import Z''","Conserve des importations spécifiques comme ''from __future__ import annotations''","Améliore la lisibilité du code","Simplifie la structure des importations"],"de":["Ersetzt Importe wie ''from X import Y'' durch ''import X'' und ''X.Y''","Unterstützt verschachtelte Importe wie ''from X.Y import Z''","Behält bestimmte Importe wie ''from __future__ import annotations'' bei","Verbessert die Lesbarkeit des Codes","Vereinfacht die Importstruktur"],"pt":["Substitui declarações de importação por versões mais concisas","Suporta importações aninhadas e alias","Manuseia importações de módulos futuros e tipagem","Reorganiza importações para melhorar a legibilidade do código","Compatível com projetos Python de grande escala"],"ru":["Заменяет операторы импорта на более краткие версии","Поддерживает вложенные импорты и псевдонимы","Обрабатывает импорты из модулей будущего и типизации","Реорганизует импорты для улучшения читаемости кода","Совместим с крупномасштабными проектами Python"],"ar":["استبدال عبارات الاستيراد بنسخ أكثر إيجازًا","دعم الاستيراد المتداخل والأسماء المستعارة","معالجة استيراد المكونات الإضافية والتصنيف","إعادة تنظيم الاستيراد لتحسين قراءة الكود","متوافق مع مشاريع Python ذات الحجم الكبير"]},"keywords":{"en":["how to use coding.fix_from_imports","coding.fix_from_imports setup guide","python import optimization techniques","coding.fix_from_imports vs importlib","what is coding.fix_from_imports","coding.fix_from_imports install","python coding best practices","import X vs from X import Y","coding.fix_from_imports alternative","python code readability"],"zh":["Python 代码优化","导入语句优化","coding.fix_from_imports","Python 开发工具","代码可读性","代码维护性","AIエージェント"],"ja":["Python コード最適化","インポート文最適化","coding.fix_from_imports","Python 開発ツール","コード可読性","コード保守性","AIエージェント"],"ko":["Python 코드 최적화","임포트 문 최적화","coding.fix_from_imports","Python 개발 도구","코드 가독성","코드 유지 보수성","AI 에이전트"],"es":["herramientas de desarrollo","mejora de importaciones","legibilidad de código","estructura de importaciones","Python","importaciones anidadas","coding.fix_from_imports","agente de código"],"fr":["outils de développement","amélioration des importations","lisibilité du code","structure des importations","Python","importations imbriquées","coding.fix_from_imports","agent de code"],"de":["Entwicklungstools","Optimierung von Importen","Lesbarkeit von Code","Importstruktur","Python","verschachtelte Importe","coding.fix_from_imports","Code-Agent"],"pt":["coding.fix_from_imports","ferramentas de desenvolvimento Python","organização de importações","melhoria de código","desenvolvimento de IA","Python para desenvolvedores","otimização de importações"],"ru":["coding.fix_from_imports","инструменты разработки Python","организация импортов","улучшение кода","разработка ИИ","Python для разработчиков","оптимизация импортов"],"ar":["coding.fix_from_imports","أدوات تطوير Python","تنظيم الاستيراد","تحسين الكود","تطوير الذكاء الاصطناعي","Python للمطورين","تحسين الاستيراد"]}},"owner":"causify-ai","repo":"helpers","repoPath":"causify-ai/helpers","stars":141,"forks":128,"updatedAt":"2026-02-28T18:01:51Z","topics":[],"category":"community","skillMd":{"name":"coding.fix_from_imports","description":"Replace from X import Y style imports with import X and update usages throughout a file","bodyPreview":"- Replace any Python statement like `from X import Y` with the form `import X`\n  and then replace the uses of `Y` with `X.Y`\n\n- For aliased imports `from X import Y as Z`, convert to `import X` and replace\n  all uses of `Z` with `X.Y`\n\n- For nested module imports `from X.Y import Z`, convert to `import X.Y` and\n  replace all uses of `Z` with `X.Y.Z`\n\n- The only ones that can stay as `from X import Y` are:\n  ```\n  from __future__ import annotations\n  from typing import Any, Dict, List, Optional,","body":"- Replace any Python statement like `from X import Y` with the form `import X`\n  and then replace the uses of `Y` with `X.Y`\n\n- For aliased imports `from X import Y as Z`, convert to `import X` and replace\n  all uses of `Z` with `X.Y`\n\n- For nested module imports `from X.Y import Z`, convert to `import X.Y` and\n  replace all uses of `Z` with `X.Y.Z`\n\n- The only ones that can stay as `from X import Y` are:\n  ```\n  from __future__ import annotations\n  from typing import Any, Dict, List, Optional, Tuple, Union, ...  (any typing name)\n  from IPython.display import display\n  ```\n"},"lastSynced":"2026-03-06T06:29:39.787Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing advanced import optimization capabilities.","zh":"非常适合需要高级导入优化能力的Python开发代理。","ja":"Python開発エージェントが高度なインポート最適化機能を必要とする場合に最適です。","ko":"고급导入 최적화 기능이 필요한 Python 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Python que necesitan capacidades de optimización de importación avanzadas.","fr":"Parfait pour les agents de développement Python ayant besoin de capacités d''optimisation d''importation avancées.","de":"Perfekt für Python-Entwicklungsagenten, die erweiterte Import-Optimierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de capacidades de otimização de importação avançadas.","ru":"Идеально подходит для агентов разработки Python, которым необходимы продвинутые возможности оптимизации импорта.","ar":"مثالي للوكلاء النمطية بايثون الذين يحتاجون إلى إمكانيات تحسين الاستيراد المتقدمة."},"recommendation":{"en":"Empowers agents to refactor Python code by replacing statements like from X import Y with import X and updating uses of Y to X.Y, utilizing import statements and module aliases. It streamlines Python development by converting aliased imports and nested module imports into standardized import forms, leveraging Python''s import mechanics.","zh":"赋予代理重构Python代码的能力，通过用import X替换诸如from X import Y的语句，并使用导入语句和模块别名更新Y的用法。它通过将别名导入和嵌套模块导入转换为标准化的导入形式，利用Python的导入机制，简化了Python开发。","ja":"Pythonコードをリファクタリングするエージェントの能力を付与し、from X import Yのようなステートメントをimport Xに置き換え、インポートステートメントとモジュールエイリアスを使用してYの使用を更新します。エイリアスインポートとネストされたモジュールインポートを標準化されたインポート形式に変換することで、Pythonのインポートメカニズムを利用してPython開発を簡素化します。","ko":"에이전트가 Python 코드를 리팩토링할 수 있는 기능을 부여하여 from X import Y와 같은 문장을 import X로 대체하고, import 문과 모듈 별칭을 사용하여 Y의 사용을 업데이트합니다. 별칭导入과 중첩 모듈导入을 표준화된导入 형식으로 변환하여 Python의导入 메커니즘을 활용하여 Python 개발을 단순화합니다.","es":"Habilita a los agentes a refactorizar el código Python reemplazando declaraciones como from X import Y con import X y actualizando usos de Y a X.Y, utilizando declaraciones de importación y alias de módulos. Simplifica el desarrollo de Python convirtiendo importaciones con alias y importaciones de módulos anidados en formas de importación estandarizadas, aprovechando los mecanismos de importación de Python.","fr":"Permet aux agents de refactoriser le code Python en remplaçant des instructions comme from X import Y par import X et en mettant à jour les utilisations de Y en X.Y, en utilisant les instructions d''importation et les alias de modules. Il rationalise le développement Python en convertissant les importations avec alias et les importations de modules imbriqués en formes d''importation standardisées, en exploitant les mécanismes d''importation de Python.","de":"Ermächtigt die Agenten, Python-Code zu refactorisieren, indem sie Anweisungen wie from X import Y durch import X ersetzen und die Verwendung von Y auf X.Y aktualisieren, unter Verwendung von Importanweisungen und Modul-Aliassen. Es rationalisiert die Python-Entwicklung, indem es importierte Aliase und verschachtelte Modul-Importe in standardisierte Importformen umwandelt, wodurch die Importmechanismen von Python genutzt werden.","pt":"Habilita os agentes a refatorar o código Python substituindo declarações como from X import Y por import X e atualizando os usos de Y para X.Y, utilizando declarações de importação e aliases de módulo. Isso simplifica o desenvolvimento Python convertendo imports com alias e imports de módulos aninhados em formas de importação padronizadas, aproveitando a mecânica de importação do Python.","ru":"Наделяет агентов возможностью рефакторинга кода Python, заменяя операторы вида from X import Y на import X и обновляя использования Y до X.Y, используя операторы импорта и псевдонимы модулей. Это упрощает разработку Python, конвертируя импорты с псевдонимами и вложенные импорты модулей в стандартизированные формы импорта, используя механику импорта Python.","ar":"تمكّن الوكلاء من إعادة هيكلة 코드 بايثون من خلال استبدال العبارات مثل from X import Y ب import X وتحديث استخدامات Y إلى X.Y، واستخدام عبارات الاستيراد وأسماء الموديلات. هذا يُبسط تطوير بايثون عن طريق تحويل الاستيرادات المسمّاة والاستيرادات الموديلية المتداخلة إلى أشكال استيراد معيارية، واستغلال ميكانيكا الاستيراد في بايثون."},"useCases":{"en":["Refactoring Python code to improve readability","Converting aliased imports to standard import forms","Optimizing nested module imports for better code organization"],"zh":["重构Python代码以提高可读性","将别名导入转换为标准导入形式","优化嵌套模块导入以获得更好的代码组织"],"ja":["Pythonコードの可読性を向上させるためのリファクタリング","エイリアスインポートを標準インポート形式に変換する","コードの組織を改善するためのネストされたモジュールインポートの最適化"],"ko":["可读性을 개선하기 위한 Python 코드 리팩토링","표준导入 형식으로 별칭导入을 변환하는","코드 조직을 개선하기 위한 중첩 모듈导入의 최적화"],"es":["Reorganizar el código Python para mejorar la legibilidad","Convertir importaciones con alias en formas de importación estándar","Optimizar importaciones de módulos anidados para una mejor organización del código"],"fr":["Réorganiser le code Python pour améliorer la lisibilité","Convertir les importations avec alias en formes d''importation standard","Optimiser les importations de modules imbriqués pour une meilleure organisation du code"],"de":["Python-Code neu organisieren, um die Lesbarkeit zu verbessern","Importe mit Aliassen in Standard-Importformen umwandeln","Verschachtelte Modul-Importe optimieren, um die Code-Organisation zu verbessern"],"pt":["Reorganizar o código Python para melhorar a legibilidade","Converter imports com alias para formas de importação padrão","Otimizar imports de módulos aninhados para melhor organização de código"],"ru":["Рефакторинг кода Python для улучшения читаемости","Преобразование импортов с псевдонимами в стандартизированные формы импорта","Оптимизация вложенных импортов модулей для лучшей организации кода"],"ar":["إعادة تنظيم رمز بايثون لتحسين القابلية للقراءة","تحويل الاستيرادات المسمّاة إلى أشكال استيراد معيارية","تحسين الاستيرادات الموديلية المتداخلة من أجل تنظيم أفضل للرمز"]},"limitations":{"en":["Excludes imports from __future__ and typing modules","Requires Python code analysis capabilities","Only optimizes import statements, not other code aspects"],"zh":["排除来自__future__和typing模块的导入","需要Python代码分析功能","仅优化导入语句，而不优化其他代码方面"],"ja":["__future__モジュールとtypingモジュールからのインポートを除外する","Pythonコード分析機能が必要","インポートステートメントのみを最適化し、他のコードの側面は最適化しない"],"ko":["__future__ 모듈과 typing 모듈로부터의导入을 제외함","Python 코드 분석 기능이 필요함","导入 문장만을 최적화하며, 다른 코드 측면은 최적화하지 않음"],"es":["Excluye importaciones de los módulos __future__ y typing","Requiere capacidades de análisis de código Python","Solo optimiza las declaraciones de importación, no otros aspectos del código"],"fr":["Exclut les importations des modules __future__ et typing","Nécessite des capacités d''analyse de code Python","N''optimise que les instructions d''importation, et non d''autres aspects du code"],"de":["Schließt Importe aus den Modulen __future__ und typing aus","Benötigt Python-Code-Analysefunktionen","Optimiert nur die Importanweisungen, nicht andere Code-Aspekte"],"pt":["Exclui imports dos módulos __future__ e typing","Requer capacidades de análise de código Python","Otimiza apenas declarações de importação, não outros aspectos do código"],"ru":["Исключает импорты из модулей __future__ и typing","Требует возможностей анализа кода Python","Оптимизирует только операторы импорта, не другие аспекты кода"],"ar":["استبعاد الاستيرادات من الموديلات __future__ و typing","يتطلب القدرات على تحليل رمز بايثون","يحسن فقط عبارات الاستيراد، وليس الجوانب الأخرى للرمز"]},"version":4},"contentHash":"60f90536632903a38bc46ec499b9220a48543a630e281624a358a263f9bdddae","qualityScore":40}');
