INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('causify-ai/helpers/coding.fix_from_imports', 'coding.fix_from_imports', 'causify-ai', 'helpers', 'community', 'coding.fix_from_imports causify-ai helpers community The coding.fix_from_imports skill optimizes Python imports by replacing statements like from X import Y with import X and updating uses of Y to X.Y, benefiting Python developers. coding.fix_from_imports 是一种 Python 代码优化工具，能够自动替换导入语句，提高代码的可读性和维护性 coding.fix_from_imports は Python コードを最適化するツールで、インポート文を自動的に置き換えてコードの可読性と保守性を向上させる coding.fix_from_imports는 Python 코드를 최적화하는 도구로, 임포트 문을 자동으로 교체하여 코드의 가독성과 유지 보수성을 향상시킵니다 Coding.fix_from_imports es una herramienta de desarrollo que reemplaza importaciones como ''from X import Y'' con ''import X'' y ''X.Y'', mejorando la legibilidad del código Coding.fix_from_imports est un outil de développement qui remplace des importations comme ''from X import Y'' par ''import X'' et ''X.Y'', améliorant la lisibilité du code Coding.fix_from_imports ist ein Entwicklungstool, das Importe wie ''from X import Y'' durch ''import X'' und ''X.Y'' ersetzt, um die Lesbarkeit des Codes zu verbessern coding.fix_from_imports é uma ferramenta que ajuda a reorganizar importações em projetos Python. Ele substitui declarações de importação por versões mais concisas. coding.fix_from_imports - это инструмент, помогающий реорганизовать импорты в проектах Python. Он заменяет операторы импорта на более краткие версии. coding.fix_from_imports هو أداة تساعد في إعادة تنظيم الاستيراد في مشاريع Python. يقوم باستبدال عبارات الاستيراد بنسخ أكثر إيجازًا. how to use coding.fix_from_imports coding.fix_from_imports setup guide python import optimization techniques coding.fix_from_imports vs importlib what is coding.fix_from_imports coding.fix_from_imports install python coding best practices import X vs from X import Y coding.fix_from_imports alternative python code readability Python 代码优化 导入语句优化 coding.fix_from_imports Python 开发工具 代码可读性 代码维护性 AIエージェント Replaces Python statements like from X import Y with import X and updates uses of Y to X.Y Converts aliased imports from X import Y as Z to import X and replaces uses of Z with X.Y Handles nested module imports from X.Y import Z by converting to import X.Y and replacing uses of Z with X.Y.Z Preserves specific imports like from __future__ import annotations and from typing import Any, Dict, List, Optional Standardizes import statements for improved code readability and maintainability coding.fix_from_imports is a Python import optimization technique that standardizes import statements for improved code readability and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sailscastshq/pellicule/pellicule', 'community', 'sailscastshq', 'pellicule', 'sailscastshq/pellicule', 'pellicule', 0, 0, 40, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:10.157Z', '63fccb591e4b57b034434d674c53ae2cc1bb1ce5afcbfd81aca4fa4d0a19a1fa', '{"id":"sailscastshq/pellicule/pellicule","name":"pellicule","description":{"en":"Pellicule is a skill for deterministic video rendering with Vue, ideal for developers creating videos, animations, or motion graphics. It provides a zero-config rendering solution.","zh":"Pellicule是一种用于Vue的确定性视频渲染工具，支持Nuxt、Quasar、Laravel等框架集成","ja":"PelliculeはVue用のデタラメ動画レンダリングツールで、Nuxt、Quasar、Laravelなどのフレームワークとの統合に対応","ko":"Pellicule은 Vue용 결정적 비디오 렌더링 도구로 Nuxt, Quasar, Laravel 등 프레임워크와의 통합을 지원","es":"Pellicule es una herramienta para renderizado de video determinístico con Vue. Permite crear videos, animaciones y gráficos de movimiento con facilidad","fr":"Pellicule est un outil pour le rendu de vidéo déterministe avec Vue. Il permet de créer des vidéos, des animations et des graphiques de mouvement avec facilité","de":"Pellicule ist ein Tool für deterministisches Video-Rendering mit Vue. Es ermöglicht die Erstellung von Videos, Animationen und Bewegungsgraphiken mit Leichtigkeit","pt":"O Pellicule é uma ferramenta para renderização de vídeo determinística com Vue, permitindo a criação de vídeos e animações personalizadas.","ru":"Pellicule - это инструмент для определённой видео-отрисовки с Vue, позволяющий создавать видео и анимации на заказ.","ar":"Pellicule هو أداة لتصيير الفيديو التحديد مع Vue، مما يسمح بإنشاء مقاطع فيديو ورسومات متحركة مخصصة."},"seo":{"title":{"en":"Pellicule: Deterministic Video Rendering Setup Guide | AI...","zh":"Pellicule Setup Guide: Vue视频渲染解决方案","ja":"Pellicule セットアップガイド: Vue用デタラメ動画レンダリングツール","ko":"Pellicule 설정 가이드: Vue용 결정적 비디오 렌더링 솔루션","es":"Pellicule: Guía de configuración para renderizado de vide...","fr":"Pellicule : Guide de configuration pour le rendu de vidéo...","de":"Pellicule: Einrichtungsleitfaden für deterministisches Vi...","pt":"Guia de Configuração do Pellicule para Renderização de Ví...","ru":"ИИ Агент Pellicule: Настройка Определённой Видео-Отрисовк...","ar":"دليل إعداد Pellicule لتصيير الفيديو التحديد مع Vue"},"description":{"en":"Unlock Vue video rendering capabilities with Pellicule. Learn how to install, setup, and integrate Pellicule with Nuxt, Quasar, and Laravel. Get started now!","zh":"使用Pellicule实现Vue视频渲染，了解如何集成Nuxt、Quasar、Laravel等框架","ja":"Pelliculeを使ってVue用のデタラメ動画レンダリングを実現する方法を学ぶ、Nuxt、Quasar、Laravelなどのフレームワークとの統合方法も","ko":"Pellicule을 사용하여 Vue용 결정적 비디오 렌더링을 구현하는 방법, Nuxt, Quasar, Laravel 등의 프레임워크 통합 방법","es":"Aprende a utilizar Pellicule para crear videos y animaciones con Vue. Descubre cómo integrar esta herramienta en tus proyectos","fr":"Découvrez comment utiliser Pellicule pour créer des vidéos et des animations avec Vue. Intégrez cette outil dans vos projets","de":"Erfahren Sie, wie Sie Pellicule verwenden können, um Videos und Animationen mit Vue zu erstellen. Integrieren Sie dieses Tool in Ihre Projekte","pt":"Aprenda a usar o Pellicule para criar vídeos, animações e gráficos de movimento com Vue, com recursos como macro defineVideoConfig","ru":"Откройте для себя Pellicule, ИИ Агент для создания видео, анимаций и графики движения с Vue, с функциями như macro defineVideoConfig","ar":"تعرف على Pellicule لإنشاء مقاطع فيديو ورسومات متحركة مع Vue، مع ميزات مثل макرو defineVideoConfig"},"definition":{"en":"Pellicule is a Vue-based skill for deterministic video rendering, similar to Remotion, offering features like defineVideoConfig macro and animation support.","zh":"Pellicule是一种用于Vue的确定性视频渲染工具","ja":"PelliculeはVue用のデタラメ動画レンダリングツール","ko":"Pellicule은 Vue용 결정적 비디오 렌더링 도구","es":"Pellicule es una herramienta de renderizado de video determinístico para Vue, similar a Remotion","fr":"Pellicule est un outil de rendu de vidéo déterministe pour Vue, similaire à Remotion","de":"Pellicule ist ein Tool für deterministisches Video-Rendering für Vue, ähnlich wie Remotion","pt":"O que é Pellicule? É uma ferramenta de renderização de vídeo determinística para Vue.","ru":"Что такое Pellicule? Это инструмент определённой видео-отрисовки для Vue.","ar":"ما هو Pellicule؟ إنه أداة تصيير فيديو تحديد مع Vue."},"features":{"en":["Supports installation and setup with popular frameworks like Nuxt, Quasar, and Laravel","Provides a defineVideoConfig macro for zero-config rendering","Offers animation support through rules/animations.md","Includes detailed explanations and code examples in individual rule files","Enables integration with various technologies through rules/getting-started.md"],"zh":["支持Nuxt、Quasar、Laravel等框架集成","提供defineVideoConfig宏用于零配置渲染","支持 animations 和 macros","使用Vue实现确定性视频渲染","提供Getting Started和规则文档"],"ja":["Nuxt、Quasar、Laravelなどのフレームワークとの統合に対応","defineVideoConfigマクロを使用した零コンフィグレーションレンダリング","animationsとmacrosをサポート","Vueを使用したデタラメ動画レンダリング","Getting Startedとルールのドキュメントを提供"],"ko":["Nuxt, Quasar, Laravel 등 프레임워크와의 통합 지원","defineVideoConfig 매크로를 사용한 제로 구성 렌더링","animations 및 macros 지원","Vue를 사용한 결정적 비디오 렌더링","Getting Started 및 규칙 문서 제공"],"es":["Renderizado de video determinístico con Vue","Integración con frameworks como Nuxt, Quasar y Laravel","Definición de configuraciones de video con macro defineVideoConfig","Soporte para animaciones y gráficos de movimiento","Compatibilidad con la creación de videos y animaciones con Vue"],"fr":["Rendu de vidéo déterministe avec Vue","Intégration avec des frameworks tels que Nuxt, Quasar et Laravel","Définition de configurations de vidéo avec macro defineVideoConfig","Prise en charge des animations et des graphiques de mouvement","Compatibilité avec la création de vidéos et d''animations avec Vue"],"de":["Deterministisches Video-Rendering mit Vue","Integration mit Frameworks wie Nuxt, Quasar und Laravel","Definition von Video-Konfigurationen mit Macro defineVideoConfig","Unterstützung für Animationen und Bewegungsgraphiken","Kompatibilität mit der Erstellung von Videos und Animationen mit Vue"],"pt":["Renderização de vídeo determinística com Vue","Macro defineVideoConfig para configuração zero","Integração com frameworks como Nuxt, Quasar e Laravel","Suporte a criação de animações e gráficos de movimento","Recursos de instalação e configuração personalizados"],"ru":["Определённая видео-отрисовка с Vue","Макро defineVideoConfig для нулевой конфигурации","Интеграция с фреймворками như Nuxt, Quasar и Laravel","Поддержка создания анимаций и графики движения","Возможности настройки установки и конфигурации"],"ar":["تصيير فيديو تحديد مع Vue","مكرو defineVideoConfig لتهيئة الصفر","التكامل مع الإطارات مثل Nuxt و Quasar و Laravel","دعم إنشاء الرسومات المتحركة ورسومات الحركة","امكانيات تخصيص التثبيت والتهيئة"]},"keywords":{"en":["how to use pellicule","what is pellicule","pellicule alternative","pellicule vs remotion","pellicule install","pellicule setup guide","vue video rendering","deterministic video rendering","pellicule integration with nuxt"],"zh":["Pellicule","Vue视频渲染","确定性视频渲染","Nuxt集成","Quasar集成","Laravel集成","Vue视频工具","AIエージェント","Vue开发"],"ja":["Pellicule","Vue動画レンダリング","デタラメ動画レンダリング","Nuxt統合","Quasar統合","Laravel統合","Vue動画ツール","AIエージェント","Vue開発"],"ko":["Pellicule","Vue 비디오 렌더링","결정적 비디오 렌더링","Nuxt 통합","Quasar 통합","Laravel 통합","Vue 비디오 도구","AI 에이전트","Vue 개발"],"es":["pellicule","renderizado de video determinístico","vue","nuxt","quasar","laravel","animaciones","gráficos de movimiento","herramientas de video","desarrollo web"],"fr":["pellicule","rendu de vidéo déterministe","vue","nuxt","quasar","laravel","animations","graphiques de mouvement","outils de vidéo","développement web"],"de":["pellicule","deterministisches video-rendering","vue","nuxt","quasar","laravel","animationen","bewegungsgraphiken","video-tools","webentwicklung"],"pt":["Pellicule","Renderização de vídeo determinística","Vue","Macro defineVideoConfig","Nuxt","Quasar","Laravel","Criação de animações","Gráficos de movimento"],"ru":["Pellicule","ИИ Агент","Определённая видео-отрисовка","Vue","Макро defineVideoConfig","Nuxt","Quasar","Laravel","Создание анимаций","Графика движения"],"ar":["Pellicule","أداة تصيير الفيديو","الفيديو التحديد","Vue","مكرو defineVideoConfig","Nuxt","Quasar","Laravel","إنشاء الرسومات المتحركة","رسومات الحركة"]}},"owner":"sailscastshq","repo":"pellicule","repoPath":"sailscastshq/pellicule","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"pellicule","description":"Create videos with Vue using Pellicule - a Vue-native video rendering library","tags":"pellicule, video, vue, animation, composition","bodyPreview":"## When to use\n\nUse this skill whenever you need to create videos, animations, or motion graphics using Vue. Pellicule is like Remotion but for Vue.\n\n## How to use\n\nRead individual rule files for detailed explanations and code examples:\n\n- [rules/getting-started.md](rules/getting-started.md) - Installation, setup, and framework integration (Nuxt, Quasar, Laravel, etc.)\n- [rules/macros.md](rules/macros.md) - defineVideoConfig macro for zero-config rendering\n- [rules/animations.md](rules/animation","body":"## When to use\n\nUse this skill whenever you need to create videos, animations, or motion graphics using Vue. Pellicule is like Remotion but for Vue.\n\n## How to use\n\nRead individual rule files for detailed explanations and code examples:\n\n- [rules/getting-started.md](rules/getting-started.md) - Installation, setup, and framework integration (Nuxt, Quasar, Laravel, etc.)\n- [rules/macros.md](rules/macros.md) - defineVideoConfig macro for zero-config rendering\n- [rules/animations.md](rules/animations.md) - Animation utilities: interpolate, sequence, easing\n- [rules/composables.md](rules/composables.md) - useFrame and useVideoConfig composables\n- [rules/sequences.md](rules/sequences.md) - Sequence component and useSequence for scene management\n- [rules/patterns.md](rules/patterns.md) - Common patterns: typewriter, staggered, scenes, loops\n- [rules/rendering.md](rules/rendering.md) - CLI options, BYOS mode, auto-detection, and rendering\n- [rules/styling.md](rules/styling.md) - CSS, fonts, and visual styling\n"},"lastSynced":"2026-03-08T02:00:10.157Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing deterministic video rendering with Vue","zh":"适合需要确定性视频渲染的前端代理，搭配 Vue","ja":"Vue を使用して決定的なビデオレンダリングが必要なフロントエンドエージェントに最適","ko":"Vue와 함께 결정적 비디오 렌더링이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan renderizado de video determinista con Vue","fr":"Parfait pour les agents Frontend nécessitant un rendu vidéo déterministe avec Vue","de":"Perfekt für Frontend-Agents, die deterministisches Video-Rendering mit Vue benötigen","pt":"Perfeito para Agentes Frontend que precisam de renderização de vídeo determinística com Vue","ru":"Идеально для агентов фронтенда, которым требуется детерминированная отрисовка видео с помощью Vue","ar":"مثالي لعميل واجهة المستخدم التي تحتاج إلى تقديم فيديو محدد مع Vue"},"recommendation":{"en":"Empowers agents to generate videos, animations, or motion graphics using Vue with zero-config rendering solutions, leveraging macros like defineVideoConfig for seamless integration with frameworks like Nuxt, Quasar, and Laravel","zh":"赋予代理生成视频、动画或运动图形的能力，使用 Vue 实现零配置渲染解决方案，利用 defineVideoConfig 等宏实现与 Nuxt、Quasar 和 Laravel 等框架的无缝集成","ja":"Vue を使用してビデオ、アニメーション、またはモーショングラフィックスを生成するエージェントを可能にし、defineVideoConfig などのマクロを使用して Nuxt、Quasar、Laravel などのフレームワークとのシームレスな統合を実現するためのゼロコンフィグレンダリングソリューション","ko":"Vue를 사용하여 비디오, 애니메이션 또는 모션 그래픽스를 생성하는 에이전트를 가능하게 하고, defineVideoConfig와 같은 매크로를 사용하여 Nuxt, Quasar, Laravelなどの 프레임워크와의 무결점 통합을 위한 제로 구성 렌더링 솔루션","es":"Habilita a los agentes a generar videos, animaciones o gráficos de movimiento utilizando Vue con soluciones de renderizado sin configuración, aprovechando macros como defineVideoConfig para una integración fluida con frameworks como Nuxt, Quasar y Laravel","fr":"Permet aux agents de générer des vidéos, des animations ou des graphiques de mouvement en utilisant Vue avec des solutions de rendu sans configuration, en exploitant des macros comme defineVideoConfig pour une intégration fluide avec des frameworks comme Nuxt, Quasar et Laravel","de":"Ermöglicht es Agenten, Videos, Animationen oder Bewegungsgrafiken mit Vue zu generieren, mit zero-config-Rendering-Lösungen, indem Makros wie defineVideoConfig für eine nahtlose Integration mit Frameworks wie Nuxt, Quasar und Laravel genutzt werden","pt":"Habilita os agentes a gerar vídeos, animações ou gráficos de movimento usando Vue com soluções de renderização zero-config, aproveitando macros como defineVideoConfig para integração transparente com frameworks como Nuxt, Quasar e Laravel","ru":"Наделяет агентов возможностью генерировать видео, анимации или графику движения с помощью Vue и решений для рендеринга с нулевой конфигурацией, используя макросы типа defineVideoConfig для бесшовной интеграции с фреймворками типа Nuxt, Quasar и Laravel","ar":"تمكين العميل من إنشاء مقاطع فيديو أو رسومات متحركة أو رسومات حركية باستخدام Vue مع حلول للتصيير بدون إعداد، واستخدام الماكرو مثل defineVideoConfig من أجل التكامل السلس مع الإطارات مثل Nuxt و Quasar و Laravel"},"useCases":{"en":["Rendering motion graphics for web applications","Creating animations for interactive user interfaces","Generating videos for marketing campaigns"],"zh":["为 Web 应用程序渲染运动图形","为交互式用户界面创建动画","为营销活动生成视频"],"ja":["Web アプリケーション用のモーショングラフィックスのレンダリング","インタラクティブなユーザーインターフェイス用のアニメーションの作成","マーケティングキャンペーン用のビデオの生成"],"ko":["웹 애플리케이션을 위한 모션 그래픽스의 렌더링","인터랙티브 사용자 인터페이스를 위한 애니메이션 생성","마케팅 캠페인을 위한 비디오 생성"],"es":["Renderizado de gráficos de movimiento para aplicaciones web","Creación de animaciones para interfaces de usuario interactivas","Generación de videos para campañas de marketing"],"fr":["Rendu de graphiques de mouvement pour des applications web","Création d''animations pour des interfaces utilisateur interactives","Génération de vidéos pour des campagnes de marketing"],"de":["Rendern von Bewegungsgrafiken für Webanwendungen","Erstellen von Animationen für interaktive Benutzeroberflächen","Generieren von Videos für Marketingkampagnen"],"pt":["Renderização de gráficos de movimento para aplicações web","Criação de animações para interfaces de usuário interativas","Geração de vídeos para campanhas de marketing"],"ru":["Отрисовка графики движения для веб-приложений","Создание анимаций для интерактивных пользовательских интерфейсов","Генерация видео для маркетинговых кампаний"],"ar":["تجسيد رسومات الحركة لتطبيقات الويب","إنشاء الرسومات المتحركة لواجهات المستخدم التفاعلية","إنشاء مقاطع الفيديو لحملات التسويق"]},"limitations":{"en":["Requires Vue framework integration","Limited to deterministic video rendering"],"zh":["需要 Vue 框架集成","仅限确定性视频渲染"],"ja":["Vue フレームワークの統合が必要","決定的なビデオレンダリングのみ"],"ko":["Vue 프레임워크 통합이 필요","결정적 비디오 렌더링만 가능"],"es":["Requiere integración con el framework Vue","Limitado al renderizado de video determinista"],"fr":["Nécessite une intégration avec le framework Vue","Limité au rendu vidéo déterministe"],"de":["Benötigt Integration mit dem Vue-Framework","Begrenzt auf deterministisches Video-Rendering"],"pt":["Requer integração com o framework Vue","Limitado à renderização de vídeo determinística"],"ru":["Требует интеграции с фреймворком Vue","Ограничен детерминированной отрисовкой видео"],"ar":["يتطلب تكامل مع إطار Vue","محدود بالتصيير الفيديو المحدد"]},"version":4},"contentHash":"63fccb591e4b57b034434d674c53ae2cc1bb1ce5afcbfd81aca4fa4d0a19a1fa","qualityScore":40}');
