INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sailscastshq/pellicule/pellicule', 'pellicule', 'sailscastshq', 'pellicule', 'community', 'pellicule sailscastshq pellicule community Pellicule is a skill for deterministic video rendering with Vue, ideal for developers creating videos, animations, or motion graphics. It provides a zero-config rendering solution. Pellicule是一种用于Vue的确定性视频渲染工具，支持Nuxt、Quasar、Laravel等框架集成 PelliculeはVue用のデタラメ動画レンダリングツールで、Nuxt、Quasar、Laravelなどのフレームワークとの統合に対応 Pellicule은 Vue용 결정적 비디오 렌더링 도구로 Nuxt, Quasar, Laravel 등 프레임워크와의 통합을 지원 Pellicule es una herramienta para renderizado de video determinístico con Vue. Permite crear videos, animaciones y gráficos de movimiento con facilidad Pellicule est un outil pour le rendu de vidéo déterministe avec Vue. Il permet de créer des vidéos, des animations et des graphiques de mouvement avec facilité Pellicule ist ein Tool für deterministisches Video-Rendering mit Vue. Es ermöglicht die Erstellung von Videos, Animationen und Bewegungsgraphiken mit Leichtigkeit O Pellicule é uma ferramenta para renderização de vídeo determinística com Vue, permitindo a criação de vídeos e animações personalizadas. Pellicule - это инструмент для определённой видео-отрисовки с Vue, позволяющий создавать видео и анимации на заказ. Pellicule هو أداة لتصيير الفيديو التحديد مع Vue، مما يسمح بإنشاء مقاطع فيديو ورسومات متحركة مخصصة. how to use pellicule what is pellicule pellicule alternative pellicule vs remotion pellicule install pellicule setup guide vue video rendering deterministic video rendering pellicule integration with nuxt Pellicule Vue视频渲染 确定性视频渲染 Nuxt集成 Quasar集成 Laravel集成 Vue视频工具 AIエージェント Vue开发 Supports installation and setup with popular frameworks like Nuxt, Quasar, and Laravel Provides a defineVideoConfig macro for zero-config rendering Offers animation support through rules/animations.md Includes detailed explanations and code examples in individual rule files Enables integration with various technologies through rules/getting-started.md Pellicule is a Vue-based skill for deterministic video rendering, similar to Remotion, offering features like defineVideoConfig macro and animation support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WayfinderFoundation/wayfinder-paths-sdk/simulation-dry-run', 'community', 'WayfinderFoundation', 'wayfinder-paths-sdk', 'WayfinderFoundation/wayfinder-paths-sdk', 'simulation-dry-run', 0, 0, 40, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:16.526Z', 'e75b29ac79335f031e7edeb0bb217beda8bbcc622f4d5696ee44bcdd73d99728', '{"id":"WayfinderFoundation/wayfinder-paths-sdk/simulation-dry-run","name":"simulation-dry-run","description":{"en":"The simulation-dry-run skill is designed for developers working on fund-moving scripts, strategy flows, and debugging approvals. It helps iterate on deposit, update, withdraw, and exit flows.","zh":"simulation-dry-run是一种用于调试和优化基金移动脚本的AI工具，支持快速迭代和验证","ja":"シミュレーション・ドライランは、資金移動スクリプトのデバッグと最適化を支援するAIエージェントです","ko":"simulation-dry-run은 펀드 이동 스크립트의 디버깅 및 최적화를 지원하는 AI 도구입니다","es":"Simulation-dry-run es una habilidad para depurar y optimizar scripts de fondos. Aprende a configurar y utilizar esta herramienta para mejorar tus flujos de estrategia","fr":"Simulation-dry-run est une compétence pour déboguer et optimiser les scripts de fonds. Découvrez comment configurer et utiliser cet outil pour améliorer vos flux de stratégie","de":"Simulation-dry-run ist eine Fähigkeit, um Fondsskripte zu debuggen und zu optimieren. Erfahren Sie, wie Sie diese Funktion konfigurieren und verwenden, um Ihre Strategieflüsse zu verbessern","pt":"O Simulation-Dry-Run é uma habilidade que permite testar e depurar scripts de fund-moving de forma eficiente","ru":"Simulation-Dry-Run - это навык, который позволяет тестировать и отлаживать скрипты передвижения средств эффективно с помощью ИИ Агентов","ar":"Simulation-Dry-Run هو مهارة يسمح باختبار وسحب خطأ سكريبتات تحريك الأموال بفعالية على منصة الإيمان الأوتوماتيكي"},"seo":{"title":{"en":"simulation-dry-run: Debugging and Testing Guide for AI Ag...","zh":"simulation-dry-run_SETUP指南","ja":"シミュレーション・ドライラン_Best Practices","ko":"simulation-dry-run구성 가이드","es":"Guía de configuración para simulation-dry-run: optimiza t...","fr":"Guide de mise en place pour simulation-dry-run : optimise...","de":"Einrichtungsleitfaden für simulation-dry-run: Optimieren ...","pt":"Guia de Configuração do Simulation-Dry-Run para Desenvolv...","ru":"Настройка Simulation-Dry-Run: Руководство для Разработчик...","ar":"دليل إعداد Simulation-Dry-Run لمنصة الإيمان الأوتوماتيكي"},"description":{"en":"Discover how simulation-dry-run streamlines fund-moving script development, debugging, and testing. Learn how to optimize your workflow with this essential A...","zh":"了解如何使用simulation-dry-run AIエージェント进行基金移动脚本调试和优化","ja":"シミュレーション・ドライランを使用して、資金移動スクリプトのデバッグと最適化を行う方法を学びます","ko":"simulation-dry-run을 사용하여 펀드 이동 스크립트 디버깅 및 최적화를 수행하는 방법","es":"Aprende a utilizar simulation-dry-run para depurar y optimizar tus scripts de fondos. Configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment utiliser simulation-dry-run pour déboguer et optimiser vos scripts de fonds. Configuration et meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie simulation-dry-run verwenden, um Ihre Fondsskripte zu debuggen und zu optimieren. Konfiguration und Best Practices für Entwickler","pt":"Aprenda a configurar o Simulation-Dry-Run para testar scripts de fund-moving e otimizar fluxos de depósito, atualização e saque","ru":"Узнайте, как настроить Simulation-Dry-Run для тестирования скриптов передвижения средств и оптимизации потоков депозита, обновления и вывода средств с помощь...","ar":"تعرف على كيفية إعداد Simulation-Dry-Run لاختبار سكريبتات تحريك الأموال وتحسين تدفقات الإيداع والتحديث والسحب على منصة الإيمان الأوتوماتيكي"},"definition":{"en":"simulation-dry-run is a skill used for debugging and testing fund-moving scripts, approvals, and strategy flows in AI agents.","zh":"simulation-dry-run是一种AI工具，用于模拟和调试基金移动脚本","ja":"シミュレーション・ドライランは、資金移動スクリプトの模擬とデバッグを行うAIエージェントです","ko":"simulation-dry-run은 펀드 이동 스크립트의 시뮬레이션 및 디버깅을 수행하는 AI 도구입니다","es":"Simulation-dry-run es una herramienta de simulación para depurar y optimizar scripts de fondos, como swaps, préstamos y puentes","fr":"Simulation-dry-run est un outil de simulation pour déboguer et optimiser les scripts de fonds, tels que les swaps, les prêts et les ponts","de":"Simulation-dry-run ist ein Simulationswerkzeug, um Fondsskripte zu debuggen und zu optimieren, wie z.B. Swaps, Kredite und Brücken","pt":"Simulation-Dry-Run é uma ferramenta de teste que simula a execução de scripts de fund-moving sem afetar os fundos reais","ru":"Simulation-Dry-Run - это инструмент тестирования, который симулирует выполнение скриптов передвижения средств без влияния на реальные средства с помощью ИИ Агентов","ar":"Simulation-Dry-Run هو أداة اختبار تمثل تشغيل سكريبتات تحريك الأموال دون التأثير على الأموال الفعلية على منصة الإيمان الأوتوماتيكي"},"features":{"en":["Supports debugging of approvals, units, calldata shapes, and gas issues","Enables iteration on strategy deposit, update, withdraw, and exit flows","Facilitates testing of multi-step sequencing in fund-moving scripts","Provides a fastest way to run a fork scenario using Config","Offers a scenario checklist for validation before live deployment"],"zh":["支持快速迭代和验证","用于调试和优化基金移动脚本","支持配置和快速运行fork场景","验证策略流程和multi-step sequencing"],"ja":["迅速なイテレーションと検証をサポート","資金移動スクリプトのデバッグと最適化に使用","設定とforkシナリオの迅速な実行をサポート","戦略フローとマルチステップシーケンシングの検証"],"ko":["빠른 반복과 검증 지원","펀드 이동 스크립트의 디버깅 및 최적화를 위해 사용","구성 및 포크 시나리오의 빠른 실행 지원","전략 흐름 및 멀티스텝 시퀀싱의 검증"],"es":["Depuración de aprobaciones y unidades","Optimización de calldata y gas","Secuenciación multietapa","Configuración de escenarios de fork","Validación de flujos de estrategia"],"fr":["Débogage des approbations et des unités","Optimisation des calldata et du gaz","Séquencement multétape","Configuration des scénarios de fork","Validation des flux de stratégie"],"de":["Debuggen von Genehmigungen und Einheiten","Optimierung von Calldata und Gas","Mehrstufige Sequenzierung","Konfiguration von Fork-Szenarien","Validierung von Strategieflüssen"],"pt":["Teste de scripts de fund-moving","Depuração de aprovações e unidades","Otimização de fluxos de depósito, atualização e saque","Análise de calldata shapes e gas issues","Suporte a multi-step sequencing"],"ru":["Тестирование скриптов передвижения средств","Отладка утверждений и единиц","Оптимизация потоков депозита, обновления и вывода средств","Анализ calldata shapes и проблем с газом","Поддержка многозадачной последовательности с помощью ИИ Агентов"],"ar":["اختبار سكريبتات تحريك الأموال","سحب خطأ للموافقات والوحدات","تحسين تدفقات الإيداع والتحديث والسحب","تحليل أشكال البيانات و مشاكل الغاز","دعم التسلسل المتعدد الخطوات على منصة الإيمان الأوتوماتيكي"]},"keywords":{"en":["how to use simulation-dry-run","simulation-dry-run setup guide","debugging fund-moving scripts","testing strategy flows","simulation-dry-run vs competitor","simulation-dry-run alternative","install simulation-dry-run","simulation-dry-run tutorial","optimizing workflow with simulation-dry-run"],"zh":["simulation-dry-run","AI工具","基金移动脚本","调试和优化","快速迭代","fork场景","策略流程"],"ja":["シミュレーション・ドライラン","AIエージェント","資金移動スクリプト","デバッグと最適化","迅速なイテレーション","forkシナリオ","戦略フロー"],"ko":["simulation-dry-run","AI 도구","펀드 이동 스크립트","디버깅 및 최적화","빠른 반복","포크 시나리오","전략 흐름"],"es":["simulation-dry-run","depuración de scripts de fondos","optimización de calldata","secuenciación multietapa","configuración de escenarios de fork","validación de flujos de estrategia","herramientas de desarrollo de AI","agentes de AI para desarrollo"],"fr":["simulation-dry-run","débogage de scripts de fonds","optimisation de calldata","séquencement multétape","configuration de scénarios de fork","validation de flux de stratégie","outils de développement d''IA","agents d''IA pour développement"],"de":["simulation-dry-run","Debuggen von Fondsskripten","Optimierung von Calldata","Mehrstufige Sequenzierung","Konfiguration von Fork-Szenarien","Validierung von Strategieflüssen","Entwicklungstools für KI","KI-Agents für Entwicklung"],"pt":["Simulation-Dry-Run","testar scripts de fund-moving","depurar aprovações","otimizar fluxos de depósito","análise de calldata shapes","gas issues","multi-step sequencing","desenvolvedores de blockchain"],"ru":["Simulation-Dry-Run","тестировать скрипты передвижения средств","отладка утверждений","оптимизировать потоки депозита","анализ calldata shapes","проблемы с газом","многозадачная последовательность","разработчики блокчейна","ИИ Агенты"],"ar":["Simulation-Dry-Run","اختبار سكريبتات تحريك الأموال","سحب خطأ للموافقات","تحسين تدفقات الإيداع","تحليل أشكال البيانات","مشاكل الغاز","التسلسل المتعدد الخطوات","مطورو البلوكشين","منصة الإيمان الأوتوماتيكي"]}},"owner":"WayfinderFoundation","repo":"wayfinder-paths-sdk","repoPath":"WayfinderFoundation/wayfinder-paths-sdk","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"simulation-dry-run","description":"How to run scenario tests against Gorlami fork RPCs (dry runs) before broadcasting live transactions. Covers config, seeding balances, runner flags, and safe script patterns.","tags":"simulation, dry-run, fork, gorlami, safety, strategies, scripts","bodyPreview":"## When to use\n\nUse this skill when you are:\n- Writing or modifying a **fund-moving** script (swaps, lending, bridging, looping)\n- Iterating on a strategy `deposit/update/withdraw/exit` flow\n- Debugging approvals, units, calldata shapes, gas issues, or multi-step sequencing\n\n## How to use\n\n- [rules/quickstart.md](rules/quickstart.md) - Config + fastest way to run a fork scenario\n- [rules/scenario-checklist.md](rules/scenario-checklist.md) - What to validate before “live”\n- [rules/script-pattern.","body":"## When to use\n\nUse this skill when you are:\n- Writing or modifying a **fund-moving** script (swaps, lending, bridging, looping)\n- Iterating on a strategy `deposit/update/withdraw/exit` flow\n- Debugging approvals, units, calldata shapes, gas issues, or multi-step sequencing\n\n## How to use\n\n- [rules/quickstart.md](rules/quickstart.md) - Config + fastest way to run a fork scenario\n- [rules/scenario-checklist.md](rules/scenario-checklist.md) - What to validate before “live”\n- [rules/script-pattern.md](rules/script-pattern.md) - Recommended CLI + `gorlami_fork(...)` pattern\n- [rules/gotchas.md](rules/gotchas.md) - Common fork-mode failures and mitigations\n\n\n"},"lastSynced":"2026-03-08T02:01:16.526Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Agents needing advanced simulation and testing of fund-moving scripts and strategy flows.","zh":"非常适合需要高级模拟和测试基金转移脚本和策略流的金融代理","ja":"財務エージェントが資金移動スクリプトと戦略フローの高度なシミュレーションとテストを必要とする場合に最適","ko":"자금 이동 스크립트와 전략 흐름의 고급 시뮬레이션 및 테스트가 필요한 금융 에이전트에 적합","es":"Perfecto para Agentes Financieros que necesitan simulación y prueba avanzadas de scripts de movimiento de fondos y flujos de estrategia.","fr":"Parfait pour les agents financiers ayant besoin de simulation et de test avancés de scripts de déplacement de fonds et de flux de stratégie.","de":"Perfekt für Finanzagenten, die erweiterte Simulation und Tests von Skripten zum Verschieben von Mitteln und Strategieflüssen benötigen.","pt":"Perfeito para Agentes Financeiros que precisam de simulação e teste avançados de scripts de movimentação de fundos e fluxos de estratégia.","ru":"Идеально подходит для финансовых агентов, которым необходимы продвинутая симуляция и тестирование сценариев передвижения средств и потоков стратегий.","ar":"مثالي للوكلاء الماليين الذين يحتاجون إلى محاكاة واختبار متقدمين لنصوص نقل الأموال ونسق الاستراتيجية."},"recommendation":{"en":"Empowers agents to iterate on deposit, update, withdraw, and exit flows using simulation-dry-run, streamlining the testing of swaps, lending, bridging, and looping scenarios with precise control over calldata shapes, gas issues, and multi-step sequencing.","zh":"赋予代理人使用模拟-干跑来迭代存款、更新、提款和退出流程的能力，简化了交换、借贷、桥接和循环场景的测试，具有对调用数据形状、gas 问题和多步骤序列的精确控制","ja":"エージェントがシミュレーション-ドライランを使用して預け入れ、更新、出金、終了フローの反復処理を行えるようにし、スワップ、レンディング、ブリッジング、ループシナリオのテストを簡素化し、コールデータの形状、ガス問題、複数ステップのシーケンシングに対する精密な制御を提供する","ko":"에이전트가 시뮬레이션-드라이런을 사용하여 예금, 업데이트, 출금 및 종료 흐름을 반복処理할 수 있도록 하여 스와프, 대출, 브리지, 루핑 시나리오의 테스트를簡素化하고 호출 데이터 형태, 가스 문제, 다단계 시퀀싱에 대한 정밀한 제어를 제공","es":"Habilita a los agentes a iterar sobre flujos de depósito, actualización, retiro y salida utilizando simulación-dry-run, lo que simplifica la prueba de escenarios de intercambio, préstamo, puente y bucle con un control preciso sobre las formas de calldata, problemas de gas y secuenciación multietapa.","fr":"Permet aux agents d''itérer sur les flux de dépôt, de mise à jour, de retrait et de sortie en utilisant la simulation-dry-run, ce qui simplifie le test de scénarios d''échange, de prêt, de pont et de boucle avec un contrôle précis sur les formes de calldata, les problèmes de gaz et la séquencing multétape.","de":"Ermöglicht es den Agenten, über Einzahlungs-, Update-, Auszahlungs- und Ausstiegsflüsse mit Hilfe von simulation-dry-run zu iterieren, wodurch das Testen von Szenarien für den Tausch, die Ausleihe, die Überbrückung und die Schleife mit präziser Kontrolle über calldata-Formen, Gasprobleme und Multi-Step-Sequenzen vereinfacht wird.","pt":"Habilita os agentes a iterar sobre fluxos de depósito, atualização, saque e saída usando simulação-dry-run, otimizando o teste de cenários de permuta, empréstimo, ponte e looping com controle preciso sobre formas de calldata, problemas de gás e sequenciamento em várias etapas.","ru":"Наделяет агентов возможностью итерировать депозитные, обновляющие, выводящие и выходящие потоки с помощью симуляции сухого запуска, оптимизируя тестирование сценариев свопов, кредитования, мостирования и циклического подключения с точным контролем над формами calldata, проблемами газа и многоступенчатой последовательностью.","ar":"تمكّن الوكلاء من التكرار على تدفقات الإيداع والتحديث والسحب والخروج باستخدام محاكاة خشک، وتبسيط اختبار سيناريوهات التبادل والقرض والجسور والتشابك مع التحكم الدقيق على أشكال calldata ومشاكل الغاز والترتيب المتعدد الخطوات."},"useCases":{"en":["Debugging approvals and units in complex financial transactions","Testing strategy flows for potential issues before live deployment","Simulating fund-moving scripts to identify and resolve gas issues or sequencing problems"],"zh":["调试复杂金融交易中的批准和单位","在实时部署之前测试策略流程中的潜在问题","模拟基金转移脚本以识别和解决gas问题或序列问题"],"ja":["複雑な金融取引における承認と単位のデバッグ","実時間デプロイ前に戦略フローの潜在的な問題をテストする","資金移動スクリプトをシミュレートしてガス問題またはシーケンシング問題を識別し解決する"],"ko":["복잡한 금융 거래中的 승인 및 단위 디버깅","실시간 배포 전략 흐름의 잠재적인 문제를 테스트","자금 이동 스크립트를 시뮬레이션하여 가스 문제 또는 시퀀싱 문제를 식별하고 해결"],"es":["Depuración de aprobaciones y unidades en transacciones financieras complejas","Prueba de flujos de estrategia para problemas potenciales antes de la implementación en vivo","Simulación de scripts de movimiento de fondos para identificar y resolver problemas de gas o secuenciación"],"fr":["Débogage des approbations et des unités dans les transactions financières complexes","Test des flux de stratégie pour les problèmes potentiels avant le déploiement en direct","Simulation de scripts de déplacement de fonds pour identifier et résoudre les problèmes de gaz ou de séquencing"],"de":["Fehlerbehebung bei Genehmigungen und Einheiten in komplexen Finanztransaktionen","Testen von Strategieflüssen auf potenzielle Probleme vor der Live-Implementierung","Simulieren von Skripten zum Verschieben von Mitteln, um Gasprobleme oder Sequenzierungsprobleme zu identifizieren und zu lösen"],"pt":["Depuração de aprovações e unidades em transações financeiras complexas","Teste de fluxos de estratégia para problemas potenciais antes do deploy ao vivo","Simulação de scripts de movimentação de fundos para identificar e resolver problemas de gás ou sequenciamento"],"ru":["Отладка одобрений и единиц в сложных финансовых транзакциях","Тестирование потоков стратегии на потенциальные проблемы до живого развертывания","Симуляция сценариев передвижения средств для выявления и решения проблем с газом или последовательностью"],"ar":["تصحيح أذونات والوحدات في المعاملات المالية المعقدة","اختبار تدفقات الاستراتيجية لمشاكل محتملة قبل النشر الحي","محاكاة نصوص نقل الأموال لتحديد ومعالجة مشاكل الغاز أو تسلسلي"]},"limitations":{"en":["Requires configuration and setup as outlined in rules/quickstart.md","Limited to simulation and testing, does not support live transactions"],"zh":["需要按照 rules/quickstart.md 中的说明进行配置和设置","仅限于模拟和测试，不支持实时交易"],"ja":["rules/quickstart.md に記載された設定と構成が必要","シミュレーションとテストのみに限定され、実時間取引はサポートされない"],"ko":["rules/quickstart.md에 설명된 대로 구성 및 설정이 필요","시뮬레이션 및 테스트만 제한되며 실시간 거래는 지원되지 않음"],"es":["Requiere configuración y configuración según lo descrito en rules/quickstart.md","Limitado a la simulación y la prueba, no admite transacciones en vivo"],"fr":["Nécessite une configuration et une installation comme indiqué dans rules/quickstart.md","Limité à la simulation et au test, ne prend pas en charge les transactions en direct"],"de":["Benötigt Konfiguration und Einrichtung wie in rules/quickstart.md beschrieben","Begrenzt auf Simulation und Test, unterstützt keine Live-Transaktionen"],"pt":["Requer configuração e instalação conforme delineado em rules/quickstart.md","Limitado à simulação e teste, não suporta transações ao vivo"],"ru":["Требует настройки и установки, как описано в rules/quickstart.md","Ограничен симуляцией и тестированием, не поддерживает живые транзакции"],"ar":["يتطلب التهيئة والتركيب كما هو محدد في rules/quickstart.md","محدود بمحاكاة الاختبار، لا يدعم المعاملات الحية"]},"version":4},"contentHash":"e75b29ac79335f031e7edeb0bb217beda8bbcc622f4d5696ee44bcdd73d99728","qualityScore":40}');
