INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WayfinderFoundation/wayfinder-paths-sdk/simulation-dry-run', 'simulation-dry-run', 'WayfinderFoundation', 'wayfinder-paths-sdk', 'community', 'simulation-dry-run WayfinderFoundation wayfinder-paths-sdk community The simulation-dry-run skill is designed for developers working on fund-moving scripts, strategy flows, and debugging approvals. It helps iterate on deposit, update, withdraw, and exit flows. simulation-dry-run是一种用于调试和优化基金移动脚本的AI工具，支持快速迭代和验证 シミュレーション・ドライランは、資金移動スクリプトのデバッグと最適化を支援するAIエージェントです simulation-dry-run은 펀드 이동 스크립트의 디버깅 및 최적화를 지원하는 AI 도구입니다 Simulation-dry-run es una habilidad para depurar y optimizar scripts de fondos. Aprende a configurar y utilizar esta herramienta para mejorar tus flujos de estrategia Simulation-dry-run est une compétence pour déboguer et optimiser les scripts de fonds. Découvrez comment configurer et utiliser cet outil pour améliorer vos flux de stratégie Simulation-dry-run ist eine Fähigkeit, um Fondsskripte zu debuggen und zu optimieren. Erfahren Sie, wie Sie diese Funktion konfigurieren und verwenden, um Ihre Strategieflüsse zu verbessern O Simulation-Dry-Run é uma habilidade que permite testar e depurar scripts de fund-moving de forma eficiente Simulation-Dry-Run - это навык, который позволяет тестировать и отлаживать скрипты передвижения средств эффективно с помощью ИИ Агентов Simulation-Dry-Run هو مهارة يسمح باختبار وسحب خطأ سكريبتات تحريك الأموال بفعالية على منصة الإيمان الأوتوماتيكي how to use simulation-dry-run simulation-dry-run setup guide debugging fund-moving scripts testing strategy flows simulation-dry-run vs competitor simulation-dry-run alternative install simulation-dry-run simulation-dry-run tutorial optimizing workflow with simulation-dry-run simulation-dry-run AI工具 基金移动脚本 调试和优化 快速迭代 fork场景 策略流程 Supports debugging of approvals, units, calldata shapes, and gas issues Enables iteration on strategy deposit, update, withdraw, and exit flows Facilitates testing of multi-step sequencing in fund-moving scripts Provides a fastest way to run a fork scenario using Config Offers a scenario checklist for validation before live deployment simulation-dry-run is a skill used for debugging and testing fund-moving scripts, approvals, and strategy flows in AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zainfathoni/kelas.rumahberbagi.com/ui-preview', 'community', 'zainfathoni', 'kelas.rumahberbagi.com', 'zainfathoni/kelas.rumahberbagi.com', 'ui-preview', 0, 0, 40, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:00.136Z', '9d3094414b3031d9d6e013dcab5b7aaf4e652ea42476ce6380193d05b780c2ce', '{"id":"zainfathoni/kelas.rumahberbagi.com/ui-preview","name":"ui-preview","description":{"en":"The ui-preview skill enables AI agents to preview local dev servers and storybooks using Chrome DevTools, allowing developers to test and debug their applications more efficiently. This skill benefits developers working with web applications","zh":"UI 预览技能允许您通过 Chrome DevTools 预览和分析本地开发服务器和 Storybook","ja":"UI プレビュースキルは、Chrome DevTools でローカル開発サーバーと Storybook をプレビューおよび分析する機能を提供します","ko":"UI预览 스킬은 크롬 개발자 도구로 로컬 개발 서버와 스토리북을 미리 보기 및 분석하는 기능을 제공합니다","es":"ui-preview es una habilidad que permite previsualizar servidores de desarrollo local y storybooks utilizando Chrome DevTools","fr":"ui-preview est une compétence qui permet de prévisualiser les serveurs de développement local et les storybooks à l''aide de Chrome DevTools","de":"ui-preview ist eine Fähigkeit, die die Vorschau lokaler Entwicklungsserver und Storybooks mithilfe von Chrome DevTools ermöglicht","pt":"O ui-preview é uma ferramenta para visualizar servidores de desenvolvimento local e storybooks com o Chrome DevTools, permitindo a navegação e captura de telas","ru":"ui-preview - это инструмент для предварительного просмотра локальных серверов разработки и storybooks с помощью Chrome DevTools, позволяющий навигацию и захват экрана","ar":"ui-preview أداة لمعاينة خوادم التطوير المحلية و storybooks باستخدام Chrome DevTools، مما يسمح بالملاحة والتحكم في الشاشة"},"seo":{"title":{"en":"ui-preview: Chrome DevTools Integration for AI Agents | A...","zh":"UI 预览技能：使用 Chrome DevTools