INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zainfathoni/kelas.rumahberbagi.com/ui-preview', 'ui-preview', 'zainfathoni', 'kelas.rumahberbagi.com', 'community', 'ui-preview zainfathoni kelas.rumahberbagi.com community The ui-preview skill enables AI agents to preview local dev servers and storybooks using Chrome DevTools, allowing developers to test and debug their applications more efficiently. This skill benefits developers working with web applications UI 预览技能允许您通过 Chrome DevTools 预览和分析本地开发服务器和 Storybook UI プレビュースキルは、Chrome DevTools でローカル開発サーバーと Storybook をプレビューおよび分析する機能を提供します UI预览 스킬은 크롬 개발자 도구로 로컬 개발 서버와 스토리북을 미리 보기 및 분석하는 기능을 제공합니다 ui-preview es una habilidad que permite previsualizar servidores de desarrollo local y storybooks utilizando Chrome DevTools ui-preview est une compétence qui permet de prévisualiser les serveurs de développement local et les storybooks à l''aide de Chrome DevTools ui-preview ist eine Fähigkeit, die die Vorschau lokaler Entwicklungsserver und Storybooks mithilfe von Chrome DevTools ermöglicht O ui-preview é uma ferramenta para visualizar servidores de desenvolvimento local e storybooks com o Chrome DevTools, permitindo a navegação e captura de telas ui-preview - это инструмент для предварительного просмотра локальных серверов разработки и storybooks с помощью Chrome DevTools, позволяющий навигацию и захват экрана ui-preview أداة لمعاينة خوادم التطوير المحلية و storybooks باستخدام Chrome DevTools، مما يسمح بالملاحة والتحكم في الشاشة how to use ui-preview ui-preview setup guide ui-preview alternative ui-preview vs puppeteer ui-preview install what is ui-preview ui-preview chrome devtools ui-preview ai agent skill ui-preview local dev server preview ui-preview storybook preview UI 预览技能 Chrome DevTools 本地开发服务器 Storybook navigate_page take_screenshot new_page press_key evaluate_script Navigate to a URL using the `navigate_page` command Capture a screenshot of the current page using `take_screenshot` Open a new browser tab with `new_page` Press keyboard keys like PageDown and End with `press_key` Run JavaScript on the page using `evaluate_script` ui-preview is a skill that allows AI agents to interact with web pages using Chrome DevTools, enabling features like navigation, screenshot capture, and JavaScript execution');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gohypergiant/standard-toolkit/accelint-ts-testing', 'community', 'gohypergiant', 'standard-toolkit', 'gohypergiant/standard-toolkit', 'accelint-ts-testing', 0, 0, 40, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:01.887Z', '3e01b52f50108c3caf57a7ca6ef19fdcf55a0393b1f1b1398df7287dedcdd41b', '{"id":"gohypergiant/standard-toolkit/accelint-ts-testing","name":"accelint-ts-testing","description":{"en":"The accelint-ts-testing skill provides a comprehensive set of patterns for writing effective Vitest tests, benefiting developers who need to ensure test organization and performance.","zh":"Accelint-ts-testing是一个用于Accelint系统家族的Web标准库，提供Vitest测试的最佳实践","ja":"Accelint-ts-testingはAccelintシステムファミリーのためのWeb標準ライブラリであり、Vitestテストのベストプラクティスを提供します","ko":"Accelint-ts-testing은 Accelint 시스템 패밀리의 Web 표준 라이브러리로 Vitest 테스트의 모범 사례를 제공합니다","es":"Accelint-ts-testing es la biblioteca estándar web para la familia de sistemas Accelint, que proporciona patrones para pruebas de Vitest mantenibles y efectivas","fr":"Accelint-ts-testing est la bibliothèque web standard pour la famille de systèmes Accelint, qui fournit des modèles pour des tests Vitest maintenables et efficaces","de":"Accelint-ts-testing ist die Web-Standardbibliothek für die Accelint-Systemfamilie, die Muster für wartbare und effektive Vitest-Tests bereitstellt","pt":"O Accelint-ts-testing é uma biblioteca de testes para a família de sistemas Accelint, fornecendo padrões abrangentes para testes Vitest mantidos e eficazes.","ru":"Accelint-ts-testing - это библиотека тестирования для семейства систем Accelint, обеспечивающая комплексные шаблоны для поддерживаемых и эффективных тестов Vitest с помощью ИИ Агентов","ar":"Accelint-ts-testing هي مكتبة اختبارات للعائلة من أنظمة Accelint، توفر أنماطا شاملة لاختبارات Vitest القابلة للصيانة والفعالة مع أدوات الذكاء الاصطناعي"},"seo":{"