INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gohypergiant/standard-toolkit/accelint-ts-testing', 'accelint-ts-testing', 'gohypergiant', 'standard-toolkit', 'community', 'accelint-ts-testing gohypergiant standard-toolkit community The accelint-ts-testing skill provides a comprehensive set of patterns for writing effective Vitest tests, benefiting developers who need to ensure test organization and performance. Accelint-ts-testing是一个用于Accelint系统家族的Web标准库，提供Vitest测试的最佳实践 Accelint-ts-testingはAccelintシステムファミリーのためのWeb標準ライブラリであり、Vitestテストのベストプラクティスを提供します Accelint-ts-testing은 Accelint 시스템 패밀리의 Web 표준 라이브러리로 Vitest 테스트의 모범 사례를 제공합니다 Accelint-ts-testing es la biblioteca estándar web para la familia de sistemas Accelint, que proporciona patrones para pruebas de Vitest mantenibles y efectivas Accelint-ts-testing est la bibliothèque web standard pour la famille de systèmes Accelint, qui fournit des modèles pour des tests Vitest maintenables et efficaces Accelint-ts-testing ist die Web-Standardbibliothek für die Accelint-Systemfamilie, die Muster für wartbare und effektive Vitest-Tests bereitstellt O Accelint-ts-testing é uma biblioteca de testes para a família de sistemas Accelint, fornecendo padrões abrangentes para testes Vitest mantidos e eficazes. Accelint-ts-testing - это библиотека тестирования для семейства систем Accelint, обеспечивающая комплексные шаблоны для поддерживаемых и эффективных тестов Vitest с помощью ИИ Агентов Accelint-ts-testing هي مكتبة اختبارات للعائلة من أنظمة Accelint، توفر أنماطا شاملة لاختبارات Vitest القابلة للصيانة والفعالة مع أدوات الذكاء الاصطناعي how to use accelint-ts-testing what is accelint-ts-testing accelint-ts-testing vs Jest accelint-ts-testing install guide Vitest best practices for AI agents accelint-ts-testing setup for developers accelint-ts-testing alternative testing frameworks accelint-ts-testing tutorial for beginners accelint-ts-testing and Vitest integration Accelint-ts-testing Vitest测试 AI工具 Web标准库 测试组织 性能优化 NEVER跳过全局模拟清理配置 Provides Vitest best practices for writing maintainable tests Guides on proper global mock cleanup configuration to avoid non-deterministic failures Offers expert-level guidance on test organization and clarity Helps prevent ''action at a distance'' failures by ensuring proper mock cleanup Supports effective test performance optimization accelint-ts-testing is a web standard library for the Accelint family of systems, focusing on expert-level guidance for test organization, clarity, and performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Meme-Lords/granhackaria-run1/gsd:workflow:resume-project', 'community', 'Meme-Lords', 'granhackaria-run1', 'Meme-Lords/granhackaria-run1', 'gsd:workflow:resume-project', 0, 0, 40, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:13.268Z', 'c43efce53d13db5354433eda9002770d9abb5b859b751b8becfcd0401de47c08', '{"id":"Meme-Lords/granhackaria-run1/gsd:workflow:resume-project","name":"gsd:workflow:resume-project","description":{"en":"The gsd:workflow:resume-project skill allows developers to resume paused or interrupted projects by loading saved state, restoring progress, and verifying readiness. This workflow benefits developers who need to pick up where they left off.","zh":"gsd:workflow:resume-project工作流用于恢复暂停或中断的项目，包括加载保存的状态、恢复进度、验证就绪性和继续工作","ja":"gsd:workflow:resume-projectワークフローは、一時停止または中断されたプロジェクトを再開するために使用され、保存された状態の読み込み、進度の復元、準備性の検証、作業の続行などを含みます","ko":"gsd:workflow:resume-project 워크플로는 일시 중지 또는 중단된 프로젝트를 재개하는 데 사용되며 저장된 상태 로드, 진행 상황 복원, 준비 상태 확인 및 작업 계속 등","es":"El flujo de trabajo gsd:workflow:resume-project permite reanudar proyectos pausados, restaurando el estado y progreso guardados. Aprende a utilizarlo para continuar tu trabajo de manera efectiva","fr":"Le flux de travail gsd:workflow:resume-project permet de reprendre les projets interrompus, en restaurant l''état et les progrès enregistrés. Découvrez comment l''utiliser pour poursuivre votre travail de manière efficace","de":"Der Workflow gsd:workflow:resume-project ermöglicht die Wiederaufnahme pausierter Projekte, indem er den gespeicherten Zustand und Fortschritt wiederherstellt. Erfahren Sie, wie Sie ihn verwenden können, um Ihre Arbeit effektiv fortzusetzen","pt":"O gsd:workflow:resume-project é uma workflow para retomar projetos pausados ou interrompidos. Carregue o estado salvo e restaure o progresso.","ru":"ИИ Агенты: gsd:workflow:resume-project - это рабочий процесс для возобновления приостановленных или прерванных проектов. Загрузите сохраненное состояние и восстановите прогресс.","ar":"أدوات الذكاء الاصطناعي: gsd:workflow:resume-project هو سير عمل لإعادة تشغيل المشاريع المتوقفة أو المنقطعة. حمل الحالة المحفوظة واستعد التقدم."},"seo":{"title":{"en":"gsd:workflow:resume-project: Project Resume Setup Guide |...","zh":"AIエージェント项目恢复工作流程设置指南","ja":"AIエージェントを使用したプロジェクト再開ワークフローのベストプラクティス","ko":"AI 에이전트 프로젝트 재개 워크플로우 구축 가이드","es":"Guía de configuración para reanudar proyectos con gsd:wor...","fr":"Guide de mise en route pour reprendre les projets avec gs...","de":"Einrichtungsanleitung für die Wiederaufnahme von Projekte...","pt":"Guia de Retomada de Projeto: gsd:workflow:resume-project","ru":"ИИ Агенты: Руководство по возобновлению проекта gsd:workf...","ar":"إعادة تشغيل المشروع: دليل gsd:workflow:resume-project لأد..."},"description":{"en":"Learn how to resume paused projects with gsd:workflow:resume-project. Discover the 4-phase workflow to load saved state, restore progress, and continue work ...","zh":"了解如何使用gsd:workflow:resume-project工作流恢复暂停或中断的项目，包括加载保存的状态、恢复进度和验证就绪性","ja":"gsd:workflow:resume-projectワークフローを使用して一時停止または中断されたプロジェクトを再開する方法について、保存された状態の読み込み、進度の復元、準備性の検証などを学びます","ko":"gsd:workflow:resume-project 워크플로를 사용하여 일시 중지 또는 중단된 프로젝트를 재개하는 방법에 대해 알아보세요. 저장된 상태 로드, 진행 상황 복원 및 준비 상태 확인 등","es":"Aprende a reanudar proyectos pausados con gsd:workflow:resume-project, una herramienta de AI Agent para restaurar el estado del proyecto y continuar el trabajo","fr":"Découvrez comment reprendre les projets interrompus avec gsd:workflow:resume-project, un outil d''AI Agent pour restaurer l''état du projet et poursuivre le tr...","de":"Erfahren Sie, wie Sie mit gsd:workflow:resume-project, einem AI-Tool, pausierte Projekte wieder aufnehmen und den Arbeitsfortschritt wiederherstellen können","pt":"Aprenda a retomar projetos pausados com o gsd:workflow:resume-project. Carregue o estado salvo, restaure o progresso e verifique a prontidão.","ru":"Узнайте, как возобновить приостановленные проекты с помощью gsd:workflow:resume-project. Загрузите сохраненное состояние, восстановите прогресс и проверьте г...","ar":"تعلم كيفية استئناف المشاريع المتوقفة مع gsd:workflow:resume-project. حمل الحالة المحفوظة و استعد التقدم و تحقق من الجاهزية."},"definition":{"en":"gsd:workflow:resume-project is a workflow for resuming a paused or interrupted project, consisting of 4 phases: load saved state, restore progress, verify readiness, and continue work.","zh":"gsd:workflow:resume-project是用于恢复暂停或中断的项目的工作流","ja":"gsd:workflow:resume-projectは、一時停止または中断されたプロジェクトを再開するためのワークフローです","ko":"gsd:workflow:resume-project는 일시 중지 또는 중단된 프로젝트를 재개하는 워크플로입니다","es":"gsd:workflow:resume-project es un flujo de trabajo de AI Agent que permite reanudar proyectos pausados, restaurando el estado y progreso guardados","fr":"gsd:workflow:resume-project est un flux de travail d''AI Agent qui permet de reprendre les projets interrompus, en restaurant l''état et les progrès enregistrés","de":"gsd:workflow:resume-project ist ein Workflow von AI-Tool, der die Wiederaufnahme pausierter Projekte ermöglicht, indem er den gespeicherten Zustand und Fortschritt wiederherstellt","pt":"O gsd:workflow:resume-project é uma workflow que permite retomar projetos pausados ou interrompidos.","ru":"ИИ Агенты: gsd:workflow:resume-project - это рабочий процесс, который позволяет возобновить приостановленные или прерванные проекты.","ar":"أدوات الذكاء الاصطناعي: gsd:workflow:resume-project هو سير عمل يسمح بإعادة تشغيل المشاريع المتوقفة أو المنقطعة."},"features":{"en":["Loads saved state to resume project from where it was left off","Restores progress to ensure continuity","Verifies readiness to ensure project is ready to continue","Continues work seamlessly after resuming the project","Supports 4-phase workflow for resuming paused or interrupted projects","Enables developers to pick up where they left off"],"zh":["加载保存的状态","恢复进度","验证就绪性","继续工作"],"ja":["保存された状態の読み込み","進度の復元","準備性の検証","作業の続行"],"ko":["저장된 상태 로드","진행 상황 복원","준비 상태 확인","작업 계속"],"es":["Carga de estado guardado","Restauración de progreso","Verificación de preparación","Continuación del trabajo","Compatibilidad con proyectos pausados","Restauración de estado del proyecto"],"fr":["Chargement de l''état enregistré","Restauration des progrès","Vérification de la préparation","Poursuite du travail","Compatibilité avec les projets interrompus","Restauration de l''état du projet"],"de":["Laden des gespeicherten Zustands","Wiederherstellung des Fortschritts","Überprüfung der Bereitschaft","Fortsetzung der Arbeit","Kompatibilität mit pausierten Projekten","Wiederherstellung des Projektzustands"],"pt":["Carregue o estado salvo","Restaure o progresso","Verifique a prontidão","Continue o trabalho"],"ru":["Загрузите сохраненное состояние","Восстановите прогресс","Проверьте готовность","Продолжите работу"],"ar":["حمل الحالة المحفوظة","استعد التقدم","تحقق من الجاهزية","استمر في العمل"]},"keywords":{"en":["how to use gsd:workflow:resume-project","gsd:workflow:resume-project setup guide","gsd:workflow:resume-project alternative","gsd:workflow:resume-project vs other workflows","what is gsd:workflow:resume-project","gsd:workflow:resume-project install","project resume workflow","gsd:workflow:resume-project tutorial","resuming paused projects with gsd:workflow:resume-project"],"zh":["AIエージェント项目恢复","gsd:workflow:resume-project","项目恢复工作流","加载保存的状态","恢复进度","验证就绪性","继续工作","项目管理"],"ja":["AIエージェントを使用したプロジェクト再開","gsd:workflow:resume-project","プロジェクト再開ワークフロー","保存された状態の読み込み","進度の復元","準備性の検証","作業の続行","プロジェクト管理"],"ko":["AI 에이전트 프로젝트 재개","gsd:workflow:resume-project","프로젝트 재개 워크플로","저장된 상태 로드","진행 상황 복원","준비 상태 확인","작업 계속","프로젝트 관리"],"es":["gsd:workflow:resume-project","AI Agent","reanudar proyectos","restaurar estado del proyecto","continuar trabajo","proyectos pausados","flujo de trabajo","herramientas de desarrollo","tecnologías de AI"],"fr":["gsd:workflow:resume-project","AI Agent","reprendre les projets","restaurer l''état du projet","poursuivre le travail","projets interrompus","flux de travail","outils de développement","technologies d''IA"],"de":["gsd:workflow:resume-project","AI-Tool","pausierte Projekte wieder aufnehmen","Projektzustand wiederherstellen","Arbeit fortsetzen","pausierte Projekte","Workflow","Entwicklungstools","KI-Technologien"],"pt":["gsd:workflow:resume-project","retomar projeto","carregar estado salvo","restaurar progresso","verificar prontidão","continue trabalho","desenvolvimento de software"],"ru":["ИИ Агенты","gsd:workflow:resume-project","возобновить проект","загрузить сохраненное состояние","восстановить прогресс","проверить готовность","продолжить работу","разработка программного обеспечения"],"ar":["أدوات الذكاء الاصطناعي","gsd:workflow:resume-project","إعادة تشغيل المشروع","حمل الحالة المحفوظة","استعد التقدم","تحقق من الجاهزية","استمر في العمل","تطوير البرمجيات"]}},"owner":"Meme-Lords","repo":"granhackaria-run1","repoPath":"Meme-Lords/granhackaria-run1","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.331Z","topics":[],"category":"community","skillMd":{"name":"gsd:workflow:resume-project","description":"Workflow for resuming a paused project","version":"1.0.0","bodyPreview":"# GSD Resume Project Workflow\n\nWorkflow for resuming a paused or interrupted project.\n\n## When to Use\n\n- Continuing after pause\n- Restoring project state\n- Picking up where left off\n\n## Phases\n\n1. Load saved state\n2. Restore progress\n3. Verify readiness\n4. Continue work\n\n## Success Criteria\n\nProject resumed from saved state.","body":"# GSD Resume Project Workflow\n\nWorkflow for resuming a paused or interrupted project.\n\n## When to Use\n\n- Continuing after pause\n- Restoring project state\n- Picking up where left off\n\n## Phases\n\n1. Load saved state\n2. Restore progress\n3. Verify readiness\n4. Continue work\n\n## Success Criteria\n\nProject resumed from saved state.\n"},"lastSynced":"2026-03-08T02:03:13.268Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring efficient project state management and continuity.","zh":"适用于需要高效项目状态管理和连续性的开发代理。","ja":"開発エージェントがプロジェクト状態を効率的に管理し、継続性を保つ必要がある場合に最適です。","ko":"개발 에이전트가 프로젝트 상태를 효율적으로 관리하고 연속성을 유지해야 하는 경우에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren una gestión eficiente del estado del proyecto y la continuidad.","fr":"Idéal pour les agents de développement nécessitant une gestion efficace de l''état du projet et la continuité.","de":"Ideal für Entwicklungssagenten, die eine effiziente Projektzustandsverwaltung und Kontinuität benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem gerenciamento eficiente do estado do projeto e continuidade.","ru":"Идеально для агентов разработки, требующих эффективного управления состоянием проекта и непрерывности.","ar":"مثالي لعميل التطوير الذي يتطلب إدارة فعالة لحالة المشروع و الاستمرارية."},"recommendation":{"en":"Empowers agents to seamlessly resume paused projects by loading saved states, restoring progress, and verifying readiness, leveraging workflow phases and success criteria to ensure project continuity and integrity.","zh":"赋予代理人在加载保存的状态、恢复进度并验证就绪情况的同时无缝地恢复暂停的项目的能力，利用工作流阶段和成功标准以确保项目的连续性和完整性。","ja":"ワークフロー段階と成功基準を利用してプロジェクトの連続性と完全性を確保することで、保存された状態をロードし、進度を回復し、準備完了を検証しながら、一時停止したプロジェクトを無停止で再開できる機能をエージェントに付与します。","ko":"저장된 상태를 로드하고, 진행 상황을 복원하며, 준비 완료를 검증하는 동시에 작업 흐름 단계와 성공 기준을 활용하여 프로젝트의 연속성과 完整性을 보장하여暂停된 프로젝트를 무중단으로 재개할 수 있는 기능을 에이전트에게 부여합니다.","es":"Habilita a los agentes a reanudar proyectos pausados de forma transparente cargando estados guardados, restaurando el progreso y verificando la preparación, aprovechando las fases del flujo de trabajo y los criterios de éxito para garantizar la continuidad e integridad del proyecto.","fr":"Permet aux agents de reprendre des projets suspendus de manière transparente en chargeant les états sauvegardés, en restaurant les progrès et en vérifiant la préparation, en exploitant les phases du workflow et les critères de réussite pour assurer la continuité et l''intégrité du projet.","de":"Ermöglicht es Agenten, pausierte Projekte nahtlos wieder aufzunehmen, indem sie gespeicherte Zustände laden, den Fortschritt wiederherstellen und die Bereitschaft überprüfen, wobei sie Phasen des Workflows und Erfolgskriterien nutzen, um die Kontinuität und Integrität des Projekts zu gewährleisten.","pt":"Habilita os agentes a retomar projetos pausados de forma transparente, carregando estados salvos, restaurando o progresso e verificando a prontidão, aproveitando fases de fluxo de trabalho e critérios de sucesso para garantir a continuidade e integridade do projeto.","ru":"Наделяет агентов возможностью беспрепятственно возобновлять приостановленные проекты, загружая сохраненные состояния, восстанавливая прогресс и проверяя готовность, используя фазы рабочего процесса и критерии успеха для обеспечения непрерывности и целостности проекта.","ar":"تمكّن الوكيل من استئناف المشاريع الموقفة بسلاسة عن طريق تحميل الحالات المحفوظة و استعادة التقدم و التحقق من الجاهزية، مستفيدا من مراحل تدفق العمل و معايير النجاح لضمان استمرارية المشروع و سلامته."},"useCases":{"en":["Restoring project state after interruptions","Continuing development from a saved point","Verifying project readiness before deployment"],"zh":["在中断后恢复项目状态","从保存点继续开发","在部署前验证项目就绪情况"],"ja":["中断後のプロジェクト状態を回復する","保存されたポイントから開発を続ける","デプロイ前にプロジェクトの準備完了を検証する"],"ko":["중단 후 프로젝트 상태를 복원하는 것","저장된 지점에서 개발을 계속하는 것","배포 전에 프로젝트 준비 완료를 검증하는 것"],"es":["Restaurar el estado del proyecto después de interrupciones","Continuar el desarrollo a partir de un punto guardado","Verificar la preparación del proyecto antes de la implementación"],"fr":["Rétablir l''état du projet après des interruptions","Continuer le développement à partir d''un point sauvegardé","Vérifier la préparation du projet avant le déploiement"],"de":["Den Projektzustand nach Unterbrechungen wiederherstellen","Die Entwicklung von einem gespeicherten Punkt aus fortsetzen","Die Bereitschaft des Projekts vor der Bereitstellung überprüfen"],"pt":["Restaurar estado do projeto após interrupções","Continuar desenvolvimento a partir de um ponto salvo","Verificar prontidão do projeto antes da implantação"],"ru":["Восстановление состояния проекта после прерываний","Продолжение разработки с сохраненной точки","Проверка готовности проекта перед развертыванием"],"ar":["استعادة حالة المشروع بعد الانقطاعات","استمرار التطوير من نقطة محفوظة","التحقق من جاهزية المشروع قبل النشر"]},"limitations":{"en":["Requires saved project state","Dependent on project type and compatibility"],"zh":["需要保存的项目状态","依赖于项目类型和兼容性"],"ja":["保存されたプロジェクト状態が必要","プロジェクトの種類や互換性に依存する"],"ko":["저장된 프로젝트 상태가 필요","프로젝트 유형 및 호환성에 의존"],"es":["Requiere un estado de proyecto guardado","Depende del tipo de proyecto y la compatibilidad"],"fr":["Nécessite un état de projet sauvegardé","Dépend du type de projet et de la compatibilité"],"de":["Benötigt einen gespeicherten Projektzustand","Hängt vom Projekttyp und der Kompatibilität ab"],"pt":["Exige estado do projeto salvo","Dependente do tipo de projeto e compatibilidade"],"ru":["Требует сохраненного состояния проекта","Зависит от типа проекта и совместимости"],"ar":["يتطلب حالة مشروع محفوظة","يعتمد على نوع المشروع و التوافق"]},"version":4},"contentHash":"c43efce53d13db5354433eda9002770d9abb5b859b751b8becfcd0401de47c08","qualityScore":40}');
