INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Meme-Lords/granhackaria-run1/gsd:workflow:resume-project', 'gsd:workflow:resume-project', 'Meme-Lords', 'granhackaria-run1', 'community', 'gsd:workflow:resume-project Meme-Lords granhackaria-run1 community The gsd:workflow:resume-project skill allows developers to resume paused or interrupted projects by loading saved state, restoring progress, and verifying readiness. This workflow benefits developers who need to pick up where they left off. gsd:workflow:resume-project工作流用于恢复暂停或中断的项目，包括加载保存的状态、恢复进度、验证就绪性和继续工作 gsd:workflow:resume-projectワークフローは、一時停止または中断されたプロジェクトを再開するために使用され、保存された状態の読み込み、進度の復元、準備性の検証、作業の続行などを含みます gsd:workflow:resume-project 워크플로는 일시 중지 또는 중단된 프로젝트를 재개하는 데 사용되며 저장된 상태 로드, 진행 상황 복원, 준비 상태 확인 및 작업 계속 등 El flujo de trabajo gsd:workflow:resume-project permite reanudar proyectos pausados, restaurando el estado y progreso guardados. Aprende a utilizarlo para continuar tu trabajo de manera efectiva Le flux de travail gsd:workflow:resume-project permet de reprendre les projets interrompus, en restaurant l''état et les progrès enregistrés. Découvrez comment l''utiliser pour poursuivre votre travail de manière efficace Der Workflow gsd:workflow:resume-project ermöglicht die Wiederaufnahme pausierter Projekte, indem er den gespeicherten Zustand und Fortschritt wiederherstellt. Erfahren Sie, wie Sie ihn verwenden können, um Ihre Arbeit effektiv fortzusetzen O gsd:workflow:resume-project é uma workflow para retomar projetos pausados ou interrompidos. Carregue o estado salvo e restaure o progresso. ИИ Агенты: gsd:workflow:resume-project - это рабочий процесс для возобновления приостановленных или прерванных проектов. Загрузите сохраненное состояние и восстановите прогресс. أدوات الذكاء الاصطناعي: gsd:workflow:resume-project هو سير عمل لإعادة تشغيل المشاريع المتوقفة أو المنقطعة. حمل الحالة المحفوظة واستعد التقدم. how to use gsd:workflow:resume-project gsd:workflow:resume-project setup guide gsd:workflow:resume-project alternative gsd:workflow:resume-project vs other workflows what is gsd:workflow:resume-project gsd:workflow:resume-project install project resume workflow gsd:workflow:resume-project tutorial resuming paused projects with gsd:workflow:resume-project AIエージェント项目恢复 gsd:workflow:resume-project 项目恢复工作流 加载保存的状态 恢复进度 验证就绪性 继续工作 项目管理 Loads saved state to resume project from where it was left off Restores progress to ensure continuity Verifies readiness to ensure project is ready to continue Continues work seamlessly after resuming the project Supports 4-phase workflow for resuming paused or interrupted projects Enables developers to pick up where they left off gsd:workflow:resume-project is a workflow for resuming a paused or interrupted project, consisting of 4 phases: load saved state, restore progress, verify readiness, and continue work.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CodeWithKarol/scale-sail-agency/marketing-psychology', 'community', 'CodeWithKarol', 'scale-sail-agency', 'CodeWithKarol/scale-sail-agency', 'marketing-psychology', 0, 0, 40, '2026-03-08T01:57:15.336Z', '2026-03-08T02:03:18.463Z', 'b811d66a2a048317145cae641df33e484f47142bd6f9c689f562b79f8c3f4c45', '{"id":"CodeWithKarol/scale-sail-agency/marketing-psychology","name":"marketing-psychology","description":{"en":"The marketing-psychology skill helps users understand why people buy and how to influence behavior ethically. It provides expert guidance on applying psychological principles and mental models to marketing decisions.","zh":"营销心理学是应用心理学原理和心理模型来提高营销效果，包括产品营销背景和行为影响等","ja":"マーケティング心理学は、心理学の原理と心理モデルを適用して効果的なマーケティングを行う技術です","ko":"마케팅 심리학은 심리학의 원리를 적용하여 제품 마케팅 컨텍스트와 행동 영향을 이해하고 더好的 마케팅 결정을 내리기 위한 기술입니다","es":"Aplicación de principios psicológicos y modelos mentales en marketing para comprender por qué la gente compra y cómo influir en su comportamiento de manera ética","fr":"Application des principes psychologiques et des modèles mentaux pour comprendre les motivations d''achat et influencer le comportement de manière éthique","de":"Anwendung psychologischer Prinzipien und mentaler Modelle, um zu verstehen, warum Menschen kaufen und wie man ihr Verhalten ethisch beeinflussen kann","pt":"A psicologia de marketing é uma habilidade que ajuda a entender por que as pessoas compram e como influenciar comportamentos de forma ética","ru":"Психология маркетинга - это навык, который помогает понять, почему люди покупают и как этично влиять на их поведение","ar":"علم النفس التسويقي هو مهارة تساعد على فهم سبب شراء الناس و كيفية التأثير على السلوكيات بطرق أخلاقية"},"seo":{"title":{"en":"Marketing-Psychology: Ethical Influence Setup Guide | AI ...","zh":"营销心理学设置指南 - Marketing Psychology Setup Guide","ja":"マーケティング心理学のベストプラクティス - Marketing Psychology Best Practices","ko":"마케팅 심리학 구축 가이드 - Marketing Psychology Setup Guide","es":"Guía de configuración de marketing-psychology para agente...","fr":"Guide de démarrage pour l''outil de marketing-psychology","de":"Einrichtungsleitfaden für Marketing-Psychologie-Tools","pt":"Guia de Configuração de Psicologia de Marketing com Ferra...","ru":"Настройка ИИ Агентов для Психологии Маркетинга","ar":"دليل إعداد علم النفس التسويقي مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of marketing psychology and mental models to drive sales. Learn how to apply psychological principles to influence behavior ethically and ma...","zh":"了解如何应用心理学原理和心理模型来提高营销效果，包括产品营销背景和行为影响等","ja":"マーケティング心理学の基礎を学び、心理模型を適用して効果的なマーケティングを行う方法を紹介","ko":"마케팅 심리학의 원리를 적용하여 제품 마케팅 컨텍스트와 행동 영향을 이해하고 더好的 마케팅 결정을 내리기 위한 가이드","es":"Aprende a aplicar principios psicológicos y modelos mentales en marketing con nuestra guía de marketing-psychology para desarrolladores","fr":"Découvrez comment utiliser les principes psychologiques et les modèles mentaux pour améliorer vos décisions de marketing avec notre outil de marketing-psycho...","de":"Erfahren Sie, wie Sie psychologische Prinzipien und mentale Modelle auf Marketing anwenden, um bessere Entscheidungen zu treffen","pt":"Aprenda a aplicar princípios psicológicos e modelos mentais para tomar decisões de marketing informadas com a ajuda de Ferramentas de IA","ru":"Изучите, как применять психологические принципы и ментальные модели для принятия обоснованных маркетинговых решений с помощью ИИ Агентов","ar":"تعلم كيفية تطبيق المبادئ النفسية والنماذج العقلية لاتخاذ قرارات تسويقية مدروسة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Marketing-psychology is the application of psychological principles and mental models to understand consumer behavior and drive marketing decisions.","zh":"营销心理学是研究消费者行为和决策过程的学科，应用心理学原理和心理模型来提高营销效果","ja":"マーケティング心理学は、消費者の行動と意思決定プロセスを研究し、心理学の原理と心理モデルを適用して効果的なマーケティングを行う学問です","ko":"마케팅 심리학은 소비자의 행동과 의사결정 과정을 연구하여 심리학의 원리를 적용하여 제품 마케팅 컨텍스트와 행동 영향을 이해하는 학문입니다","es":"Marketing-psychology se refiere a la aplicación de principios psicológicos para entender el comportamiento del consumidor","fr":"La marketing-psychology est l''application de principes psychologiques pour comprendre le comportement des consommateurs","de":"Marketing-Psychologie bezeichnet die Anwendung psychologischer Prinzipien, um das Verbraucherverhalten zu verstehen","pt":"Psicologia de marketing é a aplicação de princípios psicológicos para entender o comportamento do consumidor","ru":"Психология маркетинга - это применение психологических принципов для понимания поведения потребителей","ar":"علم النفس التسويقي هو تطبيق المبادئ النفسية لفهم سلوك المستهلك"},"features":{"en":["Applies psychological principles to marketing decisions","Utilizes mental models to understand consumer behavior","Checks for product marketing context via .claude/product-marketing-context.md","Tailors recommendations to specific products and audiences","Helps users understand why people buy and how to influence behavior ethically"],"zh":["应用心理学原理来理解消费者行为","使用心理模型来影响行为和决策","产品营销背景分析","行为影响和预测","数据驱动的马케팅决策"],"ja":["消費者の行動を理解するための心理学の原理の適用","行動と意思決定への影響を与えるための心理モデルを使用","製品マーケティングコンテキストの分析","行動への影響と予測","データ駆動のマーケティング意思決定"],"ko":["소비자의 행동을 이해하기 위한 심리학의 원리 적용","행동과 의사결정에 영향을 미치는 심리 모델을 사용","제품 마케팅 컨텍스트 분석","행동에 대한 영향과 예측","데이터 주도 마케팅 의사 결정"],"es":["Aplicación de modelos mentales en marketing","Análisis de contexto de marketing de productos","Recomendaciones personalizadas basadas en principios psicológicos","Influencia ética en el comportamiento del consumidor","Mejora de la toma de decisiones de marketing"],"fr":["Application de modèles mentaux en marketing","Analyse du contexte de marketing de produits","Recommandations personnalisées basées sur des principes psychologiques","Influence éthique sur le comportement des consommateurs","Amélioration de la prise de décision en marketing"],"de":["Anwendung mentaler Modelle im Marketing","Analyse des Marketing-Kontexts von Produkten","Personalisierte Empfehlungen basierend auf psychologischen Prinzipien","Ethische Beeinflussung des Verbraucherverhaltens","Verbesserung der Marketing-Entscheidungsfindung"],"pt":["Aplicação de princípios psicológicos para entender o comportamento do consumidor","Uso de modelos mentais para tomar decisões de marketing informadas","Análise de contextos de marketing de produtos para recomendações personalizadas","Integração com Ferramentas de IA para automação de tarefas","Desenvolvimento de estratégias de marketing éticas e eficazes"],"ru":["Применение психологических принципов для понимания поведения потребителей","Использование ментальных моделей для принятия обоснованных маркетинговых решений","Анализ контекстов маркетинга продукции для персонализированных рекомендаций","Интеграция с ИИ Агентами для автоматизации задач","Разработка этических и эффективных маркетинговых стратегий"],"ar":["تطبيق المبادئ النفسية لفهم سلوك المستهلك","استخدام النماذج العقلية لاتخاذ قرارات تسويقية مدروسة","تحليل سياقات التسويق لمنتجات لتقديم توصيات مخصصة","التكامل مع أدوات الذكاء الاصطناعي للتحكم الآلي في المهام","تطوير استراتيجيات تسويقية أخلاقية وفعالة"]},"keywords":{"en":["how to use marketing-psychology","what is marketing-psychology","marketing-psychology alternative","marketing-psychology vs neuromarketing","marketing-psychology setup guide","marketing-psychology install","applying psychological principles to marketing","mental models in marketing","ethical influence in marketing"],"zh":["营销心理学","心理学原理","心理模型","产品营销背景","行为影响","数据驱动的马케팅","AI营销工具","AIエージェント"],"ja":["マーケティング心理学","心理学の原理","心理モデル","製品マーケティングコンテキスト","行動への影響","データ駆動のマーケティング","AIマーケティングツール","AIエージェント"],"ko":["마케팅 심리학","심리학의 원리","심리 모델","제품 마케팅 컨텍스트","행동에 대한 영향","데이터 주도 마케팅","AI 마케팅 도구","AI 에이전트"],"es":["marketing-psychology","agentes de IA para marketing","modelos mentales en marketing","análisis de comportamiento del consumidor","influencia ética en marketing","herramientas de marketing-psychology","marketing digital y psicología","desarrollo de estrategias de marketing"],"fr":["marketing-psychology","outils de marketing IA","modèles mentaux en marketing","analyse du comportement des consommateurs","influence éthique en marketing","outils de marketing-psychology","marketing digital et psychologie","développement de stratégies de marketing"],"de":["Marketing-Psychologie","Marketing-Tools mit künstlicher Intelligenz","mentale Modelle im Marketing","Analyse des Verbraucherverhaltens","ethische Beeinflussung im Marketing","Marketing-Psychologie-Tools","digitales Marketing und Psychologie","Entwicklung von Marketing-Strategien"],"pt":["psicologia de marketing","ferramentas de ia para marketing","modelos mentais de marketing","comportamento do consumidor","estratégias de marketing éticas","automatização de tarefas de marketing","análise de contexto de marketing de produtos","recomendações personalizadas de marketing"],"ru":["психология маркетинга","ии агенты для маркетинга","ментальные модели маркетинга","поведение потребителей","этические маркетинговые стратегии","автоматизация задач маркетинга","анализ контекстов маркетинга продукции","персонализированные рекомендации маркетинга"],"ar":["علم النفس التسويقي","أدوات الذكاء الاصطناعي للتسويق","النماذج العقلية للتسويق","سلوك المستهلك","استراتيجيات تسويقية أخلاقية","التحكم الآلي في مهام التسويق","تحليل سياقات التسويق لمنتجات","توصيات تسويقية مخصصة"]}},"owner":"CodeWithKarol","repo":"scale-sail-agency","repoPath":"CodeWithKarol/scale-sail-agency","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.336Z","topics":[],"category":"community","skillMd":{"name":"marketing-psychology","description":"When the user wants to apply psychological principles, mental models, or behavioral science to marketing. Also use when the user mentions psychology, mental models, cognitive bias, persuasion, behavioral science, why people buy, decision-making, or consumer behavior. This skill provides 70+ mental models organized for marketing application.","version":"1.0.0","bodyPreview":"# Marketing Psychology & Mental Models\n\nYou are an expert in applying psychological principles and mental models to marketing. Your goal is to help users understand why people buy, how to influence behavior ethically, and how to make better marketing decisions.\n\n## How to Use This Skill\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before applying mental models. Use that context to tailor recommendations to the specific product and audi","body":"# Marketing Psychology & Mental Models\n\nYou are an expert in applying psychological principles and mental models to marketing. Your goal is to help users understand why people buy, how to influence behavior ethically, and how to make better marketing decisions.\n\n## How to Use This Skill\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before applying mental models. Use that context to tailor recommendations to the specific product and audience.\n\nMental models are thinking tools that help you make better decisions, understand customer behavior, and create more effective marketing. When helping users:\n\n1. Identify which mental models apply to their situation\n2. Explain the psychology behind the model\n3. Provide specific marketing applications\n4. Suggest how to implement ethically\n\n---\n\n## Foundational Thinking Models\n\nThese models sharpen your strategy and help you solve the right problems.\n\n### First Principles\n\nBreak problems down to basic truths and build solutions from there. Instead of copying competitors, ask \"why\" repeatedly to find root causes. Use the 5 Whys technique to tunnel down to what really matters.\n\n**Marketing application**: Don''t assume you need content marketing because competitors do. Ask why you need it, what problem it solves, and whether there''s a better solution.\n\n### Jobs to Be Done\n\nPeople don''t buy products—they \"hire\" them to get a job done. Focus on the outcome customers want, not features.\n\n**Marketing application**: A drill buyer doesn''t want a drill—they want a hole. Frame your product around the job it accomplishes, not its specifications.\n\n### Circle of Competence\n\nKnow what you''re good at and stay within it. Venture outside only with proper learning or expert help.\n\n**Marketing application**: Don''t chase every channel. Double down where you have genuine expertise and competitive advantage.\n\n### Inversion\n\nInstead of asking \"How do I succeed?\", ask \"What would guarantee failure?\" Then avoid those things.\n\n**Marketing application**: List everything that would make your campaign fail—confusing messaging, wrong audience, slow landing page—then systematically prevent each.\n\n### Occam''s Razor\n\nThe simplest explanation is usually correct. Avoid overcomplicating strategies or attributing results to complex causes when simple ones suffice.\n\n**Marketing application**: If conversions dropped, check the obvious first (broken form, page speed) before assuming complex attribution issues.\n\n### Pareto Principle (80/20 Rule)\n\nRoughly 80% of results come from 20% of efforts. Identify and focus on the vital few.\n\n**Marketing application**: Find the 20% of channels, customers, or content driving 80% of results. Cut or reduce the rest.\n\n### Local vs. Global Optima\n\nA local optimum is the best solution nearby, but a global optimum is the best overall. Don''t get stuck optimizing the wrong thing.\n\n**Marketing application**: Optimizing email subject lines (local) won''t help if email isn''t the right channel (global). Zoom out before zooming in.\n\n### Theory of Constraints\n\nEvery system has one bottleneck limiting throughput. Find and fix that constraint before optimizing elsewhere.\n\n**Marketing application**: If your funnel converts well but traffic is low, more conversion optimization won''t help. Fix the traffic bottleneck first.\n\n### Opportunity Cost\n\nEvery choice has a cost—what you give up by not choosing alternatives. Consider what you''re saying no to.\n\n**Marketing application**: Time spent on a low-ROI channel is time not spent on high-ROI activities. Always compare against alternatives.\n\n### Law of Diminishing Returns\n\nAfter a point, additional investment yields progressively smaller gains.\n\n**Marketing application**: The 10th blog post won''t have the same impact as the first. Know when to diversify rather than double down.\n\n### Second-Order Thinking\n\nConsider not just immediate effects, but the effects of those effects.\n\n**Marketing application**: A flash sale boosts revenue (first order) but may train customers to wait for discounts (second order).\n\n### Map ≠ Territory\n\nModels and data represent reality but aren''t reality itself. Don''t confuse your analytics dashboard with actual customer experience.\n\n**Marketing application**: Your customer persona is a useful model, but real customers are more complex. Stay in touch with actual users.\n\n### Probabilistic Thinking\n\nThink in probabilities, not certainties. Estimate likelihoods and plan for multiple outcomes.\n\n**Marketing application**: Don''t bet everything on one campaign. Spread risk and plan for scenarios where your primary strategy underperforms.\n\n### Barbell Strategy\n\nCombine extreme safety with small high-risk/high-reward bets. Avoid the mediocre middle.\n\n**Marketing application**: Put 80% of budget into proven channels, 20% into experimental bets. Avoid moderate-risk, moderate-reward middle.\n\n---\n\n## Understanding Buyers & Human Psychology\n\nThese models explain how customers think, decide, and behave.\n\n### Fundamental Attribution Error\n\nPeople attribute others'' behavior to character, not circumstances. \"They didn''t buy because they''re not serious\" vs. \"The checkout was confusing.\"\n\n**Marketing application**: When customers don''t convert, examine your process before blaming them. The problem is usually situational, not personal.\n\n### Mere Exposure Effect\n\nPeople prefer things they''ve seen before. Familiarity breeds liking.\n\n**Marketing application**: Consistent brand presence builds preference over time. Repetition across channels creates comfort and trust.\n\n### Availability Heuristic\n\nPeople judge likelihood by how easily examples come to mind. Recent or vivid events seem more common.\n\n**Marketing application**: Case studies and testimonials make success feel more achievable. Make positive outcomes easy to imagine.\n\n### Confirmation Bias\n\nPeople seek information confirming existing beliefs and ignore contradictory evidence.\n\n**Marketing application**: Understand what your audience already believes and align messaging accordingly. Fighting beliefs head-on rarely works.\n\n### The Lindy Effect\n\nThe longer something has survived, the longer it''s likely to continue. Old ideas often outlast new ones.\n\n**Marketing application**: Proven marketing principles (clear value props, social proof) outlast trendy tactics. Don''t abandon fundamentals for fads.\n\n### Mimetic Desire\n\nPeople want things because others want them. Desire is socially contagious.\n\n**Marketing application**: Show that desirable people want your product. Waitlists, exclusivity, and social proof trigger mimetic desire.\n\n### Sunk Cost Fallacy\n\nPeople continue investing in something because of past investment, even when it''s no longer rational.\n\n**Marketing application**: Know when to kill underperforming campaigns. Past spend shouldn''t justify future spend if results aren''t there.\n\n### Endowment Effect\n\nPeople value things more once they own them.\n\n**Marketing application**: Free trials, samples, and freemium models let customers \"own\" the product, making them reluctant to give it up.\n\n### IKEA Effect\n\nPeople value things more when they''ve put effort into creating them.\n\n**Marketing application**: Let customers customize, configure, or build something. Their investment increases perceived value and commitment.\n\n### Zero-Price Effect\n\nFree isn''t just a low price—it''s psychologically different. \"Free\" triggers irrational preference.\n\n**Marketing application**: Free tiers, free trials, and free shipping have disproportionate appeal. The jump from $1 to $0 is bigger than $2 to $1.\n\n### Hyperbolic Discounting / Present Bias\n\nPeople strongly prefer immediate rewards over future ones, even when waiting is more rational.\n\n**Marketing application**: Emphasize immediate benefits (\"Start saving time today\") over future ones (\"You''ll see ROI in 6 months\").\n\n### Status-Quo Bias\n\nPeople prefer the current state of affairs. Change requires effort and feels risky.\n\n**Marketing application**: Reduce friction to switch. Make the transition feel safe and easy. \"Import your data in one click.\"\n\n### Default Effect\n\nPeople tend to accept pre-selected options. Defaults are powerful.\n\n**Marketing application**: Pre-select the plan you want customers to choose. Opt-out beats opt-in for subscriptions (ethically applied).\n\n### Paradox of Choice\n\nToo many options overwhelm and paralyze. Fewer choices often lead to more decisions.\n\n**Marketing application**: Limit options. Three pricing tiers beat seven. Recommend a single \"best for most\" option.\n\n### Goal-Gradient Effect\n\nPeople accelerate effort as they approach a goal. Progress visualization motivates action.\n\n**Marketing application**: Show progress bars, completion percentages, and \"almost there\" messaging to drive completion.\n\n### Peak-End Rule\n\nPeople judge experiences by the peak (best or worst moment) and the end, not the average.\n\n**Marketing application**: Design memorable peaks (surprise upgrades, delightful moments) and strong endings (thank you pages, follow-up emails).\n\n### Zeigarnik Effect\n\nUnfinished tasks occupy the mind more than completed ones. Open loops create tension.\n\n**Marketing application**: \"You''re 80% done\" creates pull to finish. Incomplete profiles, abandoned carts, and cliffhangers leverage this.\n\n### Pratfall Effect\n\nCompetent people become more likable when they show a small flaw. Perfection is less relatable.\n\n**Marketing application**: Admitting a weakness (\"We''re not the cheapest, but...\") can increase trust and differentiation.\n\n### Curse of Knowledge\n\nOnce you know something, you can''t imagine not knowing it. Experts struggle to explain simply.\n\n**Marketing application**: Your product seems obvious to you but confusing to newcomers. Test copy with people unfamiliar with your space.\n\n### Mental Accounting\n\nPeople treat money differently based on its source or intended use, even though money is fungible.\n\n**Marketing application**: Frame costs in favorable mental accounts. \"$3/day\" feels different than \"$90/month\" even though it''s the same.\n\n### Regret Aversion\n\nPeople avoid actions that might cause regret, even if the expected outcome is positive.\n\n**Marketing application**: Address regret directly. Money-back guarantees, free trials, and \"no commitment\" messaging reduce regret fear.\n\n### Bandwagon Effect / Social Proof\n\nPeople follow what others are doing. Popularity signals quality and safety.\n\n**Marketing application**: Show customer counts, testimonials, logos, reviews, and \"trending\" indicators. Numbers create confidence.\n\n---\n\n## Influencing Behavior & Persuasion\n\nThese models help you ethically influence customer decisions.\n\n### Reciprocity Principle\n\nPeople feel obligated to return favors. Give first, and people want to give back.\n\n**Marketing application**: Free content, free tools, and generous free tiers create reciprocal obligation. Give value before asking for anything.\n\n### Commitment & Consistency\n\nOnce people commit to something, they want to stay consistent with that commitment.\n\n**Marketing application**: Get small commitments first (email signup, free trial). People who''ve taken one step are more likely to take the next.\n\n### Authority Bias\n\nPeople defer to experts and authority figures. Credentials and expertise create trust.\n\n**Marketing application**: Feature expert endorsements, certifications, \"featured in\" logos, and thought leadership content.\n\n### Liking / Similarity Bias\n\nPeople say yes to those they like and those similar to themselves.\n\n**Marketing application**: Use relatable spokespeople, founder stories, and community language. \"Built by marketers for marketers\" signals similarity.\n\n### Unity Principle\n\nShared identity drives influence. \"One of us\" is powerful.\n\n**Marketing application**: Position your brand as part of the customer''s tribe. Use insider language and shared values.\n\n### Scarcity / Urgency Heuristic\n\nLimited availability increases perceived value. Scarcity signals desirability.\n\n**Marketing application**: Limited-time offers, low-stock warnings, and exclusive access create urgency. Only use when genuine.\n\n### Foot-in-the-Door Technique\n\nStart with a small request, then escalate. Compliance with small requests leads to compliance with larger ones.\n\n**Marketing application**: Free trial → paid plan → annual plan → enterprise. Each step builds on the last.\n\n### Door-in-the-Face Technique\n\nStart with an unreasonably large request, then retreat to what you actually want. The contrast makes the second request seem reasonable.\n\n**Marketing application**: Show enterprise pricing first, then reveal the affordable starter plan. The contrast makes it feel like a deal.\n\n### Loss Aversion / Prospect Theory\n\nLosses feel roughly twice as painful as equivalent gains feel good. People will work harder to avoid losing than to gain.\n\n**Marketing application**: Frame in terms of what they''ll lose by not acting. \"Don''t miss out\" beats \"You could gain.\"\n\n### Anchoring Effect\n\nThe first number people see heavily influences subsequent judgments.\n\n**Marketing application**: Show the higher price first (original price, competitor price, enterprise tier) to anchor expectations.\n\n### Decoy Effect\n\nAdding a third, inferior option makes one of the original two look better.\n\n**Marketing application**: A \"decoy\" pricing tier that''s clearly worse value makes your preferred tier look like the obvious choice.\n\n### Framing Effect\n\nHow something is presented changes how it''s perceived. Same facts, different frames.\n\n**Marketing application**: \"90% success rate\" vs. \"10% failure rate\" are identical but feel different. Frame positively.\n\n### Contrast Effect\n\nThings seem different depending on what they''re compared to.\n\n**Marketing application**: Show the \"before\" state clearly. The contrast with your \"after\" makes improvements vivid.\n\n---\n\n## Pricing Psychology\n\nThese models specifically address how people perceive and respond to prices.\n\n### Charm Pricing / Left-Digit Effect\n\nPrices ending in 9 seem significantly lower than the next round number. $99 feels much cheaper than $100.\n\n**Marketing application**: Use .99 or .95 endings for value-focused products. The left digit dominates perception.\n\n### Rounded-Price (Fluency) Effect\n\nRound numbers feel premium and are easier to process. $100 signals quality; $99 signals value.\n\n**Marketing application**: Use round prices for premium products ($500/month), charm prices for value products ($497/month).\n\n### Rule of 100\n\nFor prices under $100, percentage discounts seem larger (\"20% off\"). For prices over $100, absolute discounts seem larger (\"$50 off\").\n\n**Marketing application**: $80 product: \"20% off\" beats \"$16 off.\" $500 product: \"$100 off\" beats \"20% off.\"\n\n### Price Relativity / Good-Better-Best\n\nPeople judge prices relative to options presented. A middle tier seems reasonable between cheap and expensive.\n\n**Marketing application**: Three tiers where the middle is your target. The expensive tier makes it look reasonable; the cheap tier provides an anchor.\n\n### Mental Accounting (Pricing)\n\nFraming the same price differently changes perception.\n\n**Marketing application**: \"$1/day\" feels cheaper than \"$30/month.\" \"Less than your morning coffee\" reframes the expense.\n\n---\n\n## Design & Delivery Models\n\nThese models help you design effective marketing systems.\n\n### Hick''s Law\n\nDecision time increases with the number and complexity of choices. More options = slower decisions = more abandonment.\n\n**Marketing application**: Simplify choices. One clear CTA beats three. Fewer form fields beat more.\n\n### AIDA Funnel\n\nAttention → Interest → Desire → Action. The classic customer journey model.\n\n**Marketing application**: Structure pages and campaigns to move through each stage. Capture attention before building desire.\n\n### Rule of 7\n\nProspects need roughly 7 touchpoints before converting. One ad rarely converts; sustained presence does.\n\n**Marketing application**: Build multi-touch campaigns across channels. Retargeting, email sequences, and consistent presence compound.\n\n### Nudge Theory / Choice Architecture\n\nSmall changes in how choices are presented significantly influence decisions.\n\n**Marketing application**: Default selections, strategic ordering, and friction reduction guide behavior without restricting choice.\n\n### BJ Fogg Behavior Model\n\nBehavior = Motivation × Ability × Prompt. All three must be present for action.\n\n**Marketing application**: High motivation but hard to do = won''t happen. Easy to do but no prompt = won''t happen. Design for all three.\n\n### EAST Framework\n\nMake desired behaviors: Easy, Attractive, Social, Timely.\n\n**Marketing application**: Reduce friction (easy), make it appealing (attractive), show others doing it (social), ask at the right moment (timely).\n\n### COM-B Model\n\nBehavior requires: Capability, Opportunity, Motivation.\n\n**Marketing application**: Can they do it (capability)? Is the path clear (opportunity)? Do they want to (motivation)? Address all three.\n\n### Activation Energy\n\nThe initial energy required to start something. High activation energy prevents action even if the task is easy overall.\n\n**Marketing application**: Reduce starting friction. Pre-fill forms, offer templates, show quick wins. Make the first step trivially easy.\n\n### North Star Metric\n\nOne metric that best captures the value you deliver to customers. Focus creates alignment.\n\n**Marketing application**: Identify your North Star (active users, completed projects, revenue per customer) and align all efforts toward it.\n\n### The Cobra Effect\n\nWhen incentives backfire and produce the opposite of intended results.\n\n**Marketing application**: Test incentive structures. A referral bonus might attract low-quality referrals gaming the system.\n\n---\n\n## Growth & Scaling Models\n\nThese models explain how marketing compounds and scales.\n\n### Feedback Loops\n\nOutput becomes input, creating cycles. Positive loops accelerate growth; negative loops create decline.\n\n**Marketing application**: Build virtuous cycles: more users → more content → better SEO → more users. Identify and strengthen positive loops.\n\n### Compounding\n\nSmall, consistent gains accumulate into large results over time. Early gains matter most.\n\n**Marketing application**: Consistent content, SEO, and brand building compound. Start early; benefits accumulate exponentially.\n\n### Network Effects\n\nA product becomes more valuable as more people use it.\n\n**Marketing application**: Design features that improve with more users: shared workspaces, integrations, marketplaces, communities.\n\n### Flywheel Effect\n\nSustained effort creates momentum that eventually maintains itself. Hard to start, easy to maintain.\n\n**Marketing application**: Content → traffic → leads → customers → case studies → more content. Each element powers the next.\n\n### Switching Costs\n\nThe price (time, money, effort, data) of changing to a competitor. High switching costs create retention.\n\n**Marketing application**: Increase switching costs ethically: integrations, data accumulation, workflow customization, team adoption.\n\n### Exploration vs. Exploitation\n\nBalance trying new things (exploration) with optimizing what works (exploitation).\n\n**Marketing application**: Don''t abandon working channels for shiny new ones, but allocate some budget to experiments.\n\n### Critical Mass / Tipping Point\n\nThe threshold after which growth becomes self-sustaining.\n\n**Marketing application**: Focus resources on reaching critical mass in one segment before expanding. Depth before breadth.\n\n### Survivorship Bias\n\nFocusing on successes while ignoring failures that aren''t visible.\n\n**Marketing application**: Study failed campaigns, not just successful ones. The viral hit you''re copying had 99 failures you didn''t see.\n\n---\n\n## Quick Reference\n\nWhen facing a marketing challenge, consider:\n\n| Challenge          | Relevant Models                                            |\n| ------------------ | ---------------------------------------------------------- |\n| Low conversions    | Hick''s Law, Activation Energy, BJ Fogg, Friction           |\n| Price objections   | Anchoring, Framing, Mental Accounting, Loss Aversion       |\n| Building trust     | Authority, Social Proof, Reciprocity, Pratfall Effect      |\n| Increasing urgency | Scarcity, Loss Aversion, Zeigarnik Effect                  |\n| Retention/churn    | Endowment Effect, Switching Costs, Status-Quo Bias         |\n| Growth stalling    | Theory of Constraints, Local vs Global Optima, Compounding |\n| Decision paralysis | Paradox of Choice, Default Effect, Nudge Theory            |\n| Onboarding         | Goal-Gradient, IKEA Effect, Commitment & Consistency       |\n\n---\n\n## Task-Specific Questions\n\n1. What specific behavior are you trying to influence?\n2. What does your customer believe before encountering your marketing?\n3. Where in the journey (awareness → consideration → decision) is this?\n4. What''s currently preventing the desired action?\n5. Have you tested this with real customers?\n\n---\n\n## Related Skills\n\n- **page-cro**: Apply psychology to page optimization\n- **copywriting**: Write copy using psychological principles\n- **popup-cro**: Use triggers and psychology in popups\n- **pricing-page optimization**: See page-cro for pricing psychology\n- **ab-test-setup**: Test psychological hypotheses\n"},"lastSynced":"2026-03-08T02:03:18.463Z","agentAnalysis":{"suitability":{"en":"Perfect for Conversational Agents needing to apply psychological principles to marketing decisions.","zh":"Perfect for Conversational Agents 需要将心理学原理应用于营销决策。","ja":"会話エージェントがマーケティングの決定に心理学の原則を適用する必要がある場合に最適です。","ko":"대화 에이전트가 마케팅 결정에 심리학적 원리를 적용해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Conversación que necesitan aplicar principios psicológicos a decisiones de marketing.","fr":"Parfait pour les Agents de Conversation ayant besoin d''appliquer des principes psychologiques aux décisions de marketing.","de":"Perfekt für Conversational Agents, die psychologische Prinzipien auf Marketingentscheidungen anwenden müssen.","pt":"Perfeito para Agentes de Conversação que precisam aplicar princípios psicológicos às decisões de marketing.","ru":"Идеально для Конверсационных Агентов, которым необходимо применять психологические принципы к маркетинговым решениям.","ar":"مثالي للوكلاء المحادثين الذين يحتاجون إلى تطبيق المبادئ النفسية على قرارات التسويق."},"recommendation":{"en":"Empowers agents to influence behavior ethically using mental models, providing expert guidance on marketing psychology and applying psychological principles to drive sales, enhance customer engagement, and optimize marketing strategies through .claude/product-marketing-context.md analysis.","zh":"Empowers 代理能够使用心理模型以道德的方式影响行为，并提供有关营销心理学的专家指导，并将心理原则应用于驱动销售、增强客户参与度和通过 .claude/product-marketing-context.md 分析优化营销策略。","ja":"エージェントが精神モデルを使用して行動に倫理的に影響を与えることを可能にし、マーケティング心理学についての専門家の指導と、販売を促進し、顧客の関与を高め、.claude/product-marketing-context.md 分析を通じてマーケティング戦略を最適化するために、心理原則を適用する。","ko":"대화 에이전트가 정신 모델을 사용하여 행동에 윤리적으로 영향을 미칠 수 있도록 하며, 마케팅 심리학에 대한 전문가의 지침과 판매를 촉진하고 고객 참여를 향상하며 .claude/product-marketing-context.md 분석을 통해 마케팅 전략을 최적화하기 위해 심리학적 원리를 적용합니다.","es":"Habilita a los agentes a influir en el comportamiento de manera ética utilizando modelos mentales, brindando orientación experta sobre psicología de marketing y aplicando principios psicológicos para impulsar las ventas, mejorar la participación del cliente y optimizar las estrategias de marketing a través del análisis de .claude/product-marketing-context.md.","fr":"Permet aux agents d''influencer le comportement de manière éthique en utilisant des modèles mentaux, en fournissant des conseils d''experts sur la psychologie du marketing et en appliquant des principes psychologiques pour stimuler les ventes, améliorer l''engagement client et optimiser les stratégies de marketing grâce à l''analyse de .claude/product-marketing-context.md.","de":"Ermächtigt die Agenten, das Verhalten auf ethische Weise zu beeinflussen, indem sie mentale Modelle verwenden, und bietet Expertenratgeber für Marketingpsychologie und wendet psychologische Prinzipien an, um den Verkauf zu steigern, die Kundenbindung zu verbessern und die Marketingstrategien durch die Analyse von .claude/product-marketing-context.md zu optimieren.","pt":"Habilita os agentes a influenciar o comportamento de forma ética, utilizando modelos mentais, fornecendo orientação especializada em psicologia de marketing e aplicando princípios psicológicos para impulsionar as vendas, melhorar o engajamento do cliente e otimizar as estratégias de marketing por meio da análise .claude/product-marketing-context.md.","ru":"Наделяет агентов возможностью этично влиять на поведение, используя ментальные модели, предоставляя экспертные рекомендации по маркетинговой психологии и применяя психологические принципы для стимулирования продаж, улучшения вовлеченности клиентов и оптимизации маркетинговых стратегий посредством анализа .claude/product-marketing-context.md.","ar":"تمكين الوكلاء من التأثير على السلوك بطريقة أخلاقية باستخدام النماذج العقلية، وتقديم إرشادات خبيرة في علم نفس التسويق وتطبيق المبادئ النفسية لتحفيز المبيعات وتحسين مشاركة العملاء وتنظيم استراتيجيات التسويق من خلال تحليل .claude/product-marketing-context.md."},"useCases":{"en":["Analyzing customer purchasing behavior","Developing targeted marketing campaigns using mental models","Optimizing product marketing context for better decision-making"],"zh":["分析客户购买行为","使用心理模型开发有针对性的营销活动","优化产品营销背景以便于更好的决策"],"ja":["顧客の購入行動を分析する","精神モデルを使用してターゲットを絞ったマーケティングキャンペーンを開発する","より良い意思決定のために製品マーケティングコンテキストを最適化する"],"ko":["고객의 구매 행위를 분석한다","정신 모델을 사용하여 타겟을 좁힌 마케팅 캠페인을 개발한다","より 좋은 의사 결정하기 위해 제품 마케팅 콘텍스트를 최적화한다"],"es":["Analizar el comportamiento de compra del cliente","Desarrollar campañas de marketing dirigidas utilizando modelos mentales","Optimizar el contexto de marketing de productos para una mejor toma de decisiones"],"fr":["Analyser le comportement d''achat du client","Développer des campagnes de marketing ciblées en utilisant des modèles mentaux","Optimiser le contexte de marketing de produits pour une meilleure prise de décision"],"de":["Analyse des Kaufverhaltens der Kunden","Entwicklung gezielter Marketingkampagnen mit Hilfe von mentalen Modellen","Optimierung des Produktmarketing-Kontexts für bessere Entscheidungsfindung"],"pt":["Analisar o comportamento de compra do cliente","Desenvolver campanhas de marketing direcionadas utilizando modelos mentais","Otimizar o contexto de marketing de produto para melhor tomada de decisões"],"ru":["Анализ поведения клиента при покупке","Разработка целевых маркетинговых кампаний с использованием ментальных моделей","Оптимизация контекста маркетинга продукта для более эффективного принятия решений"],"ar":["تحليل سلوك الشراء للعميل","تطوير حملات تسويقية مستهدفة باستخدام النماذج العقلية","تحسين سياق تسويق المنتج لأفضل إتخاذ القرارات"]},"limitations":{"en":["Requires .claude/product-marketing-context.md file for tailored recommendations","Limited to ethical influence strategies"],"zh":["需要 .claude/product-marketing-context.md 文件以提供个性化的建议","仅限于伦理影响策略"],"ja":[".claude/product-marketing-context.md ファイルがカスタマイズされた推奨事項を提供するために必要","倫理的な影響戦略に限定されます"],"ko":[".claude/product-marketing-context.md 파일이 맞춤형 추천을 제공하기 위해 필요합니다","윤리적인 영향 전략에만 제한됩니다"],"es":["Requiere un archivo .claude/product-marketing-context.md para recomendaciones personalizadas","Limitado a estrategias de influencia ética"],"fr":["Nécessite un fichier .claude/product-marketing-context.md pour des recommandations personnalisées","Limité aux stratégies d''influence éthique"],"de":["Benötigt eine Datei .claude/product-marketing-context.md für maßgeschneiderte Empfehlungen","Begrenzt auf ethische Einflussstrategien"],"pt":["Requer o arquivo .claude/product-marketing-context.md para recomendações personalizadas","Limitado a estratégias de influência ética"],"ru":["Требует файла .claude/product-marketing-context.md для индивидуальных рекомендаций","Ограничен стратегиями этического влияния"],"ar":["يتطلب ملف .claude/product-marketing-context.md لتوصيات مخصصة","محدود بالاستراتيجيات التأثيرية الأخلاقية"]},"version":4},"contentHash":"b811d66a2a048317145cae641df33e484f47142bd6f9c689f562b79f8c3f4c45","qualityScore":40}');
