INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CodeWithKarol/scale-sail-agency/marketing-psychology', 'marketing-psychology', 'CodeWithKarol', 'scale-sail-agency', 'community', 'marketing-psychology CodeWithKarol scale-sail-agency community The marketing-psychology skill helps users understand why people buy and how to influence behavior ethically. It provides expert guidance on applying psychological principles and mental models to marketing decisions. 营销心理学是应用心理学原理和心理模型来提高营销效果，包括产品营销背景和行为影响等 マーケティング心理学は、心理学の原理と心理モデルを適用して効果的なマーケティングを行う技術です 마케팅 심리학은 심리학의 원리를 적용하여 제품 마케팅 컨텍스트와 행동 영향을 이해하고 더好的 마케팅 결정을 내리기 위한 기술입니다 Aplicación de principios psicológicos y modelos mentales en marketing para comprender por qué la gente compra y cómo influir en su comportamiento de manera ética Application des principes psychologiques et des modèles mentaux pour comprendre les motivations d''achat et influencer le comportement de manière éthique Anwendung psychologischer Prinzipien und mentaler Modelle, um zu verstehen, warum Menschen kaufen und wie man ihr Verhalten ethisch beeinflussen kann A psicologia de marketing é uma habilidade que ajuda a entender por que as pessoas compram e como influenciar comportamentos de forma ética Психология маркетинга - это навык, который помогает понять, почему люди покупают и как этично влиять на их поведение علم النفس التسويقي هو مهارة تساعد على فهم سبب شراء الناس و كيفية التأثير على السلوكيات بطرق أخلاقية how to use marketing-psychology what is marketing-psychology marketing-psychology alternative marketing-psychology vs neuromarketing marketing-psychology setup guide marketing-psychology install applying psychological principles to marketing mental models in marketing ethical influence in marketing 营销心理学 心理学原理 心理模型 产品营销背景 行为影响 数据驱动的马케팅 AI营销工具 AIエージェント Applies psychological principles to marketing decisions Utilizes mental models to understand consumer behavior Checks for product marketing context via .claude/product-marketing-context.md Tailors recommendations to specific products and audiences Helps users understand why people buy and how to influence behavior ethically Marketing-psychology is the application of psychological principles and mental models to understand consumer behavior and drive marketing decisions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kingsonseang/staco-finance-minimal-landing/vueuse-functions', 'community', 'kingsonseang', 'staco-finance-minimal-landing', 'kingsonseang/staco-finance-minimal-landing', 'vueuse-functions', 0, 0, 40, '2026-03-08T01:57:15.509Z', '2026-03-08T02:10:24.965Z', 'f7c0a0c84cd751f3b3ce2a178b9846d00e3a92c0e97033455a12b9e6618ecc0c', '{"id":"kingsonseang/staco-finance-minimal-landing/vueuse-functions","name":"vueuse-functions","description":{"en":"The vueuse-functions skill provides a decision-and-implementation guide for VueUse composables in Vue.js/Nuxt projects, mapping requirements to suitable functions for efficient development.","zh":"VueUse 函数是一种优化 Vue.js 和 Nuxt 项目的方法，通过使用合适的函数和模式来保持代码的简洁和可维护性","ja":"VueUse 関数は、Vue.js / Nuxt プロジェクトを最適化するための方法であり、適切な関数とパターンを使用してコードを簡潔で保守可能に保つ","ko":"VueUse 함수는 Vue.js와 Nuxt 프로젝트를 최적화하는 방법으로, 적절한 함수와 패턴을 사용하여 코드를 간결하고 유지보수하기 쉽게 만듭니다","es":"VueUse Functions es una guía para la implementación de soluciones composable en Vue.js y Nuxt","fr":"VueUse Functions est un guide pour la mise en œuvre de solutions composable dans Vue.js et Nuxt","de":"VueUse Functions ist ein Leitfaden für die Implementierung von composable-Lösungen in Vue.js und Nuxt","pt":"O VueUse Functions é um guia de decisão e implementação para composables VueUse em projetos Vue.js/Nuxt","ru":"VueUse Functions - это руководство по принятию решений и реализации для composables VueUse в проектах Vue.js/Nuxt","ar":"VueUse Functions هو دليل لاتخاذ القرارات وتطبيقها لملحقات VueUse في مشاريع Vue.js/Nuxt"},"seo":{"title":{"en":"vueuse-functions: Composable-Based Solutions for Vue.js/N...","zh":"VueUse 函数集成指南 - 优化 Vue.js 和 Nuxt 项目","ja":"VueUse 関数のベストプラクティス - Vue.js / Nuxt プロジェクトの最適化","ko":"VueUse 함수 설정 가이드 - Vue.js와 Nuxt 프로젝트 최적화","es":"Guía de Configuración de Funciones VueUse","fr":"Guide de Mise en Place des Fonctions VueU