INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kingsonseang/staco-finance-minimal-landing/vueuse-functions', 'vueuse-functions', 'kingsonseang', 'staco-finance-minimal-landing', 'community', 'vueuse-functions kingsonseang staco-finance-minimal-landing community The vueuse-functions skill provides a decision-and-implementation guide for VueUse composables in Vue.js/Nuxt projects, mapping requirements to suitable functions for efficient development. VueUse 函数是一种优化 Vue.js 和 Nuxt 项目的方法，通过使用合适的函数和模式来保持代码的简洁和可维护性 VueUse 関数は、Vue.js / Nuxt プロジェクトを最適化するための方法であり、適切な関数とパターンを使用してコードを簡潔で保守可能に保つ VueUse 함수는 Vue.js와 Nuxt 프로젝트를 최적화하는 방법으로, 적절한 함수와 패턴을 사용하여 코드를 간결하고 유지보수하기 쉽게 만듭니다 VueUse Functions es una guía para la implementación de soluciones composable en Vue.js y Nuxt VueUse Functions est un guide pour la mise en œuvre de solutions composable dans Vue.js et Nuxt VueUse Functions ist ein Leitfaden für die Implementierung von composable-Lösungen in Vue.js und Nuxt O VueUse Functions é um guia de decisão e implementação para composables VueUse em projetos Vue.js/Nuxt VueUse Functions - это руководство по принятию решений и реализации для composables VueUse в проектах Vue.js/Nuxt VueUse Functions هو دليل لاتخاذ القرارات وتطبيقها لملحقات VueUse في مشاريع Vue.js/Nuxt how to use vueuse-functions vueuse-functions setup guide vueuse-functions for Vue.js vueuse-functions alternative vueuse-functions vs bespoke code what is vueuse-functions vueuse-functions install vueuse-functions best practices vueuse-functions for Nuxt vueuse-functions tutorial VueUse 函数 Vue.js 优化 Nuxt 项目 组合函数 代码简洁 可维护性 AIエージェント VueUse 函数集成 Maps requirements to the most suitable VueUse function for efficient development Applies the correct usage pattern for VueUse composables Prefers composable-based solutions over bespoke code for maintainability Supports implementation in both Vue.js and Nuxt projects Ensures concise, maintainable, and performant code implementations Guides decision-making for applying VueUse functions in development work vueuse-functions is a skill that guides the application of VueUse composables in Vue.js and Nuxt projects for concise and maintainable code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('selhorys/dataspoke-baseline/sync-spec-to-impl', 'community', 'selhorys', 'dataspoke-baseline', 'selhorys/dataspoke-baseline', 'sync-spec-to-impl', 14, 0, 40, '2026-03-03T15:57:32Z', '2026-03-04T01:54:45.764Z', '246e3504fe196bce07ba09ed3838628286de83e53f1e76249578a3ce8f44f78c', '{"id":"selhorys/dataspoke-baseline/sync-spec-to-impl","name":"sync-spec-to-impl","description":{"zh":"sync-spec-to-impl AI数据目录启动器帮助开发者简化数据管理和集成，提高开发效率","ja":"sync-spec-to-implは、開発者がデータ同期と実装を簡素化することで、AIエージェントの開発を強化します","ko":"sync-spec-to-impl AI 데이터 카탈로그 스타터는 개발자가 데이터 관리와 구현을 간소화하여 개발 효율성을 높여줍니다","es":"El catálogo de datos de IA es una herramienta que ayuda a sincronizar especificaciones de implementación con Agentes de IA, mejorando la eficiencia y la precisión","fr":"Le catalogue de données d''IA est un outil qui aide à synchroniser des spécifications d''implémentation avec des Agents d''IA, améliorant l''efficacité et la précision","de":"Der KI-Datenkatalog ist ein Werkzeug, das bei der Synchronisierung von Implementierungsspezifikationen mit KI-Agenten hilft, die Effizienz und Genauigkeit zu verbessern","pt":"O sync-spec-to-impl é um starter de catálogo de dados de IA que ajuda desenvolvedores a sincronizar especificações e implementações de forma eficiente","ru":"ИИ Агент sync-spec-to-impl - это стартовый каталог данных, помогающий разработчикам синхронизировать спецификации и реализации эффективно","ar":"وكيل الذكاء الاصطناعي sync-spec-to-impl هو بدء تشغيل كتالوج بيانات يساعد المطورين على مزامنة المواصفات والتنفيذ بفعالية","en":"AI Data Catalog Starter"},"seo":{"title":{"zh":"AI数据目录同步工具 - sync-spec-to-impl","ja":"AIエージェント：sync-spec-to-implを使用した実装の同期","ko":"AI 에이전트: sync-spec-to-impl 구현 同期 도구","es":"Herramientas de sincronización de especificaciones de imp...","fr":"Outils de synchronisation de spécifications d''implémentat...","de":"Werkzeuge zur Synchronisierung von Implementierungsspezif...","pt":"Ferramentas de IA: sync-spec-to-impl para Desenvolvedores","ru":"ИИ Агенты: sync-spec-to-impl для Разработчиков","ar":"أدوات الذكاء الاصطناعي: sync-spec-to-impl للمطورين","en":"sync-spec-to-impl"},"description":{"zh":"sync-spec-to-impl AI数据目录启动器帮助开发者简化数据管理和集成，提高开发效率","ja":"sync-spec-to-implは、開発者がデータ同期と実装を簡素化することで、AIエージェントの開発を強化します","ko":"sync-spec-to-impl AI 데이터 카탈로그 스타터는 개발자가 데이터 관리와 구현을 간소화하여 개발 효율성을 높여줍니다","es":"El catálogo de datos de IA es una herramienta que ayuda a sincronizar especificaciones de implementación con Agentes de IA, mejorando la eficiencia y la prec...","fr":"Le catalogue de données d''IA est un outil qui aide à synchroniser des spécifications d''implémentation avec des Agents d''IA, améliorant l''efficacité et la pré...","de":"Der KI-Datenkatalog ist ein Werkzeug, das bei der Synchronisierung von Implementierungsspezifikationen mit KI-Agenten hilft, die Effizienz und Genauigkeit zu...","pt":"O sync-spec-to-impl é um starter de catálogo de dados de IA que ajuda desenvolvedores a sincronizar especificações e implementações de forma eficiente","ru":"ИИ Агент sync-spec-to-impl - это стартовый каталог данных, помогающий разработчикам синхронизировать спецификации и реализации эффективно","ar":"وكيل الذكاء الاصطناعي sync-spec-to-impl هو بدء تشغيل كتالوج بيانات يساعد المطورين على مزامنة المواصفات والتنفيذ بفعالية","en":"AI Data Catalog Starter"},"definition":{"en":"AI Data Catalog Starter"},"features":{"zh":["自动同步AI数据目录","简化数据管理和集成","提高开发效率","支持多种数据格式","集成React、Python、Node.js等开发框架"],"ja":["AIデータカタログの自動同期","データ管理と実装の簡素化","開発効率の向上","複数のデータ形式をサポート","React、Python、Node.jsなどの開発フレームワークとの統合"],"ko":["AI 데이터 카탈로그 자동 동기화","데이터 관리와 구현의 간소화","개발 효율성 향상","다양한 데이터 형식 지원","React, Python, Node.js 등의 개발 프레임워크와의 통합"],"es":["Sincronización automática de especificaciones de implementación","Integración con Agentes de IA para mejorar la eficiencia","Mejora de la precisión en la implementación de especificaciones","Soporte para múltiples formatos de datos","Interfaz de usuario intuitiva y fácil de usar"],"fr":["Synchronisation automatique de spécifications d''implémentation","Intégration avec des Agents d''IA pour améliorer l''efficacité","Amélioration de la précision dans l''implémentation de spécifications","Prise en charge de plusieurs formats de données","Interface utilisateur intuitive et facile à utiliser"],"de":["Automatische Synchronisierung von Implementierungsspezifikationen","Integration mit KI-Agenten zur Verbesserung der Effizienz","Verbesserung der Genauigkeit bei der Implementierung von Spezifikationen","Unterstützung für mehrere Datenformate","Benutzerfreundliche und intuitive Oberfläche"],"pt":["Sincronização de especificações e implementações","Suporte a desenvolvedores de software","Integração com ferramentas de desenvolvimento","Melhoria da eficiência do desenvolvimento","Redução de erros e bugs"],"ru":["Синхронизация спецификаций и реализаций","Поддержка разработчиков программного обеспечения","Интеграция с инструментами разработки","Улучшение эффективности разработки","Снижение количества ошибок и багов"],"ar":["مزامنة المواصفات والتنفيذ","دعم المطورين البرمجيين","التكامل مع أدوات التطوير","تحسين كفاءة التطوير","تقليل الأخطاء والعيوب"]},"keywords":{"zh":["如何使用sync-spec-to-impl","AI数据目录工具","sync-spec-to-impl安装","sync-spec-to-impl教程","AI开发工具","数据管理工具","sync-spec-to-impl vs 其他工具"],"ja":["sync-spec-to-implの使い方","AIエージェントの実装","sync-spec-to-implのインストール","sync-spec-to-implのチュートリアル","AI開発ツール","データ管理ツール","sync-spec-to-implと他のツールの比較"],"ko":["sync-spec-to-impl 사용법","AI 에이전트 구현","sync-spec-to-impl 설치","sync-spec-to-impl 튜토리얼","AI 개발 도구","데이터 관리 도구","sync-spec-to-impl과 다른 도구의 비교"],"es":["cómo usar Agentes de IA","qué es un Agente de IA","sincronización de especificaciones de implementación","catálogo de datos de IA","Agentes de IA para la implementación","herramientas de sincronización de especificaciones","mejora de la eficiencia con Agentes de IA","precisión en la implementación de especificaciones"],"fr":["comment utiliser des Agents d''IA","quoi est un Agent d''IA","synchronisation de spécifications d''implémentation","catalogue de données d''IA","Agents d''IA pour l''implémentation","outils de synchronisation de spécifications","amélioration de l''efficacité avec des Agents d''IA","précision dans l''implémentation de spécifications"],"de":["wie man KI-Agents verwendet","was ist ein KI-Agent","Synchronisierung von Implementierungsspezifikationen","KI-Datenkatalog","KI-Agents für die Implementierung","Werkzeuge zur Synchronisierung von Spezifikationen","Verbesserung der Effizienz mit KI-Agenten","Genauigkeit bei der Implementierung von Spezifikationen"],"pt":["como usar sync-spec-to-impl","o que é sync-spec-to-impl","ferramentas de ia para desenvolvedores","sync-spec-to-impl vs outras ferramentas","instalar sync-spec-to-impl","guia de configuração do sync-spec-to-impl","desenvolvimento de software com sync-spec-to-impl","melhores práticas para usar sync-spec-to-impl"],"ru":["как использовать ИИ Агент sync-spec-to-impl","что такое ИИ Агент sync-spec-to-impl","инструменты ИИ для разработчиков","ИИ Агент sync-spec-to-impl vs другие инструменты","установить ИИ Агент sync-spec-to-impl","руководство по настройке ИИ Агента sync-spec-to-impl","разработка программного обеспечения с ИИ Агентом sync-spec-to-impl","лучшие практики использования ИИ Агента sync-spec-to-impl"],"ar":["كيفية استخدام وكيل الذكاء الاصطناعي sync-spec-to-impl","ما هو وكيل الذكاء الاصطناعي sync-spec-to-impl","أدوات الذكاء الاصطناعي للمطورين","وكيل الذكاء الاصطناعي sync-spec-to-impl مقابل أدوات أخرى","تثبيت وكيل الذكاء الاصطناعي sync-spec-to-impl","دليل إعداد وكيل الذكاء الاصطناعي sync-spec-to-impl","تطوير البرمجيات مع وكيل الذكاء الاصطناعي sync-spec-to-impl","أفضل ممارسات لاستخدام وكيل الذكاء الاصطناعي sync-spec-to-impl"]}},"owner":"selhorys","repo":"dataspoke-baseline","repoPath":"selhorys/dataspoke-baseline","stars":14,"forks":0,"updatedAt":"2026-03-03T15:57:32Z","topics":[],"category":"community","skillMd":{"name":"sync-spec-to-impl","description":"Synchronize DataSpoke specification documents with current implementation state. Use when specs and implementations have drifted and need reconciliation.","bodyPreview":"## Definitions\n\n### What counts as Specification\n\nSpecification is any document that describes *what should exist and how it should behave*:\n\n- Docs under `spec/` and `spec/feature/` directories\n- `README.md` files at each component directory and at the repository root\n- `CLAUDE.md` at the repository root\n- **Declarations** in SKILL.md files (YAML frontmatter + description/routing sections at the top — everything above the detailed workflow instructions)\n\n### What counts as Implementation\n\nImple","body":"## Definitions\n\n### What counts as Specification\n\nSpecification is any document that describes *what should exist and how it should behave*:\n\n- Docs under `spec/` and `spec/feature/` directories\n- `README.md` files at each component directory and at the repository root\n- `CLAUDE.md` at the repository root\n- **Declarations** in SKILL.md files (YAML frontmatter + description/routing sections at the top — everything above the detailed workflow instructions)\n\n### What counts as Implementation\n\nImplementation is the actual code, scripts, and configs that *do things*:\n\n- `.prauto/` scripts, libraries, prompts, and config files\n- `dev_env/` scripts, manifests, and helpers\n- `helm-charts/` chart definitions, values, and templates\n- `api/` OpenAPI spec (`openapi.yaml`)\n- `src/` application code (api, backend, frontend) and `tests/` directories\n- **Detailed logic** in SKILL.md files (the workflow instruction body — everything below the declarations)\n- `ref/` system (reference materials and setup scripts)\n\n### The boundary inside SKILL.md\n\nA single SKILL.md file straddles both sides:\n\n| Part | Counts as | What it contains |\n|------|-----------|------------------|\n| YAML frontmatter (`name`, `description`, `argument-hint`, `allowed-tools`, flags) | **Spec** | What the skill claims to do |\n| Routing table / first overview section | **Spec** | How the skill is invoked |\n| Detailed step-by-step workflow instructions | **Impl** | How the skill actually works |\n\n---\n\n## Routing & Scope Definitions\n\nParse `$ARGUMENTS` to determine the change scope. If no arguments are given or the scope is unclear, output the following scope menu and **wait for the user to reply** with their selection:\n\n```\nSelect scopes to sync (comma-separated numbers or keywords):\n\n  1. all          — All scopes that have both spec and impl files\n  2. prauto       — .prauto scripts, prauto-related specs and skills\n  3. ai-scaffold  — CLAUDE.md, .claude/ settings, hooks, agents, all skills\n  4. dev-env      — dev_env/ scripts, DEV_ENV spec\n  5. helm-charts  — Helm chart definitions and specs\n  6. api          — API specs, OpenAPI, src/api/ code\n  7. ref          — ref/ setup scripts and reference materials\n  8. backend      — Backend services, Temporal workflows (TBD)\n  9. frontend     — Next.js frontend code (TBD)\n\nExample: \"1\" or \"prauto, api\" or \"2,3,6\"\n```\n\nParse the user''s reply into individual scope keywords. Accept numbers, keywords, or a mix.\n\nThe directories below are **starting points** — always glob the actual tree to discover what exists. If files have moved or been renamed, follow the real structure rather than these hints.\n\n| Scope keyword | Spec side | Impl side |\n|---------------|-----------|-----------|\n| `prauto` | `spec/AI_PRAUTO.md`, prauto-related skill declarations, `.prauto/README.md` | `.prauto/` scripts and libs, prauto-related skill logic bodies |\n| `ai-scaffold` | `spec/AI_SCAFFOLD.md`, `CLAUDE.md`, all skill declarations across `.claude/skills/` | `.claude/` settings/hooks/agents, all skill logic bodies |\n| `dev-env` | `spec/feature/DEV_ENV.md`, dev-env skill declaration, `dev_env/README.md` | `dev_env/` scripts and helpers, dev-env skill logic body |\n| `helm-charts` | `spec/feature/HELM_CHART.md` | `helm-charts/` charts, values, and templates |\n| `api` | `spec/feature/API.md`, `spec/API_DESIGN_PRINCIPLE_en.md`, `src/api/README.md` | `api/` OpenAPI spec, `src/api/` routers/schemas/auth/middleware |\n| `ref` | `spec/AI_SCAFFOLD.md` (ref section), ref-setup skill declaration, `ref/README.md` | `ref/` setup scripts and reference materials, ref-setup skill logic body |\n| `backend` | TBD | TBD |\n| `frontend` | TBD | TBD |\n| `all` | All of the above | All of the above |\n\n- If the user selects `all`, expand to every scope that has both spec and impl files present.\n- For scopes marked **TBD**: inform the user that the mapping is not yet defined and skip with a note.\n\n---\n\n## Step 1 — Collect inventory\n\nFor each selected scope:\n\n1. **Glob** for all spec-side and impl-side files using the areas in §Routing & Scope Definitions.\n2. Build a file inventory: `{scope, side, path, exists}`.\n3. If a scope has no spec files or no impl files, report it and skip with a warning.\n\n---\n\n## Step 2 — Read and compare\n\nFor each scope, read files on both sides and identify discrepancies.\n\n### What to look for\n\n| Category | Example discrepancies |\n|----------|-----------------------|\n| **Structural drift** | Spec lists components/scripts that don''t exist in impl, or impl has components not mentioned in spec |\n| **Naming mismatch** | Spec uses one name for a concept; impl uses a different name |\n| **Behavioral drift** | Spec describes a workflow or protocol; impl does it differently |\n| **Missing documentation** | Impl has features/options not documented in spec or README |\n| **Stale references** | Spec references files, paths, or versions that have changed |\n| **Skill declaration drift** | SKILL.md declaration (frontmatter/routing) doesn''t match the skill''s logic body |\n\n### Reading strategy\n\n- **Spec side**: Read fully — these define the intended behavior.\n- **Impl side**: Focus on structure, exported functions/endpoints, CLI options, and high-level flow. Don''t read every line of business logic unless the spec describes that level of detail.\n- **SKILL.md**: Read the declaration (frontmatter + routing) as spec; skim the logic body for workflow steps and behavioral contracts; compare the two sides against each other.\n\n---\n\n## Step 3 — Classify and prioritize changes\n\n### High-level spec rules (spec hierarchy awareness)\n\nFollow the spec hierarchy from `CLAUDE.md`. Higher-priority documents constrain lower ones.\n\n| Priority | Documents | Sync rule |\n|----------|-----------|-----------|\n| 1 | `MANIFESTO_en/kr.md` | **Never modify.** Only flag contradictions for user review. |\n| 2 | `API_DESIGN_PRINCIPLE_en/kr.md`, `DATAHUB_INTEGRATION.md` | Fix factual inaccuracies only. Keep conventions abstract — no impl details. |\n| 3 | `ARCHITECTURE.md`, `TESTING.md`, `USE_CASE_en/kr.md` | Update component lists, tech stack, data flows if they''ve changed. Keep architectural level — no code-level detail. |\n| 4 | `AI_SCAFFOLD.md`, `AI_PRAUTO.md` | Update to reflect current scaffold structure and prauto behavior. May include moderate detail (file trees, config keys, workflow steps). |\n| 5–6 | `feature/*.md`, `feature/spoke/*.md` | Full detail allowed. These are the deep-dive specs. |\n\n### Brevity rules\n\n- **`CLAUDE.md`** (root): Keep as brief as possible. Orientation document, not a reference. Only names, key commands, and pointers to detailed specs. Remove anything that belongs in `AI_SCAFFOLD.md` or feature specs.\n- **`README.md`** files: Quick-start focused. Prerequisites, install command, access details, link to spec. No architecture discussion.\n- **SKILL.md declarations**: `description` should be one sentence. `argument-hint` should match actual accepted arguments.\n- **High-level specs (priority 1–3)**: Describe *what* and *why*, not *how*. Implementation details belong in priority 4–6 documents or in impl files.\n- **Generally, all spec-side documents should stay brief.** They exist to orient and constrain, not to replicate implementation details. \n- In spec, focus on architecture, decisions, and constraints. From spec, remove verbatim template code, full code blocks, and script snippets that duplicate the impl files.\n\n### Change direction heuristic\n\n- If **impl is more recent** (has features/options that spec doesn''t mention) → propose updating spec to document the current state.\n- If **spec has requirements** that impl doesn''t fulfill → flag as \"spec gap in implementation\" — do not auto-modify impl code (too risky without tests). Report it for the user to decide.\n- If **both have drifted** → propose spec update to match impl reality, and list impl gaps separately.\n\n---\n\n## Step 4 — Present findings and apply changes\n\n### Report format\n\nPresent a structured summary before making changes:\n\n```\n## Sync Report — <scope(s)>\n\n### Discrepancies Found\n\n#### <Scope Name>\n\n| # | File | Side | Issue | Proposed Action |\n|---|------|------|-------|-----------------|\n| 1 | spec/AI_PRAUTO.md | spec | Missing reference to new lib module | Add to file tree |\n| 2 | .prauto/README.md | spec | Stale prerequisites list | Update to match reality |\n| 3 | .claude/skills/dev-env/SKILL.md | spec (decl) | argument-hint missing new action | Update frontmatter |\n| ... | ... | ... | ... | ... |\n\n#### Spec Gaps in Implementation (not auto-fixed)\n- spec/feature/API.md requires endpoint X, but src/api/routers/ doesn''t implement it\n\n### High-Level Spec Impact\n- CLAUDE.md: <no change needed | brief update proposed>\n- ARCHITECTURE.md: <no change needed | update proposed>\n```\n\n### Apply changes\n\n1. **Ask the user** to confirm before applying. Show the proposed edits clearly.\n2. Apply edits using the `Edit` tool (prefer surgical edits over full rewrites).\n3. For high-level specs and `CLAUDE.md`, show the diff preview first — these files affect all agents.\n4. After applying, re-read modified files to verify consistency.\n\n---\n\n## Cross-scope consistency check\n\nWhen `all` is selected (or multiple scopes), perform an additional pass after the per-scope steps above:\n\n- Flag any **contradictions between priority levels** (e.g., a feature spec contradicting ARCHITECTURE.md, or a skill declaration contradicting its parent spec).\n- The spec hierarchy in §Step 3 determines which document is authoritative when there is a conflict — higher priority wins.\n"},"lastSynced":"2026-03-04T01:54:45.764Z","agentAnalysis":{"suitability":{"en":"Essential for Documentation Integrity Agents maintaining alignment between technical specifications and code implementations.","zh":"对于文档完整性代理维护技术规格和代码实现之间的对齐至关重要。","ja":"技術仕様とコード実装の間の整合性を維持するために、ドキュメント完全性エージェントに不可欠です。","ko":"기술 사양과 코드 구현 간의 일치를 유지하는 데 필수적인 문서 무결성 에이전트입니다.","es":"Esencial para los agentes de integridad de la documentación que mantienen la alineación entre las especificaciones técnicas y las implementaciones de código.","fr":"Essentiel pour les agents d''intégrité de la documentation qui maintiennent l''alignement entre les spécifications techniques et les implémentations de code.","de":"Wesentlich für die Integritätsagenten der Dokumentation, die die Ausrichtung zwischen den technischen Spezifikationen und den Codeimplementierungen aufrechterhalten.","pt":"Essencial para os Agentes de Integridade de Documentação que mantêm o alinhamento entre especificações técnicas e implementações de código.","ru":"Необходимо для агентов целостности документации, обеспечивающих соответствие между техническими спецификациями и кодовыми реализациями.","ar":"جوهرية لعمليات توثيق الوثائق التي تحافظ على الانسجام بين المواصفات الفنية وتنفيذ الكود."},"recommendation":{"en":"Enables automated synchronization between declarative specifications (spec/ directories, README.md, CLAUDE.md, SKILL.md frontmatter) and actual implementation code. It provides systematic gap analysis and reconciliation for documentation-complete systems.","zh":"实现声明式规格（spec/ 目录、README.md、CLAUDE.md、SKILL.md 前置内容）和实际实现代码之间的自动同步。它为文档完整系统提供系统化的差异分析和调和。","ja":"宣言的仕様（spec/ ディレクトリ、README.md、CLAUDE.md、SKILL.md フロントマター）と実際の実装コードの間の自動同期を可能にします。ドキュメント完全なシステムのための体系的なギャップ分析と和解を提供します。","ko":"선언적 사양(spec/ 디렉토리, README.md, CLAUDE.md, SKILL.md 프론티어)과 실제 구현 코드 간의 자동 동기화를 가능하게 합니다. 문서 완전한 시스템을 위한 체계적인 갭 분석 및 조정을 제공합니다.","es":"Habilita la sincronización automatizada entre las especificaciones declarativas (directorios spec/, README.md, CLAUDE.md, frontmatter de SKILL.md) y el código de implementación real. Proporciona un análisis de brechas sistemático y una reconciliación para sistemas con documentación completa.","fr":"Permet la synchronisation automatique entre les spécifications déclaratives (répertoires spec/, README.md, CLAUDE.md, frontmatter de SKILL.md) et le code d''implémentation réel. Fournit une analyse de lacunes systématique et une réconciliation pour les systèmes à documentation complète.","de":"Ermöglicht die automatisierte Synchronisation zwischen den deklarativen Spezifikationen (spec/-Verzeichnisse, README.md, CLAUDE.md, SKILL.md-Frontmatter) und dem tatsächlichen Implementierungscode. Bietet eine systematische Lückenanalyse und Abstimmung für dokumentationsvollständige Systeme.","pt":"Permite a sincronização automática entre especificações declarativas (diretórios spec/, README.md, CLAUDE.md, frontmatter de SKILL.md) e código de implementação real. Fornece uma análise sistemática de lacunas e reconciliação para sistemas de documentação completa.","ru":"Позволяет автоматически синхронизировать декларативные спецификации (каталоги spec/, README.md, CLAUDE.md, метаданные SKILL.md) и фактический код реализации. Предоставляет системный анализ разрывов и согласование для систем с полной документацией.","ar":"تمكن من التزامن الآلي بين المواصفات الإعلانية (مجلدات spec/، README.md، CLAUDE.md، SKILL.md frontmatter) والكود الفعلي للتطبيق. يوفر تحليلًا منهجيًا للفجوات والمصالح للمعظمات ذات الوثائق الكاملة."},"useCases":{"en":["Validating feature completeness against spec documents","Identifying undocumented implementation changes","Maintaining CLAUDE.md accuracy with current system behavior","Auditing README.md files for implementation drift"],"zh":["验证功能的完整性与规格文档","识别未记录的实现更改","维护CLAUDE.md的准确性与当前系统行为","审计README.md文件的实现偏差"],"ja":["機能の完全性を仕様ドキュメントに対して検証する","記録されていない実装の変更を特定する","CLAUDE.mdの精度を現在のシステム動作と維持する","README.mdファイルの実装の乖離を監査する"],"ko":["기능의 완전성을 사양 문서에 대해 검증","기록되지 않은 구현 변경 사항을 식별","CLAUDE.md의 정확성을 현재 시스템 동작과 유지","README.md 파일의 구현 편차를 감사"],"es":["Validar la completitud de las características frente a los documentos de especificación","Identificar los cambios de implementación no documentados","Mantener la precisión de CLAUDE.md con el comportamiento actual del sistema","Auditar los archivos README.md para el desplazamiento de la implementación"],"fr":["Valider la complétude des fonctionnalités par rapport aux documents de spécification","Identifier les modifications d''implémentation non documentées","Maintenir la précision de CLAUDE.md avec le comportement actuel du système","Auditer les fichiers README.md pour le déplacement de l''implémentation"],"de":["Überprüfen der Vollständigkeit der Funktionen gegenüber den Spezifikationsdokumenten","Ermitteln nicht dokumentierter Implementierungsänderungen","Aufrechterhalten der Genauigkeit von CLAUDE.md mit dem aktuellen Systemverhalten","Auditen der README.md-Dateien für Implementierungsdrift"],"pt":["Validar a completude de recursos contra documentos de especificação","Identificar alterações de implementação não documentadas","Manter a precisão do CLAUDE.md com o comportamento atual do sistema","Auditar arquivos README.md para derivação de implementação"],"ru":["Проверять полноту функций против спецификационных документов","Определять нерассмотренные изменения реализации","Поддерживать точность CLAUDE.md с текущим поведением системы","Проверять файлы README.md на отклонение реализации"],"ar":["التحقق من اكتمال الميزات مقابل وثائق المواصفات","تحديد التغييرات غير المocumentedة للتنفيذ","الحفاظ على دقة CLAUDE.md مع سلوك النظام الحالي","مراجعة ملفات README.md لانحراف التنفيذ"]},"limitations":{"en":["Requires filesystem access to spec/ and component directories","Depends on consistent YAML frontmatter structure in SKILL.md","Limited to declared specification formats (spec/, README.md, CLAUDE.md)"],"zh":["需要对spec/和组件目录的文件系统访问","依赖于SKILL.md中的一致的YAML前置内容结构","仅限于已声明的规格格式（spec/、README.md、CLAUDE.md）"],"ja":["spec/およびコンポーネントディレクトリへのファイルシステムアクセスが必要","SKILL.md内の一貫したYAMLフロントマター構造に依存","宣言された仕様形式（spec/、README.md、CLAUDE.md）のみに限定"],"ko":["spec/ 및 구성 요소 디렉토리에 대한 파일 시스템 액세스가 필요","SKILL.md의 일관된 YAML 프론티어 구조에 의존","선언된 사양 형식(spec/, README.md, CLAUDE.md)만으로 제한"],"es":["Requiere acceso al sistema de archivos para los directorios spec/ y componentes","Depende de una estructura de frontmatter YAML consistente en SKILL.md","Limitado a formatos de especificación declarados (spec/, README.md, CLAUDE.md)"],"fr":["Nécessite un accès au système de fichiers pour les répertoires spec/ et les composants","Dépend d''une structure de frontmatter YAML cohérente dans SKILL.md","Limité aux formats de spécification déclarés (spec/, README.md, CLAUDE.md)"],"de":["Benötigt Zugriff auf das Dateisystem für die Verzeichnisse spec/ und Komponenten","Hängt von einer konsistenten YAML-Frontmatter-Struktur in SKILL.md ab","Begrenzt auf deklarierte Spezifikationsformate (spec/-Verzeichnisse, README.md, CLAUDE.md)"],"pt":["Requer acesso ao sistema de arquivos para diretórios spec/ e componentes","Depende de estrutura de frontmatter YAML consistente em SKILL.md","Limitado a formatos de especificação declarados (spec/, README.md, CLAUDE.md)"],"ru":["Требует доступа к файловой системе для каталогов spec/ и компонентов","Зависит от последовательной структуры метаданных YAML в SKILL.md","Ограничен объявленными форматами спецификаций (spec/, README.md, CLAUDE.md)"],"ar":["يتطلب الوصول إلى نظام الملفات لمجلدات spec/ والمكونات","يعتمد على هيكل YAML المترابط في SKILL.md","محدود بالتنسيقات المعلنة للمواصفات (spec/، README.md، CLAUDE.md)"]},"version":3},"contentHash":"246e3504fe196bce07ba09ed3838628286de83e53f1e76249578a3ce8f44f78c","qualityScore":40}');
