INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('phrazzld/codex-config/pr', 'pr', 'phrazzld', 'codex-config', 'community', 'pr phrazzld codex-config community Codex CLI控制栈的PR命令允许开发人员创建清洁、文档齐全的PR，提高代码审查效率 Codex CLIコントロールスタックのPRコマンドを使用すると、開発者はクリーンでドキュメント化されたPRを作成でき、コードレビューの効率が向上します Codex CLI 제어 스택의 PR 명령을 사용하면 개발자가 깨끗하고 문서화된 PR을 생성하여 코드 리뷰 효율성을 향상시킬 수 있습니다 El comando ''pr'' permite a los ingenieros abrir solicitudes de extracción desde el estado actual de la rama, mejorando la colaboración y la documentación La commande ''pr'' permet aux ingénieurs d''ouvrir des demandes d''extraction à partir de l''état actuel de la branche, améliorant ainsi la collaboration et la documentation Der Befehl ''pr'' ermöglicht es Entwicklern, Pull-Anfragen vom aktuellen Branch-Zustand aus zu öffnen, was die Zusammenarbeit und Dokumentation verbessert O Codex CLI permite que os desenvolvedores criem e gerenciem pull requests de forma eficiente, com recursos como commit semântico e link para issues. Codex CLI позволяет разработчикам создавать и управлять пулл-реквестами эффективно, с функциями seperti семантический коммит и ссылка на issues. يسمح Codex CLI للمطورين بإنشاء وتنظيم طلبات السحب بفعالية، مع ميزات مثل Commit Семантический وربط المشاكل. codex cli control stack Codex CLI PR命令 Git拉取请求 代码审查 开发效率 自动提交 codex cli control stack');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/React Testing', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'React Testing', 0, 0, 40, '2026-02-20T04:13:19.578Z', '2026-02-20T04:51:59.277Z', '9a35bd3811f1f1bf4463abcf4fd2baeb5913e5565d1f4b1ca0bc86cdb63d074a', '{"id":"HoangNguyen0403/agent-skills-standard/React Testing","name":"React Testing","description":{"zh":"React ","ja":"React ","ko":"React ","es":"Nuestras mejores prácticas para pruebas de React se centran en la creación de tests confiables y escalables que se ajusten a las necesidades de tu aplicación","fr":"Nos meilleures pratiques pour les tests React se concentrent sur la création de tests fiables et évolutifs qui répondent aux besoins de votre application","de":"Unsere bewährten Methoden für React-Tests konzentrieren sich auf die Erstellung zuverlässiger und skalierbarer Tests, die den Anforderungen Ihrer Anwendung entsprechen","pt":"Testes em React com enfoque em comportamento do usuário, utilizando React Testing Library e Vitest","ru":"Тестирование React с фокусом на поведении пользователя, используя React Testing Library и Vitest","ar":"اختبار رياكت مع التركيز على سلوك المستخدم، باستخدام مكتبة اختبار رياكت و فيتست","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"React ","ja":"React ","ko":"React ","es":"Pruebas de React: Mejores Prácticas y Herramientas","fr":"Test React: Meilleures Pratiques et Outils","de":"React-Tests: Best Practices und Tools","pt":"Testes em React: Melhores Práticas","ru":"Тестирование React: Лучшие Практики","ar":"اختبار رياكت: أفضل الممارسات","en":"React Testing"},"description":{"zh":"React ","ja":"React ","ko":"React ","es":"Nuestras mejores prácticas para pruebas de React se centran en la creación de tests confiables y escalables que se ajusten a las necesidades de tu aplicación","fr":"Nos meilleures pratiques pour les tests React se concentrent sur la création de tests fiables et évolutifs qui répondent aux besoins de votre application","de":"Unsere bewährten Methoden für React-Tests konzentrieren sich auf die Erstellung zuverlässiger und skalierbarer Tests, die den Anforderungen Ihrer Anwendung e...","pt":"Testes em React com enfoque em comportamento do usuário, utilizando React Testing Library e Vitest","ru":"Тестирование React с фокусом на поведении пользователя, используя React Testing Library и Vitest","ar":"اختبار رياكت مع التركيز على سلوك المستخدم، باستخدام مكتبة اختبار رياكت و فيتست","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and p..."},"definition":{"en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"features":{"zh":["React Testing Library + Vitest","","getByRole","userEvent","MSW"],"ja":["React Testing Library + Vitest","","getByRole","userEvent","MSW"],"ko":["React Testing Library + Vitest","","getByRole","userEvent","MSW"],"es":["Uso de React Testing Library y Vitest","Enfoque en la prueba del comportamiento del usuario","Uso de queries como getByRole y getByText","Implementación de eventos asíncronos con userEvent","Uso de MSW para mockear peticiones de red","Pruebas de accesibilidad"],"fr":["Utilisation de React Testing Library et Vitest","Focus sur les tests de comportement utilisateur","Utilisation de requêtes comme getByRole et getByText","Mise en œuvre d''événements asynchrones avec userEvent","Utilisation de MSW pour mocker les requêtes réseau","Tests d''accessibilité"],"de":["Verwendung von React Testing Library und Vitest","Fokus auf Benutzerverhaltens-Tests","Verwendung von Abfragen wie getByRole und getByText","Implementierung von asynchronen Ereignissen mit userEvent","Verwendung von MSW zum Mocken von Netzwerkanfragen","Barrierefreitest"],"pt":["Utilização de React Testing Library e Vitest","Testes de comportamento do usuário","Uso de `getByRole` e `getByText`","Suporte a atualizações assíncronas","Uso de MSW para mock de rede","Testes de acessibilidade"],"ru":["Использование React Testing Library и Vitest","Тестирование поведения пользователя","Использование `getByRole` и `getByText`","Поддержка асинхронных обновлений","Использование MSW для имитации сети","Тестирование доступности"],"ar":["استخدام مكتبة اختبار رياكت و فيتست","اختبار سلوك المستخدم","استخدام `getByRole` و `getByText`","دعم التحديثات غير المتزامنة","استخدام MSW لمحاكاة الشبكة","اختبار إمكانية الوصول"]},"keywords":{"zh":["React ","React ","React ","React ","React ","React ","React "],"ja":["React ","React ","React ","React ","React ","React ","React "],"ko":["React ","React ","React ","React ","React ","React ","React "],"es":["pruebas de React","mejores prácticas de pruebas","React Testing Library","Vitest","pruebas de comportamiento","pruebas asíncronas","mockear peticiones de red","pruebas de accesibilidad"],"fr":["tests React","meilleures pratiques de tests","React Testing Library","Vitest","tests de comportement","tests asynchrones","mocking des requêtes réseau","tests d''accessibilité"],"de":["React-Tests","bewährte Methoden für Tests","React Testing Library","Vitest","Benutzerverhaltens-Tests","asynchrone Tests","Mocken von Netzwerkanfragen","Barrierefreitest"],"pt":["testes em react","react testing library","vitest","testes de comportamento","desenvolvimento de software","qualidade de software","testes automatizados","react js","desenvolvimento web"],"ru":["тестирование react","react testing library","vitest","тестирование поведения","разработка программного обеспечения","качество программного обеспечения","автоматизированное тестирование","react js","веб-разработка"],"ar":["اختبار رياكت","مكتبة اختبار رياكت","فيتست","اختبار السلوك","تطوير البرمجيات","جودة البرمجيات","اختبار آلي","رياكت جس","تطوير الويب"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"React Testing","description":"Testing strategies with RTL and Jest/Vitest.","bodyPreview":"# React Testing\n\n## **Priority: P2 (MAINTENANCE)**\n\nReliable tests focusing on user behavior.\n\n## Implementation Guidelines\n\n- **Tooling**: React Testing Library + Vitest.\n- **Philosophy**: Test behavior, not implementation (State/Internal vars).\n- **Queries**: `getByRole` > `getByText` > `getByTestId`.\n- **Events**: Use `userEvent` (async) over `fireEvent`.\n- **Async**: `await screen.findBy*` for async updates.\n- **Mocks**: MSW for network. Mock heavy 3rd-party libs.\n- **Accessibility**: Testin","body":"# React Testing\n\n## **Priority: P2 (MAINTENANCE)**\n\nReliable tests focusing on user behavior.\n\n## Implementation Guidelines\n\n- **Tooling**: React Testing Library + Vitest.\n- **Philosophy**: Test behavior, not implementation (State/Internal vars).\n- **Queries**: `getByRole` > `getByText` > `getByTestId`.\n- **Events**: Use `userEvent` (async) over `fireEvent`.\n- **Async**: `await screen.findBy*` for async updates.\n- **Mocks**: MSW for network. Mock heavy 3rd-party libs.\n- **Accessibility**: Testing Lib implicitly tests a11y roles.\n\n## Anti-Patterns\n\n- **No Shallow Rendering**: Render full tree.\n- **No Testing Implementation Details**: Don''t check `component.state`.\n- **No Wait**: Use `findBy`, avoid `waitFor` if possible.\n\n## Code\n\n```tsx\ntest(''submits form'', async () => {\n  const user = userEvent.setup();\n  render(<LoginForm />);\n\n  await user.type(screen.getByLabelText(/email/i), ''test@test.com'');\n  await user.click(screen.getByRole(''button'', { name: /login/i }));\n\n  expect(await screen.findByText(/welcome/i)).toBeInTheDocument();\n});\n```\n"},"lastSynced":"2026-02-20T04:51:59.277Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents focused on ensuring reliable user interfaces with React Testing Library and Vitest","zh":"适用于专注于使用 React Testing Library 和 Vitest 确保可靠用户界面的前端代理","ja":"React Testing Library と Vitest を使用して信頼性の高いユーザー インターフェイスを確保することに重点を置くフロントエンド エージェントに最適","ko":"React Testing Library와 Vitest를 사용하여 신뢰할 수 있는 사용자 인터페이스를 보장하는 프론트엔드 에이전트에 적합","es":"Ideal para agentes de frontend centrados en garantizar interfaces de usuario confiables con React Testing Library y Vitest","fr":"Idéal pour les agents de frontend axés sur la garantie d''interfaces utilisateur fiables avec React Testing Library et Vitest","de":"Ideal für Frontend-Agents, die sich auf die Gewährleistung zuverlässiger Benutzeroberflächen mit React Testing Library und Vitest konzentrieren","pt":"Ideal para Agentes Frontend focados em garantir interfaces de usuário confiáveis com React Testing Library e Vitest","ru":"Идеально для агентов фронтенда, сосредоточенных на обеспечении надежных пользовательских интерфейсов с помощью React Testing Library и Vitest","ar":"مثالي لعميل واجهة المستخدم الذي يركز على ضمان واجهات مستخدم موثوقة مع مكتبة اختبار React و Vitest"},"recommendation":{"en":"Empowers agents to write robust tests focusing on user behavior, utilizing `getByRole`, `getByText`, and `getByTestId` queries, while leveraging `userEvent` for async interactions and MSW for network mocking, thereby enhancing overall application stability and accessibility","zh":"赋予代理写入强大的测试能力，专注于用户行为，利用 `getByRole`、`getByText` 和 `getByTestId` 查询，同时利用 `userEvent` 进行异步交互和 MSW 进行网络模拟，从而提高整体应用稳定性和可访问性","ja":"エージェントが強力なテストを記述できるようにし、ユーザーの動作に焦点を当て、`getByRole`、`getByText`、`getByTestId` クエリを利用し、`userEvent` を使用して非同期のやり取りを行い、MSW を使用してネットワークのモッキングを行うことで、全体的なアプリケーションの安定性とアクセシビリティを高める","ko":"에이전트가 강력한 테스트를 작성할 수 있도록 하여 사용자 행동에 중점을 두고, `getByRole`, `getByText`, `getByTestId` 쿼리를 사용하며, `userEvent`를 사용하여 비동기 상호작용과 MSW를 사용하여 네트워크 모의를 수행함으로써 전체 애플리케이션의 안정성과 접근성을 향상시킵니다","es":"Habilita a los agentes a escribir pruebas sólidas centradas en el comportamiento del usuario, utilizando consultas `getByRole`, `getByText` y `getByTestId`, mientras aprovecha `userEvent` para interacciones asíncronas y MSW para la simulación de red, mejorando así la estabilidad y accesibilidad generales de la aplicación","fr":"Permet aux agents d''écrire des tests solides axés sur le comportement de l''utilisateur, en utilisant des requêtes `getByRole`, `getByText` et `getByTestId`, tout en exploitant `userEvent` pour les interactions asynchrones et MSW pour la simulation du réseau, améliorant ainsi la stabilité et l''accessibilité générales de l''application","de":"Ermächtigt Agents, robuste Tests zu schreiben, die sich auf das Benutzerverhalten konzentrieren, indem sie Abfragen wie `getByRole`, `getByText` und `getByTestId` verwenden und `userEvent` für asynchrone Interaktionen und MSW für Netzwerksimulation nutzen, wodurch die Gesamstabilität und -zugänglichkeit der Anwendung verbessert wird","pt":"Habilita os agentes a escrever testes robustos, focando no comportamento do usuário, utilizando consultas `getByRole`, `getByText` e `getByTestId`, ao mesmo tempo em que aproveita `userEvent` para interações assíncronas e MSW para simulação de rede, melhorando assim a estabilidade e a acessibilidade geral do aplicativo","ru":"Наделяет агентов возможностью писать прочные тесты, фокусируясь на поведении пользователя, используя запросы `getByRole`, `getByText` и `getByTestId`, а также использует `userEvent` для асинхронных взаимодействий и MSW для имитации сети, тем самым повышая общую стабильность и доступность приложения","ar":"تمكين الوكيل من كتابة اختبارات قوية تركز على سلوك المستخدم، باستخدام استفسارات `getByRole` و `getByText` و `getByTestId`، وفي الوقت نفسه الاستفادة من `userEvent` للتفاعلات غير المتزامنة و MSW لمحاكاة الشبكة، مما يحسن من الاستقرار والإمكانية العامة للتطبيق"},"useCases":{"en":["Writing tests for complex React components","Debugging issues with async updates using `await screen.findBy*`","Implementing accessibility testing with React Testing Library"],"zh":["编写复杂 React 组件的测试","使用 `await screen.findBy*` 调试异步更新问题","使用 React Testing Library 实现可访问性测试"],"ja":["複雑な React コンポーネントのテストを記述する","`await screen.findBy*` を使用して非同期の更新に関する問題をデバッグする","React Testing Library を使用してアクセシビリティ テストを実装する"],"ko":["복잡한 React 컴포넌트에 대한 테스트 작성","`await screen.findBy*`를 사용하여 비동기 업데이트 문제 디버깅","React Testing Library를 사용하여 접근성 테스트 구현"],"es":["Escribir pruebas para componentes React complejos","Depurar problemas con actualizaciones asíncronas utilizando `await screen.findBy*`","Implementar pruebas de accesibilidad con React Testing Library"],"fr":["Écrire des tests pour des composants React complexes","Déboguer des problèmes avec des mises à jour asynchrones en utilisant `await screen.findBy*`","Mettre en œuvre des tests d''accessibilité avec React Testing Library"],"de":["Schreiben von Tests für komplexe React-Komponenten","Beheben von Problemen mit asynchronen Updates unter Verwendung von `await screen.findBy*`","Implementierung von Zugriffstests mit React Testing Library"],"pt":["Escrita de testes para componentes React complexos","Depuração de problemas com atualizações assíncronas usando `await screen.findBy*`","Implementação de testes de acessibilidade com React Testing Library"],"ru":["Написание тестов для сложных компонентов React","Отладка проблем с асинхронными обновлениями с помощью `await screen.findBy*`","Реализация тестирования доступности с помощью React Testing Library"],"ar":["كتابة اختبارات لمكونات React معقدة","تصحيح الأخطاء المتعلقة بالتحديثات غير المتزامنة باستخدام `await screen.findBy*`","تنفيذ اختبارات إمكانية الوصول باستخدام مكتبة اختبار React"]},"limitations":{"en":["Requires React Testing Library and Vitest setup","Limited to React applications","Needs MSW for network mocking"],"zh":["需要 React Testing Library 和 Vitest 设置","仅限 React 应用","需要 MSW 进行网络模拟"],"ja":["React Testing Library と Vitest の設定が必要","React アプリケーションにのみ限る","ネットワークのモッキングには MSW が必要"],"ko":["React Testing Library와 Vitest 설정이 필요","React 애플리케이션에만 제한","네트워크 모의를 위해 MSW가 필요"],"es":["Requiere configuración de React Testing Library y Vitest","Limitado a aplicaciones React","Necesita MSW para la simulación de red"],"fr":["Nécessite une configuration de React Testing Library et Vitest","Limité aux applications React","Nécessite MSW pour la simulation du réseau"],"de":["Benötigt eine Konfiguration von React Testing Library und Vitest","Begrenzt auf React-Anwendungen","Benötigt MSW für die Netzwerksimulation"],"pt":["Requer configuração do React Testing Library e Vitest","Limitado a aplicações React","Necessita MSW para simulação de rede"],"ru":["Требует настройки React Testing Library и Vitest","Ограничен для приложений React","Требует MSW для имитации сети"],"ar":["يتطلب إعداد مكتبة اختبار React و Vitest","محدود للتطبيقات React","يحتاج إلى MSW لمحاكاة الشبكة"]},"version":3},"contentHash":"9a35bd3811f1f1bf4463abcf4fd2baeb5913e5565d1f4b1ca0bc86cdb63d074a","qualityScore":40}');
